static const proto::ProtoObject* py_frozenset_hash(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    const proto::ProtoSet* s = self->asSet(context);
    if (!s) return context->fromInteger(0);
    unsigned long h = 0x345678UL;
    const proto::ProtoSetIterator* it = s->getIterator(context);
    while (it && it->hasNext(context)) {
        const proto::ProtoObject* val = it->next(context);
        h ^= (val->getHash(context) + (h << 6) + (h >> 2));
        it = it->advance(context);
    }
    return context->fromInteger(static_cast<long long>(h));
}

static const proto::ProtoObject* py_frozenset_call(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    (void)parentLink;
    (void)keywordParameters;

    const proto::ProtoObject* cls = (positionalParameters && positionalParameters->getSize(context) > 0) ? positionalParameters->getAt(context, 0) : self;
    if (!cls) return PROTO_NONE;

    const proto::ProtoSet* acc = context->newSet();
    PythonEnvironment* env = PythonEnvironment::fromContext(context);

    if (positionalParameters && positionalParameters->getSize(context) >= 2) {
        const proto::ProtoObject* itObj = positionalParameters->getAt(context, 1);
        const proto::ProtoObject* it = env ? env->iter(itObj) : nullptr;
        if (it && it != PROTO_NONE) {
            for (;;) {
                const proto::ProtoObject* item = env->next(it);
                if (!item) {
                    if (env && env->handleExhaustion(context)) break;
                    break;
                }
                acc = acc->add(context, item);
            }
        }
    }

    proto::ProtoObject* fs = const_cast<proto::ProtoObject*>(context->newObject(true));
    fs->addParent(context, env->getFrozensetPrototype());
    if (cls != env->getFrozensetPrototype()) fs->addParent(context, cls);
    fs->setAttribute(context, env->getClassString(), cls);
    fs->setAttribute(context, env->getDataString(), acc->asObject(context));
    // Step V77: marker to ensure getType identifies it as an instance of its __class__
    fs->setAttribute(context, PythonEnvironment::getInternedString(context, "__is_python_class__"), PROTO_TRUE);
    
    if (get_env_diag()) {
        if (fs->hasAttribute(context, env->getClassString())) {
        } else {
        }
    }
    return fs;
}

static const proto::ProtoObject* py_int_format(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    long long v = self->asLong(context);
    char buf[32];
    snprintf(buf, sizeof(buf), "%lld", v);
    return PythonEnvironment::getInternedString(context, buf)->asObject(context);
}

static const proto::ProtoString* str_from_self(proto::ProtoContext* context, const proto::ProtoObject* self);
static const proto::ProtoString* str_from_self_or_arg(proto::ProtoContext* context,
        const proto::ProtoObject* self, const proto::ProtoList* posArgs,
        int* posOff = nullptr);

static const proto::ProtoObject* py_str_format_dunder(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    const proto::ProtoString* s = str_from_self(context, self);
    if (!s) return PROTO_NONE;
    return s->asObject(context);
}

static const proto::ProtoObject* py_int_bit_length(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList*, const proto::ProtoSparseList*) {
    if (self->integerSign(context) == 0) return context->fromInteger(0);
    // Bignum-safe: count via the absolute hex digit count, then refine
    // the most-significant nibble.
    const proto::ProtoString* hex = self->asIntegerString(context, 16);
    std::string s;
    hex->toUTF8String(context, s);
    if (!s.empty() && s[0] == '-') s.erase(0, 1);
    if (s.empty()) return context->fromInteger(0);
    long long bits = static_cast<long long>(s.size() - 1) * 4;
    char top = s[0];
    int topVal = (top >= '0' && top <= '9') ? (top - '0')
              : (top >= 'a' && top <= 'f') ? (top - 'a' + 10)
              : (top >= 'A' && top <= 'F') ? (top - 'A' + 10) : 0;
    while (topVal) { bits++; topVal >>= 1; }
    return context->fromInteger(bits);
}

static const proto::ProtoObject* py_int_bit_count(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList*, const proto::ProtoSparseList*) {
    // CPython treats negatives as if abs(n): bit_count(-7) == bit_count(7) == 3.
    const proto::ProtoObject* mag = self->abs(context);
    const proto::ProtoString* hex = mag->asIntegerString(context, 16);
    std::string s;
    hex->toUTF8String(context, s);
    if (!s.empty() && s[0] == '-') s.erase(0, 1);
    long long count = 0;
    for (char c : s) {
        int v = (c >= '0' && c <= '9') ? (c - '0')
              : (c >= 'a' && c <= 'f') ? (c - 'a' + 10)
              : (c >= 'A' && c <= 'F') ? (c - 'A' + 10) : 0;
        while (v) { count += (v & 1); v >>= 1; }
    }
    return context->fromInteger(count);
}

// Helper: pull a long long from `obj`, walking __data__ for int subclass
// instances that wrap a SmallInteger.  Returns nullptr-equivalent (sets
// *out=0 and returns false) when obj isn't int-like.
static bool int_value(proto::ProtoContext* ctx, const proto::ProtoObject* obj, long long* out) {
    if (!obj) return false;
    const proto::ProtoObject* iv = nullptr;
    if (obj->isInteger(ctx)) iv = obj;
    else if (obj->isBoolean(ctx)) {
        *out = (obj == PROTO_TRUE) ? 1 : 0;
        return true;
    } else {
        PythonEnvironment* env = PythonEnvironment::fromContext(ctx);
        const proto::ProtoObject* data = obj->getAttribute(ctx,
            env ? env->getDataString() : PythonEnvironment::getInternalString(ctx, "__data__"));
        if (data && data->isInteger(ctx)) iv = data;
    }
    if (!iv) return false;
    try { *out = iv->asLong(ctx); return true; }
    catch (...) { return false; }
}

// Generic int arithmetic dunder.  Routes through env->binaryOp so big-num
// promotion / float fallback / dunder dispatch all match what
// OP_BINARY_* uses; returns NotImplemented for non-numeric RHS so the
// reflected dunder gets a chance.
//
// Supports both bound (self=int_value, args=[other]) and unbound
// (self=intPrototype/null, args=[int_value, other]) calling conventions
// — the latter is what `int.__add__(a, b)` produces.
static const proto::ProtoObject* py_int_arith(
    proto::ProtoContext* ctx, const proto::ProtoObject* self,
    const proto::ProtoList* posArgs, TokenType op) {
    PythonEnvironment* env = PythonEnvironment::fromContext(ctx);
    if (!posArgs) return PROTO_NONE;
    // Unwrap helper: takes any numeric carrier and returns its raw
    // SmallInt / Float / 0|1 (for bool).  Recognises wrapped
    // subclass-of-int / subclass-of-float instances by reading
    // __data__.  Returns the input unchanged if no numeric payload is
    // available — the caller decides how to handle non-numerics.
    auto unwrap = [&](const proto::ProtoObject* x) -> const proto::ProtoObject* {
        if (!x) return x;
        if (x == PROTO_TRUE) return ctx->fromInteger(1);
        if (x == PROTO_FALSE) return ctx->fromInteger(0);
        if (x->isInteger(ctx) || x->isFloat(ctx)) return x;
        if (env) {
            const proto::ProtoObject* d = x->getAttribute(ctx, env->getDataString());
            if (d) {
                if (d == PROTO_TRUE) return ctx->fromInteger(1);
                if (d == PROTO_FALSE) return ctx->fromInteger(0);
                if (d->isInteger(ctx) || d->isFloat(ctx)) return d;
            }
        }
        return x;
    };
    const proto::ProtoObject* unwrappedSelf = unwrap(self);
    bool selfIsIntInstance = unwrappedSelf
        && (unwrappedSelf->isInteger(ctx) || unwrappedSelf->isFloat(ctx));
    const proto::ProtoObject* a = nullptr;
    const proto::ProtoObject* b = nullptr;
    if (!selfIsIntInstance) {
        // Unbound dispatch: self is the class (intPrototype) or null;
        // the actual int receiver is args[0].
        if (posArgs->getSize(ctx) < 2) return env ? env->getNotImplementedPrototype() : PROTO_NONE;
        a = unwrap(posArgs->getAt(ctx, 0));
        b = unwrap(posArgs->getAt(ctx, 1));
    } else {
        if (posArgs->getSize(ctx) < 1) return PROTO_NONE;
        a = unwrappedSelf;
        b = unwrap(posArgs->getAt(ctx, 0));
    }
    if (!a || !b) return PROTO_NONE;
    bool lhsNumeric = a->isInteger(ctx) || a->isFloat(ctx);
    bool rhsNumeric = b->isInteger(ctx) || b->isFloat(ctx);
    if (!lhsNumeric || !rhsNumeric) {
        return env ? env->getNotImplementedPrototype() : PROTO_NONE;
    }
    // Compute directly using primitive arithmetic — calling back into
    // env->binaryOp would re-enter binaryAdd → binaryOpDispatch and loop
    // forever for "1 + E(int_subclass)".
    switch (op) {
        case TokenType::Plus:   return a->add(ctx, b);
        case TokenType::Minus:  return a->subtract(ctx, b);
        case TokenType::Star:   return a->multiply(ctx, b);
        case TokenType::Slash: {
            // True division: coerce to float.
            double lhs = a->isInteger(ctx) ? (double)a->asLong(ctx) : a->asDouble(ctx);
            double rhs = b->isInteger(ctx) ? (double)b->asLong(ctx) : b->asDouble(ctx);
            if (rhs == 0.0) {
                if (env) env->raiseZeroDivisionError(ctx);
                return nullptr;
            }
            return ctx->fromDouble(lhs / rhs);
        }
        case TokenType::Modulo: return a->modulo(ctx, b);
        case TokenType::DoubleSlash: {
            // Floor division.  Both operands int: integer floor; either
            // is float: floor of the true division.
            if (a->isInteger(ctx) && b->isInteger(ctx)) {
                long long lhs = a->asLong(ctx);
                long long rhs = b->asLong(ctx);
                if (rhs == 0) {
                    if (env) env->raiseZeroDivisionError(ctx);
                    return nullptr;
                }
                long long q = lhs / rhs;
                if ((lhs ^ rhs) < 0 && q * rhs != lhs) --q; // round toward -inf
                return ctx->fromInteger(q);
            }
            double lhs = a->isInteger(ctx) ? (double)a->asLong(ctx) : a->asDouble(ctx);
            double rhs = b->isInteger(ctx) ? (double)b->asLong(ctx) : b->asDouble(ctx);
            if (rhs == 0.0) {
                if (env) env->raiseZeroDivisionError(ctx);
                return nullptr;
            }
            return ctx->fromDouble(std::floor(lhs / rhs));
        }
        case TokenType::LShift: {
            if (!a->isInteger(ctx) || !b->isInteger(ctx)) {
                return env ? env->getNotImplementedPrototype() : PROTO_NONE;
            }
            long long lhs = a->asLong(ctx);
            long long rhs = b->asLong(ctx);
            if (rhs < 0) {
                if (env) env->raiseValueError(ctx,
                    PythonEnvironment::getInternedString(ctx, "negative shift count")->asObject(ctx));
                return nullptr;
            }
            long long out = (rhs >= 64) ? 0 : static_cast<long long>(static_cast<unsigned long long>(lhs) << rhs);
            return ctx->fromInteger(out);
        }
        case TokenType::RShift: {
            if (!a->isInteger(ctx) || !b->isInteger(ctx)) {
                return env ? env->getNotImplementedPrototype() : PROTO_NONE;
            }
            long long lhs = a->asLong(ctx);
            long long rhs = b->asLong(ctx);
            if (rhs < 0) {
                if (env) env->raiseValueError(ctx,
                    PythonEnvironment::getInternedString(ctx, "negative shift count")->asObject(ctx));
                return nullptr;
            }
            long long out = (rhs >= 64) ? (lhs < 0 ? -1 : 0) : (lhs >> rhs);
            return ctx->fromInteger(out);
        }
        case TokenType::BitAnd: return a->bitwiseAnd(ctx, b);
        case TokenType::BitOr:  return a->bitwiseOr(ctx, b);
        case TokenType::BitXor: return a->bitwiseXor(ctx, b);
        default: return env ? env->getNotImplementedPrototype() : PROTO_NONE;
    }
}

