// int.__lt__/__le__/__gt__/__ge__/__eq__/__ne__: comparison dunders
// missing from intPrototype.  Returns NotImplemented when the other
// operand isn't numeric (CPython parity), otherwise the boolean
// result of the requested comparison.
enum class IntCmp { Lt, Le, Gt, Ge, Eq, Ne };
static const proto::ProtoObject* py_int_cmp(
    proto::ProtoContext* ctx, const proto::ProtoObject* self,
    const proto::ProtoList* args, IntCmp op) {
    PythonEnvironment* env = PythonEnvironment::fromContext(ctx);
    if (!args) return PROTO_NONE;
    auto unwrap = [&](const proto::ProtoObject* x) -> const proto::ProtoObject* {
        if (!x) return x;
        if (x == PROTO_TRUE) return ctx->fromInteger(1);
        if (x == PROTO_FALSE) return ctx->fromInteger(0);
        if (x->isInteger(ctx) || x->isFloat(ctx)) return x;
        if (env) {
            const proto::ProtoObject* d = x->getAttribute(ctx, env->getDataString());
            if (d) {
                if (d == PROTO_TRUE) return ctx->fromInteger(1);
                if (d == PROTO_FALSE) return ctx->fromInteger(0);
                if (d->isInteger(ctx) || d->isFloat(ctx)) return d;
            }
        }
        return x;
    };
    const proto::ProtoObject* unwrappedSelf = unwrap(self);
    bool selfIsIntInstance = unwrappedSelf
        && (unwrappedSelf->isInteger(ctx) || unwrappedSelf->isFloat(ctx));
    const proto::ProtoObject* a = nullptr;
    const proto::ProtoObject* b = nullptr;
    if (!selfIsIntInstance) {
        if (args->getSize(ctx) < 2) return env ? env->getNotImplementedPrototype() : PROTO_NONE;
        a = unwrap(args->getAt(ctx, 0));
        b = unwrap(args->getAt(ctx, 1));
    } else {
        if (args->getSize(ctx) < 1) return PROTO_NONE;
        a = unwrappedSelf;
        b = unwrap(args->getAt(ctx, 0));
    }
    if (!a || !b) return PROTO_NONE;
    bool lhsNumeric = a->isInteger(ctx) || a->isFloat(ctx);
    bool rhsNumeric = b->isInteger(ctx) || b->isFloat(ctx);
    if (!lhsNumeric || !rhsNumeric) {
        return env ? env->getNotImplementedPrototype() : PROTO_NONE;
    }
    int cmp = a->compare(ctx, b);  // -1, 0, 1
    bool result = false;
    switch (op) {
        case IntCmp::Lt: result = cmp <  0; break;
        case IntCmp::Le: result = cmp <= 0; break;
        case IntCmp::Gt: result = cmp >  0; break;
        case IntCmp::Ge: result = cmp >= 0; break;
        case IntCmp::Eq: result = cmp == 0; break;
        case IntCmp::Ne: result = cmp != 0; break;
    }
    return result ? PROTO_TRUE : PROTO_FALSE;
}
static const proto::ProtoObject* py_int_lt(proto::ProtoContext* c, const proto::ProtoObject* s, const proto::ParentLink*, const proto::ProtoList* a, const proto::ProtoSparseList*) { return py_int_cmp(c, s, a, IntCmp::Lt); }
static const proto::ProtoObject* py_int_le(proto::ProtoContext* c, const proto::ProtoObject* s, const proto::ParentLink*, const proto::ProtoList* a, const proto::ProtoSparseList*) { return py_int_cmp(c, s, a, IntCmp::Le); }
static const proto::ProtoObject* py_int_gt(proto::ProtoContext* c, const proto::ProtoObject* s, const proto::ParentLink*, const proto::ProtoList* a, const proto::ProtoSparseList*) { return py_int_cmp(c, s, a, IntCmp::Gt); }
static const proto::ProtoObject* py_int_ge(proto::ProtoContext* c, const proto::ProtoObject* s, const proto::ParentLink*, const proto::ProtoList* a, const proto::ProtoSparseList*) { return py_int_cmp(c, s, a, IntCmp::Ge); }
static const proto::ProtoObject* py_int_eq(proto::ProtoContext* c, const proto::ProtoObject* s, const proto::ParentLink*, const proto::ProtoList* a, const proto::ProtoSparseList*) { return py_int_cmp(c, s, a, IntCmp::Eq); }
static const proto::ProtoObject* py_int_ne(proto::ProtoContext* c, const proto::ProtoObject* s, const proto::ParentLink*, const proto::ProtoList* a, const proto::ProtoSparseList*) { return py_int_cmp(c, s, a, IntCmp::Ne); }

// int.__pow__(self, exp[, mod]): exponentiation. Negative exp returns float
// (matches CPython 3.x). With mod, computes modular exponentiation.
static const proto::ProtoObject* py_int_pow(
    proto::ProtoContext* ctx, const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* args, const proto::ProtoSparseList*) {
    if (!args) return PROTO_NONE;
    PythonEnvironment* env = PythonEnvironment::fromContext(ctx);
    long long base, exp, mod = 0;
    // Bound form: self is the base, args=[exp[, mod]].
    // Unbound form: self is intPrototype/null, args=[base, exp[, mod]].
    // Wrapped subclass-of-int instance also counts as a bound receiver:
    // its integer payload lives in __data__; int_value() unwraps both
    // SmallInt and __data__ so we just need to check whether self can
    // be coerced to int.
    long long selfIntProbe;
    bool selfIsIntInstance = self
        && (self->isInteger(ctx) || self->isBoolean(ctx)
            || int_value(ctx, self, &selfIntProbe));
    int expIdx, modIdx;
    if (selfIsIntInstance) {
        // CPython: int.__pow__ accepts 1 or 2 arguments (exp[, mod]).
        // Earlier this returned PROTO_NONE silently when the count was
        // wrong, hiding the misuse from `assertRaisesRegex(TypeError,
        // 'expected 1 or 2 arguments, got 0', int().__pow__)`.
        unsigned long n = args->getSize(ctx);
        if (n < 1 || n > 2) {
            if (env) {
                env->raiseTypeError(ctx,
                    "expected 1 or 2 arguments, got " + std::to_string(n));
            }
            return nullptr;
        }
        if (!int_value(ctx, self, &base)) {
            return env ? env->getNotImplementedPrototype() : PROTO_NONE;
        }
        expIdx = 0;
        modIdx = 1;
    } else {
        if (args->getSize(ctx) < 2) return env ? env->getNotImplementedPrototype() : PROTO_NONE;
        if (!int_value(ctx, args->getAt(ctx, 0), &base)) {
            return env ? env->getNotImplementedPrototype() : PROTO_NONE;
        }
        expIdx = 1;
        modIdx = 2;
    }
    bool hasMod = (args->getSize(ctx) > (unsigned long)modIdx && args->getAt(ctx, modIdx) != PROTO_NONE);
    if (!int_value(ctx, args->getAt(ctx, expIdx), &exp)) {
        return env ? env->getNotImplementedPrototype() : PROTO_NONE;
    }
    if (hasMod) {
        if (!int_value(ctx, args->getAt(ctx, modIdx), &mod) || mod == 0) {
            return env ? env->getNotImplementedPrototype() : PROTO_NONE;
        }
    }
    // Negative exp without mod → float result.
    if (exp < 0 && !hasMod) {
        double r = std::pow(static_cast<double>(base), static_cast<double>(exp));
        return ctx->fromDouble(r);
    }
    // Iterative exponentiation by squaring.  Long-long overflow is benign
    // for the typical test usage (small exponents); CPython does bignum
    // here, which we'd need fromString to cover but isn't needed for the
    // current test_descr coverage.
    long long result = 1;
    long long b = base;
    long long e = exp < 0 ? -exp : exp;
    while (e > 0) {
        if (e & 1) {
            result = hasMod ? (result * b) % mod : result * b;
        }
        e >>= 1;
        if (e) {
            b = hasMod ? (b * b) % mod : b * b;
        }
    }
    if (hasMod && result < 0) result += mod;
    return ctx->fromInteger(result);
}

// int.__rpow__(self, other[, mod]): equivalent to other ** self with the
// same arity validation that __pow__ has.  test_pow_wrapper_error_messages
// asserts identical error messages.
static const proto::ProtoObject* py_int_rpow(
    proto::ProtoContext* ctx, const proto::ProtoObject* self,
    const proto::ParentLink* link, const proto::ProtoList* args, const proto::ProtoSparseList* kwargs) {
    PythonEnvironment* env = PythonEnvironment::fromContext(ctx);
    long long rpowProbe;
    bool selfIsIntInstance = self
        && (self->isInteger(ctx) || self->isBoolean(ctx)
            || int_value(ctx, self, &rpowProbe));
    if (selfIsIntInstance) {
        unsigned long n = args ? args->getSize(ctx) : 0UL;
        if (n < 1 || n > 2) {
            if (env) {
                env->raiseTypeError(ctx,
                    "expected 1 or 2 arguments, got " + std::to_string(n));
            }
            return nullptr;
        }
        // Reflected: other ** self.  Re-route as py_int_pow with a
        // synthetic call site where `self` becomes args[0] (the LHS we're
        // reflecting from) and exp becomes the original self.
        const proto::ProtoObject* other = args->getAt(ctx, 0);
        const proto::ProtoList* newArgs = ctx->newList()->appendLast(ctx, self);
        if (n == 2) newArgs = newArgs->appendLast(ctx, args->getAt(ctx, 1));
        return py_int_pow(ctx, other, link, newArgs, kwargs);
    }
    // Unbound int.__rpow__(other, self[, mod])
    if (!args || args->getSize(ctx) < 2) {
        return env ? env->getNotImplementedPrototype() : PROTO_NONE;
    }
    return py_int_pow(ctx, args->getAt(ctx, 1), link,
        ([&]() {
            const proto::ProtoList* newArgs = ctx->newList()->appendLast(ctx, args->getAt(ctx, 0));
            if (args->getSize(ctx) >= 3) newArgs = newArgs->appendLast(ctx, args->getAt(ctx, 2));
            return newArgs;
        })(),
        kwargs);
}

// Reflected versions: int.__radd__(self, other) is equivalent to other + self,
// invoked when other.__add__(self) returned NotImplemented.  CPython's
// nb_add / nb_radd slots — protoPython's binaryOp already handles
// commutativity for ints, so the reflected impl just swaps operands.
// Reflected operator dispatch — must NOT re-enter env->binaryOp because
// that re-runs the dispatcher (binaryAdd → binaryOpDispatch → ...) and
// the result of `1.__radd__(SubclassInstance)` is itself dispatched via
// __radd__ when the forward path returned NotImplemented, producing an
// infinite recursion. Same pattern as #89's py_int_arith fix.
//
// Compute the result with primitive arithmetic: this method is called
// only via int.__radd__ / int.__rmul__, so `self` is always an exact
// int (or bool); `other` is the LHS that the reflected op handles
// (commonly an int subclass with __data__ holding the underlying int).
static const proto::ProtoObject* py_int_radd(
    proto::ProtoContext* ctx, const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* args, const proto::ProtoSparseList*) {
    if (!args || args->getSize(ctx) < 1) return PROTO_NONE;
    PythonEnvironment* env = PythonEnvironment::fromContext(ctx);
    auto unwrap = [&](const proto::ProtoObject* x) -> const proto::ProtoObject* {
        if (!x) return x;
        if (x == PROTO_TRUE) return ctx->fromInteger(1);
        if (x == PROTO_FALSE) return ctx->fromInteger(0);
        if (x->isInteger(ctx) || x->isFloat(ctx)) return x;
        if (env) {
            const proto::ProtoObject* d = x->getAttribute(ctx, env->getDataString());
            if (d) {
                if (d == PROTO_TRUE) return ctx->fromInteger(1);
                if (d == PROTO_FALSE) return ctx->fromInteger(0);
                if (d->isInteger(ctx) || d->isFloat(ctx)) return d;
            }
        }
        return x;
    };
    const proto::ProtoObject* other = unwrap(args->getAt(ctx, 0));
    const proto::ProtoObject* selfNum = unwrap(self);
    if (!other || (!other->isInteger(ctx) && !other->isFloat(ctx))
        || !selfNum || (!selfNum->isInteger(ctx) && !selfNum->isFloat(ctx))) {
        return env ? env->getNotImplementedPrototype() : PROTO_NONE;
    }
    return other->add(ctx, selfNum);
}
static const proto::ProtoObject* py_int_rmul(
    proto::ProtoContext* ctx, const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* args, const proto::ProtoSparseList*) {
    if (!args || args->getSize(ctx) < 1) return PROTO_NONE;
    PythonEnvironment* env = PythonEnvironment::fromContext(ctx);
    auto unwrap = [&](const proto::ProtoObject* x) -> const proto::ProtoObject* {
        if (!x) return x;
        if (x == PROTO_TRUE) return ctx->fromInteger(1);
        if (x == PROTO_FALSE) return ctx->fromInteger(0);
        if (x->isInteger(ctx) || x->isFloat(ctx)) return x;
        if (env) {
            const proto::ProtoObject* d = x->getAttribute(ctx, env->getDataString());
            if (d) {
                if (d == PROTO_TRUE) return ctx->fromInteger(1);
                if (d == PROTO_FALSE) return ctx->fromInteger(0);
                if (d->isInteger(ctx) || d->isFloat(ctx)) return d;
            }
        }
        return x;
    };
    const proto::ProtoObject* other = unwrap(args->getAt(ctx, 0));
    const proto::ProtoObject* selfNum = unwrap(self);
    if (!other || (!other->isInteger(ctx) && !other->isFloat(ctx))
        || !selfNum || (!selfNum->isInteger(ctx) && !selfNum->isFloat(ctx))) {
        return env ? env->getNotImplementedPrototype() : PROTO_NONE;
    }
    return other->multiply(ctx, selfNum);
}

// Resolve (selfStr, otherIdx) for both bound (str(...).__add__(other)) and
// unbound (str.__add__(s, other)) calling conventions on string dunders.
static const proto::ProtoObject* str_method_self(
    proto::ProtoContext* ctx, const proto::ProtoObject* self,
    const proto::ProtoList* args, int* otherIdx) {
    bool selfIsStr = self && self->isString(ctx);
    if (selfIsStr) { *otherIdx = 0; return self; }
    if (args && args->getSize(ctx) >= 1) {
        const proto::ProtoObject* a0 = args->getAt(ctx, 0);
        if (a0 && a0->isString(ctx)) { *otherIdx = 1; return a0; }
    }
    return nullptr;
}

// String concatenation: str.__add__(self, other). CPython requires both
// sides to be str — non-string operand returns NotImplemented so the
// reflected dunder gets a chance. Accepts both bound and unbound dispatch.
static const proto::ProtoObject* py_str_add(
    proto::ProtoContext* ctx, const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* args, const proto::ProtoSparseList*) {
    PythonEnvironment* env = PythonEnvironment::fromContext(ctx);
    int otherIdx;
    const proto::ProtoObject* a = str_method_self(ctx, self, args, &otherIdx);
    if (!a) return env ? env->getNotImplementedPrototype() : PROTO_NONE;
    if (!args || args->getSize(ctx) <= (unsigned long)otherIdx) return PROTO_NONE;
    const proto::ProtoObject* other = args->getAt(ctx, otherIdx);
    if (!other || !other->isString(ctx)) {
        return env ? env->getNotImplementedPrototype() : PROTO_NONE;
    }
    std::string sa, sb;
    a->asString(ctx)->toUTF8String(ctx, sa);
    other->asString(ctx)->toUTF8String(ctx, sb);
    return PythonEnvironment::getInternedString(ctx, (sa + sb).c_str())->asObject(ctx);
}

// String repetition: str.__mul__(self, count). count must be int (or bool).
// Accepts both bound and unbound dispatch.
static const proto::ProtoObject* py_str_mul(
    proto::ProtoContext* ctx, const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* args, const proto::ProtoSparseList*) {
    PythonEnvironment* env = PythonEnvironment::fromContext(ctx);
    int otherIdx;
    const proto::ProtoObject* a = str_method_self(ctx, self, args, &otherIdx);
    if (!a) return env ? env->getNotImplementedPrototype() : PROTO_NONE;
    if (!args || args->getSize(ctx) <= (unsigned long)otherIdx) return PROTO_NONE;
    const proto::ProtoObject* other = args->getAt(ctx, otherIdx);
    long long n = 0;
    if (other && other->isInteger(ctx)) {
        try { n = other->asLong(ctx); } catch (...) { n = 0; }
    } else if (other && other->isBoolean(ctx)) {
        n = (other == PROTO_TRUE) ? 1 : 0;
    } else {
        // Subclass-of-int instance: read __data__ payload directly so
        // `"a" * MyInt(2)` produces "aa" (test_dynamics).  Walk the
        // value's MRO looking for intPrototype before resorting to
        // NotImplemented.
        bool unwrapped = false;
        if (env && other) {
            const proto::ProtoObject* otCls = env->getType(ctx, other);
            const proto::ProtoObject* otMro = otCls ? otCls->getAttribute(ctx, env->getMroString()) : nullptr;
            const proto::ProtoTuple* otMroT = otMro ? otMro->asTuple(ctx) : nullptr;
            bool subOfInt = false;
            if (otMroT && env->getIntPrototype()) {
                for (unsigned long i = 0; i < otMroT->getSize(ctx); ++i) {
                    if (otMroT->getAt(ctx, static_cast<int>(i)) == env->getIntPrototype()) {
                        subOfInt = true;
                        break;
                    }
                }
            }
            if (subOfInt) {
                const proto::ProtoObject* d = other->getAttribute(ctx, env->getDataString());
                if (d && d->isInteger(ctx)) {
                    try { n = d->asLong(ctx); unwrapped = true; }
                    catch (...) { n = 0; unwrapped = true; }
                } else if (d == PROTO_TRUE) { n = 1; unwrapped = true; }
                else if (d == PROTO_FALSE) { n = 0; unwrapped = true; }
            }
        }
        if (!unwrapped) {
            return env ? env->getNotImplementedPrototype() : PROTO_NONE;
        }
    }
    std::string s;
    a->asString(ctx)->toUTF8String(ctx, s);
    if (n <= 0) return PythonEnvironment::getInternedString(ctx, "")->asObject(ctx);
    std::string out;
    out.reserve(s.size() * static_cast<size_t>(n));
    for (long long i = 0; i < n; ++i) out += s;
    return PythonEnvironment::getInternedString(ctx, out.c_str())->asObject(ctx);
}

static const proto::ProtoObject* py_float_hash(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList*, const proto::ProtoSparseList*) {
    // Extract the underlying double — direct or via __data__ (subclass).
    double v = 0.0;
    bool got = false;
    if (self->isFloat(context)) { v = self->asDouble(context); got = true; }
    else if (self->isInteger(context)) { v = static_cast<double>(self->asLong(context)); got = true; }
    else {
        PythonEnvironment* env = PythonEnvironment::fromContext(context);
        const proto::ProtoObject* data = self->getAttribute(context,
            env ? env->getDataString() : PythonEnvironment::getInternalString(context, "__data__"));
        if (data) {
            if (data->isFloat(context)) { v = data->asDouble(context); got = true; }
            else if (data->isInteger(context)) { v = static_cast<double>(data->asLong(context)); got = true; }
        }
    }
    if (!got) return context->fromInteger(0);
    // CPython: integer-valued floats hash the same as the int.  We only
    // hit the integer-equivalence path here; non-integral floats fall
    // through to a deterministic value-based hash (the bit pattern).
    if (v == (double)(long long)v && !std::isnan(v) && !std::isinf(v)) {
        long long iv = (long long)v;
        if (iv == -1) return context->fromInteger(-2);
        return context->fromInteger(iv);
    }
    // Non-integer: hash from the IEEE 754 bit pattern with a small tweak.
    union { double d; unsigned long long u; } pun;
    pun.d = v;
    long long h = static_cast<long long>(pun.u);
    if (h == -1) h = -2;
    return context->fromInteger(h);
}

static const proto::ProtoObject* py_int_hash(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList*, const proto::ProtoSparseList*) {
    const proto::ProtoObject* intObj = nullptr;
    if (self->isInteger(context)) {
        intObj = self;
    } else {
        PythonEnvironment* env = PythonEnvironment::fromContext(context);
        const proto::ProtoObject* data = self->getAttribute(context, env ? env->getDataString() : PythonEnvironment::getInternalString(context, "__data__"));
        if (data && data->isInteger(context)) intObj = data;
    }
    if (!intObj) return context->fromInteger(0);
    // Fast path: SmallInteger fits in long long — hash is the value itself
    // (CPython matches int's value when it fits).
    try {
        long long v = intObj->asLong(context);
        // CPython: hash(-1) == -2 to keep -1 reserved as the error marker.
        if (v == -1) return context->fromInteger(-2);
        return context->fromInteger(v);
    } catch (const std::overflow_error&) {
        // Bignum: hash via its digits modulo a large prime.  This keeps
        // `hash(n) == hash(n)` stable without overflowing long long.
        // Use Python's PyHASH_MODULUS (2^61 - 1) equivalent simplified:
        // fold the decimal digit string through FNV-1a.
        const proto::ProtoString* s = intObj->asIntegerString(context, 16);
        std::string digits;
        s->toUTF8String(context, digits);
        unsigned long long h = 14695981039346656037ULL; // FNV-1a offset
        for (char c : digits) {
            h ^= static_cast<unsigned long long>(static_cast<unsigned char>(c));
            h *= 1099511628211ULL; // FNV-1a prime
        }
        long long signed_h = static_cast<long long>(h);
        if (signed_h == -1) signed_h = -2;
        return context->fromInteger(signed_h);
    }
}

// --- Bytes backing-store helpers (Y-round) ---------------------------------
//
// `bytes` instances historically stored their content in the `__data__`
// attribute as a ProtoString (a Unicode string).  That representation
// silently corrupted bytes >= 0x80 (re-encoded as UTF-8) and truncated
// at embedded 0x00.  The Y-round migrates `bytes` to use ProtoByteBuffer
// (an opaque octet array) for new construction while keeping the
// ProtoString path readable for backward compatibility with existing
// `__data__` assignments throughout the codebase.

// Read a bytes-like object's raw octets into `out`.  Accepts:
//   - native ProtoString      (legacy; re-emit as UTF-8 bytes)
//   - bytes/bytearray instance (look up __data__ which may be either
//                               a ProtoByteBuffer or a ProtoString)
// Returns true on success.
static bool bytes_view(proto::ProtoContext* context,
                       const proto::ProtoObject* obj,
                       std::string& out) {
    if (!obj) return false;
    if (obj->isString(context)) {
        out.clear();
        obj->asString(context)->toUTF8String(context, out);
        return true;
    }
    if (obj->isByteBuffer(context)) {
        const proto::ProtoByteBuffer* bb = obj->asByteBuffer(context);
        unsigned long n = bb->getSize(context);
        out.assign(bb->getBuffer(context), n);
        return true;
    }
    // memoryview: __mv_data__ holds the underlying bytes / bytearray
    // / ByteBuffer. Recurse so callers (bytes.maketrans / translate
    // / etc.) accept memoryview altchars correctly.
    const proto::ProtoObject* mv = obj->getAttribute(context,
        PythonEnvironment::getInternalString(context, "__mv_data__"));
    if (mv && mv != PROTO_NONE && mv != obj) {
        return bytes_view(context, mv, out);
    }
    const proto::ProtoObject* data = obj->getAttribute(context,
        PythonEnvironment::getInternalString(context, "__data__"));
    if (data && data != PROTO_NONE) {
        if (data->isByteBuffer(context)) {
            const proto::ProtoByteBuffer* bb = data->asByteBuffer(context);
            unsigned long n = bb->getSize(context);
            out.assign(bb->getBuffer(context), n);
            return true;
        }
        if (data->isString(context)) {
            out.clear();
            data->asString(context)->toUTF8String(context, out);
            return true;
        }
    }
    // array.array exposes raw octets via `_data` (the lib's own
    // attribute) and via `tobytes()` (the public buffer-protocol
    // bridge). Both are recursive — the inner value is a bytes
    // wrapper or ProtoString that the cases above will accept.
    const proto::ProtoObject* underData = obj->getAttribute(context,
        PythonEnvironment::getInternalString(context, "_data"));
    if (underData && underData != PROTO_NONE && underData != obj) {
        return bytes_view(context, underData, out);
    }
    const proto::ProtoObject* tobytesM = obj->getAttribute(context,
        PythonEnvironment::getInternedString(context, "tobytes"));
    if (tobytesM && tobytesM != PROTO_NONE && tobytesM->asMethod(context)) {
        const proto::ProtoObject* res = tobytesM->asMethod(context)(context,
            const_cast<proto::ProtoObject*>(obj),
            nullptr, context->newList(), nullptr);
        if (res && res != obj) return bytes_view(context, res, out);
    }
    return false;
}

// Construct a fresh `bytes` instance whose `__data__` is a
// ProtoByteBuffer holding the given raw octets.  Bytes 0..255 round-trip
// exactly (no UTF-8 reinterpretation, no truncation at 0x00).
static const proto::ProtoObject* bytes_make_object(proto::ProtoContext* context,
                                                    const char* data,
                                                    unsigned long len) {
    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    if (!env || !env->getBytesPrototype()) return PROTO_NONE;
    proto::ProtoObject* b = const_cast<proto::ProtoObject*>(
        env->getBytesPrototype()->newChild(context, true));
    const proto::ProtoByteBuffer* bb = context->newByteBuffer(data, len);
    b->setAttribute(context,
        PythonEnvironment::getInternalString(context, "__data__"),
        bb->asObject(context));
    b->setAttribute(context,
        env->getClassString(),
        env->getBytesPrototype());
    return b;
}

static const proto::ProtoString* bytes_from_object(proto::ProtoContext* context, const proto::ProtoObject* obj) {
    // Legacy helper: returns a ProtoString view of a bytes-like object.
    // Used by callers that immediately call toUTF8String to get a
    // std::string.  For ProtoByteBuffer-backed bytes we synthesize a
    // ProtoString from the raw octets via fromUTF8Buffer (which accepts
    // any byte sequence, since UTF-8 is a superset of ASCII byte view
    // for our purposes — the resulting ProtoString may be lossy for
    // values >= 0x80, but that's a caller-side issue when they treat
    // the result as bytes).  New code should prefer bytes_view().
    if (!obj) return nullptr;
    if (obj->isString(context)) return obj->asString(context);
    if (obj->isByteBuffer(context)) {
        const proto::ProtoByteBuffer* bb = obj->asByteBuffer(context);
        uint8_t rem[4]; uint8_t remCount = 0;
        return proto::ProtoString::fromUTF8Buffer(context,
            reinterpret_cast<const uint8_t*>(bb->getBuffer(context)),
            bb->getSize(context),
            nullptr, 0, rem, &remCount);
    }
    const proto::ProtoObject* data = obj->getAttribute(context,
        PythonEnvironment::getInternalString(context, "__data__"));
    if (!data) return nullptr;
    if (data->isString(context)) return data->asString(context);
    if (data->isByteBuffer(context)) {
        const proto::ProtoByteBuffer* bb = data->asByteBuffer(context);
        uint8_t rem[4]; uint8_t remCount = 0;
        return proto::ProtoString::fromUTF8Buffer(context,
            reinterpret_cast<const uint8_t*>(bb->getBuffer(context)),
            bb->getSize(context),
            nullptr, 0, rem, &remCount);
    }
    return nullptr;
}

static const proto::ProtoObject* py_int_from_bytes(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList* kw) {
    (void)self;
    if (posArgs->getSize(context) < 1) return PROTO_NONE;
    std::string bytesStr;
    if (!bytes_view(context, posArgs->getAt(context, 0), bytesStr)) return PROTO_NONE;
    // byteorder defaults to 'big' (Python 3.11+); accept either positional
    // arg #1 or kwarg "byteorder". Falling back to 'big' silently is
    // critical because the std-lib base64._b32encode passes no byteorder.
    std::string byteorderStr = "big";
    if (posArgs->getSize(context) >= 2) {
        const proto::ProtoObject* bo = posArgs->getAt(context, 1);
        if (bo && bo->isString(context)) bo->asString(context)->toUTF8String(context, byteorderStr);
    } else if (kw) {
        const proto::ProtoString* bs = PythonEnvironment::getInternalString(context, "byteorder");
        if (bs && kw->has(context, bs->getHash(context))) {
            const proto::ProtoObject* bo = kw->getAt(context, bs->getHash(context));
            if (bo && bo->isString(context)) bo->asString(context)->toUTF8String(context, byteorderStr);
        }
    }
    bool little = (byteorderStr == "little");
    // Build the integer one byte at a time via shiftLeft + add,
    // so values larger than 64 bits are handled correctly.
    const proto::ProtoObject* result = context->fromInteger(0);
    auto consume = [&](unsigned char c) {
        result = result->shiftLeft(context, 8);
        result = result->add(context, context->fromInteger(c));
    };
    if (little) {
        for (size_t i = bytesStr.size(); i > 0; --i)
            consume(static_cast<unsigned char>(bytesStr[i - 1]));
    } else {
        for (unsigned char c : bytesStr) consume(c);
    }
    return result;
}

static const proto::ProtoObject* py_int_to_bytes(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList* kw) {
    if (posArgs->getSize(context) < 1) return PROTO_NONE;
    int length = static_cast<int>(posArgs->getAt(context, 0)->asLong(context));
    if (length < 0) length = 0;
    // byteorder defaults to 'big' (Python 3.11+); accept positional or kwarg.
    std::string byteorderStr = "big";
    if (posArgs->getSize(context) >= 2) {
        const proto::ProtoObject* bo = posArgs->getAt(context, 1);
        if (bo && bo->isString(context)) bo->asString(context)->toUTF8String(context, byteorderStr);
    } else if (kw) {
        const proto::ProtoString* bs = PythonEnvironment::getInternalString(context, "byteorder");
        if (bs && kw->has(context, bs->getHash(context))) {
            const proto::ProtoObject* bo = kw->getAt(context, bs->getHash(context));
            if (bo && bo->isString(context)) bo->asString(context)->toUTF8String(context, byteorderStr);
        }
    }
    bool little = (byteorderStr == "little");
    // Bignum-safe extraction: peel one byte at a time via & 0xff and >> 8.
    const proto::ProtoObject* mask = context->fromInteger(0xff);
    const proto::ProtoObject* cur = self->abs(context);
    std::string out;
    out.reserve(static_cast<size_t>(length));
    for (int i = 0; i < length; ++i) {
        const proto::ProtoObject* lowByte = cur->bitwiseAnd(context, mask);
        unsigned char byte = static_cast<unsigned char>(lowByte->asLong(context) & 0xff);
        out += static_cast<char>(byte);
        cur = cur->shiftRight(context, 8);
    }
    if (!little) std::reverse(out.begin(), out.end());
    // Backed by ProtoByteBuffer so all 256 byte values round-trip exactly.
    return bytes_make_object(context, out.data(), static_cast<unsigned long>(out.size()));
}

static const proto::ProtoObject* py_str_hash(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList*, const proto::ProtoSparseList*) {
    const proto::ProtoString* s = str_from_self(context, self);
    if (!s) return context->fromInteger(0);
    return context->fromInteger(static_cast<long long>(s->getHash(context)));
}

static const proto::ProtoObject* py_tuple_hash(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList*, const proto::ProtoSparseList*) {
    const proto::ProtoString* dataName = PythonEnvironment::getInternalString(context, "__data__");
    const proto::ProtoObject* data = self->getAttribute(context, dataName);
    if (!data || !data->asTuple(context)) return context->fromInteger(0);
    const proto::ProtoTuple* t = data->asTuple(context);
    unsigned long h = 0x345678UL;
    long n = static_cast<long>(t->getSize(context));
    for (long i = 0; i < n; ++i) {
        const proto::ProtoObject* el = t->getAt(context, static_cast<int>(i));
        h ^= (el ? el->getHash(context) : 0) + (h << 6) + (h >> 2);
    }
    return context->fromInteger(static_cast<long long>(h));
}

static const proto::ProtoObject* py_tuple_len(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    // Direct ProtoTuple (e.g. *args tuples created natively)
    if (self && self->asTuple(context)) return context->fromInteger(self->asTuple(context)->getSize(context));
    // Python-level tuple: data stored in __data__ attribute
    const proto::ProtoString* dataName = PythonEnvironment::getInternalString(context, "__data__");
    const proto::ProtoObject* data = self ? self->getAttribute(context, dataName) : nullptr;
    // Unbound form: `tuple.__len__((1,2,3))` — self is tuple type.
    if ((!data || !data->asTuple(context))
        && positionalParameters && positionalParameters->getSize(context) >= 1) {
        const proto::ProtoObject* candidate = positionalParameters->getAt(context, 0);
        if (candidate && candidate->asTuple(context)) {
            return context->fromInteger(candidate->asTuple(context)->getSize(context));
        }
        if (candidate) {
            const proto::ProtoObject* cd = candidate->getAttribute(context, dataName);
            if (cd && cd->asTuple(context)) data = cd;
        }
    }
    if (!data || !data->asTuple(context)) return context->fromInteger(0);
    return context->fromInteger(data->asTuple(context)->getSize(context));
}

static const proto::ProtoObject* py_dict_init(
    proto::ProtoContext* ctx,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* posArgs,
    const proto::ProtoSparseList* kwargs) {
    PythonEnvironment* env = PythonEnvironment::fromContext(ctx);
    if (!env || !self || self == PROTO_NONE) return PROTO_NONE;

    const proto::ProtoString* dataName = env->getDataString();
    const proto::ProtoString* keysName = env->getKeysString();

    // Helper: insert one (key, value) pair into self.
    auto insertPair = [&](const proto::ProtoObject* key, const proto::ProtoObject* val) {
        if (!key || !val) return;
        const proto::ProtoObject* dataObj = self->getAttribute(ctx, dataName);
        const proto::ProtoSparseList* dict = (dataObj && dataObj->asSparseList(ctx))
                                              ? dataObj->asSparseList(ctx) : ctx->newSparseList();
        unsigned long hash = key->getHash(ctx);
        bool hadKey = dict->has(ctx, hash);
        dict = dict->setAt(ctx, hash, val);
        const_cast<proto::ProtoObject*>(self)->setAttribute(ctx, dataName, dict->asObject(ctx));
        if (!hadKey) {
            const proto::ProtoObject* keysObj = self->getAttribute(ctx, keysName);
            const proto::ProtoList* keys = (keysObj && keysObj->asList(ctx))
                                            ? keysObj->asList(ctx) : ctx->newList();
            keys = keys->appendLast(ctx, key);
            const_cast<proto::ProtoObject*>(self)->setAttribute(ctx, keysName, keys->asObject(ctx));
        }
    };

    if (posArgs && posArgs->getSize(ctx) >= 1) {
        const proto::ProtoObject* arg = posArgs->getAt(ctx, 0);
        if (!arg || arg == PROTO_NONE) goto handle_kwargs;

        // If arg is a dict (has sparse __data__), copy entries directly.
        {
            const proto::ProtoObject* argData = (arg->hasOwnAttribute(ctx, dataName) == PROTO_TRUE)
                                                  ? arg->getAttribute(ctx, dataName) : nullptr;
            if (argData && argData->asSparseList(ctx)) {
                const proto::ProtoSparseList* srcSparse = argData->asSparseList(ctx);
                const proto::ProtoObject* argKeysObj = (arg->hasOwnAttribute(ctx, keysName) == PROTO_TRUE)
                                                        ? arg->getAttribute(ctx, keysName) : nullptr;
                const proto::ProtoList* argKeys = (argKeysObj && argKeysObj->asList(ctx))
                                                   ? argKeysObj->asList(ctx) : nullptr;
                if (argKeys) {
                    unsigned long n = argKeys->getSize(ctx);
                    for (unsigned long i = 0; i < n; ++i) {
                        const proto::ProtoObject* k = argKeys->getAt(ctx, static_cast<int>(i));
                        const proto::ProtoObject* v = srcSparse->getAt(ctx, k->getHash(ctx));
                        if (k && v) insertPair(k, v);
                    }
                }
                goto handle_kwargs;
            }
        }

        // Otherwise iterate as iterable of (key, value) pairs.
        {
            const proto::ProtoObject* it = env->iter(arg);
            if (!it) goto handle_kwargs;
            for (;;) {
                const proto::ProtoObject* pair = env->next(it);
                if (!pair) {
                    if (env->handleExhaustion(ctx)) break;
                    return nullptr; // Propagate non-StopIteration exceptions.
                }

                // Unpack pair — expect a 2-tuple or 2-list.
                const proto::ProtoObject* pairData = pair->getAttribute(ctx, dataName);
                const proto::ProtoTuple* tpl = pairData ? pairData->asTuple(ctx) : pair->asTuple(ctx);
                const proto::ProtoList* lst = nullptr;
                if (!tpl) {
                    lst = pairData ? pairData->asList(ctx) : pair->asList(ctx);
                }

                const proto::ProtoObject* key = nullptr;
                const proto::ProtoObject* val = nullptr;
                if (tpl && tpl->getSize(ctx) >= 2) {
                    key = tpl->getAt(ctx, 0);
                    val = tpl->getAt(ctx, 1);
                } else if (lst && lst->getSize(ctx) >= 2) {
                    key = lst->getAt(ctx, 0);
                    val = lst->getAt(ctx, 1);
                }
                if (key && val) insertPair(key, val);
            }
        }
    }

handle_kwargs:
    // Handle keyword arguments: each becomes a key-value entry.
    if (kwargs) {
        const proto::ProtoString* kwKeysName = PythonEnvironment::getInternalString(ctx, "__kw_keys__");
        const proto::ProtoObject* kwKeysObj = kwargs->asObject(ctx)->getAttribute(ctx, kwKeysName);
        // ProtoSparseList does not have a "keys" list, so we handle kwargs
        // by iterating over the ProtoSparseList if it has an associated keys list.
        // For now, keyword arguments are uncommon for dict(); skip if no keys list.
        (void)kwKeysObj;
    }

    return PROTO_NONE;
}

static const proto::ProtoObject* py_tuple_getitem(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    auto unwrap = [&](const proto::ProtoObject* candidate) -> const proto::ProtoTuple* {
        if (!candidate) return nullptr;
        const proto::ProtoTuple* t = candidate->asTuple(context);
        if (t) return t;
        const proto::ProtoString* dataName = PythonEnvironment::getInternalString(context, "__data__");
        const proto::ProtoObject* data = candidate->getAttribute(context, dataName);
        if (data && data->asTuple(context)) return data->asTuple(context);
        return nullptr;
    };
    const proto::ProtoTuple* tuple = unwrap(self);
    int indexArgOff = 0;
    // Unbound form: `tuple.__getitem__((1,2,3), slice(2))` — self is
    // the tuple type and positional[0] is the actual receiver.
    if (!tuple && positionalParameters && positionalParameters->getSize(context) >= 1) {
        tuple = unwrap(positionalParameters->getAt(context, 0));
        if (tuple) indexArgOff = 1;
    }
    if (!tuple) return nullptr; // Fallback to __class_getitem__

    if (positionalParameters->getSize(context) < static_cast<unsigned long>(indexArgOff + 1)) return PROTO_NONE;
    const proto::ProtoObject* indexObj = positionalParameters->getAt(context, indexArgOff);
    long long size = static_cast<long long>(tuple->getSize(context));

    SliceBounds sb = get_slice_bounds(context, indexObj, size);
    if (sb.isSlice) {
        const proto::ProtoList* result = context->newList();
        for (long long i = sb.start; (sb.step > 0 ? i < sb.stop : i > sb.stop); i += sb.step) {
            result = result->appendLast(context, tuple->getAt(context, static_cast<int>(i)));
        }
        const proto::ProtoTuple* T = context->newTupleFromList(result);
        proto::ProtoObject* tupObj = const_cast<proto::ProtoObject*>(context->newObject(true));
        PythonEnvironment* env = PythonEnvironment::fromContext(context);
        if (env && env->getTuplePrototype()) {
            tupObj = const_cast<proto::ProtoObject*>(tupObj->addParent(context, env->getTuplePrototype()));
            tupObj = const_cast<proto::ProtoObject*>(tupObj->setAttribute(context, env->getClassString(), env->getTuplePrototype()));
        }
        tupObj = const_cast<proto::ProtoObject*>(tupObj->setAttribute(context, env ? env->getDataString() : PythonEnvironment::getInternalString(context, "__data__"), T->asObject(context)));
        return tupObj;
    }

    // bool subclasses int — accept True/False as 1/0.  Same fix as
    // list/str indexing.
    if (indexObj->isInteger(context) || indexObj == PROTO_TRUE || indexObj == PROTO_FALSE) {
        long long index = indexObj == PROTO_TRUE ? 1
                        : indexObj == PROTO_FALSE ? 0
                        : indexObj->asLong(context);
        if (index < 0) index += size;
        if (index < 0 || index >= size) {
            if (get_env_diag()) {
                fflush(stderr);
            }
            PythonEnvironment* env = PythonEnvironment::fromContext(context);
            if (env) env->raiseIndexError(context, "tuple index out of range");
            return PROTO_NONE;
        }
        return tuple->getAt(context, static_cast<int>(index));
    }

    // CPython __index__ protocol — same fix as list subscript.
    {
        PythonEnvironment* envE = PythonEnvironment::fromContext(context);
        if (envE) {
            const proto::ProtoString* indexS =
                PythonEnvironment::getInternedString(context, "__index__");
            const proto::ProtoObject* indexM = envE->getAttribute(context, indexObj, indexS, false);
            if (indexM && indexM != PROTO_NONE) {
                const proto::ProtoObject* idxRes = nullptr;
                if (indexM->asMethod(context)) {
                    idxRes = indexM->asMethod(context)(context,
                        const_cast<proto::ProtoObject*>(indexObj), nullptr,
                        envE->getEmptyList(), nullptr);
                } else {
                    const proto::ProtoList* sa = context->newList()->appendLast(context, indexObj);
                    idxRes = ::protoPython::invokePythonCallable(context, indexM, sa, nullptr);
                }
                if (idxRes && idxRes->isInteger(context)) {
                    long long index = idxRes->asLong(context);
                    if (index < 0) index += size;
                    if (index < 0 || index >= size) {
                        envE->raiseIndexError(context, "tuple index out of range");
                        return PROTO_NONE;
                    }
                    return tuple->getAt(context, static_cast<int>(index));
                }
            }
        }
    }

    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    if (env) env->raiseTypeError(context, "tuple indices must be integers or slices");
    return PROTO_NONE;
}

static const proto::ProtoObject* py_tuple_iter(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    const proto::ProtoString* iterProtoName = PythonEnvironment::getInternedString(context, "__iter_prototype__");
    const proto::ProtoObject* iterProto = env ? env->getAttribute(context, self, iterProtoName) : self->getAttribute(context, iterProtoName);
    if (!iterProto) return PROTO_NONE;

    const proto::ProtoTuple* tuple = self->asTuple(context);
    const proto::ProtoObject* data = self;
    if (!tuple) {
        const proto::ProtoString* dataName = env ? env->getDataString() : PythonEnvironment::getInternalString(context, "__data__");
        data = self->getAttribute(context, dataName);
        if (data) tuple = data->asTuple(context);
    }
    if (!tuple) return PROTO_NONE;

    const proto::ProtoObject* iterObj = iterProto->newChild(context, true);
    const proto::ProtoString* iterTupleName = PythonEnvironment::getInternedString(context, "__iter_tuple__");
    const proto::ProtoString* iterIndexName = PythonEnvironment::getInternedString(context, "__iter_index__");
    iterObj = const_cast<proto::ProtoObject*>(iterObj->setAttribute(context, iterTupleName, data));
    iterObj = const_cast<proto::ProtoObject*>(iterObj->setAttribute(context, iterIndexName, context->fromInteger(0)));
    if (get_env_diag()) fprintf(stderr, "DEBUG py_tuple_iter CREATING: iterObj=%p for tuple=%p\n", (void*)iterObj, (void*)data);
    return iterObj;
}

static const proto::ProtoObject* py_tuple_reversed(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList*, const proto::ProtoSparseList*) {
    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    const proto::ProtoString* revProtoName = PythonEnvironment::getInternedString(context, "__reversed_prototype__");
    const proto::ProtoObject* revProto = self->getAttribute(context, revProtoName);
    if (!revProto || revProto == PROTO_NONE) return PROTO_NONE;
    const proto::ProtoString* dataName = PythonEnvironment::getInternalString(context, "__data__");
    const proto::ProtoObject* data = self->getAttribute(context, dataName);
    if (!data) return PROTO_NONE;
    
    long long n = 0;
    if (data->asList(context)) n = static_cast<long long>(data->asList(context)->getSize(context));
    else if (data->isTuple(context)) n = static_cast<long long>(data->asTuple(context)->getSize(context));
    else return PROTO_NONE;
    
    const proto::ProtoObject* revObj = revProto->newChild(context, true);
    revObj->setAttribute(context, PythonEnvironment::getInternedString(context, "__reversed_list__"), data);
    revObj->setAttribute(context, PythonEnvironment::getInternedString(context, "__reversed_idx__"), context->fromInteger(n - 1));
    return revObj;
}

static const proto::ProtoObject* py_tuple_reversed_next(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList*, const proto::ProtoSparseList*) {
    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    const proto::ProtoObject* dataObj = self->getAttribute(context, PythonEnvironment::getInternedString(context, "__reversed_list__"));
    const proto::ProtoObject* idxObj = self->getAttribute(context, PythonEnvironment::getInternedString(context, "__reversed_idx__"));
    if (!dataObj || !idxObj || !idxObj->isInteger(context)) return PROTO_NONE;
    long long idx = idxObj->asLong(context);
    if (idx < 0) return nullptr;
    
    const proto::ProtoObject* value = nullptr;
    if (dataObj->asList(context)) value = dataObj->asList(context)->getAt(context, static_cast<int>(idx));
    else if (dataObj->isTuple(context)) value = dataObj->asTuple(context)->getAt(context, static_cast<int>(idx));
    
    if (value) {
        self->setAttribute(context, PythonEnvironment::getInternedString(context, "__reversed_idx__"), context->fromInteger(idx - 1));
        return value;
    }
    return nullptr;
}

static const proto::ProtoObject* py_tuple_iter_next(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    const proto::ProtoString* iterTupleName = PythonEnvironment::getInternedString(context, "__iter_tuple__");
    const proto::ProtoString* iterIndexName = PythonEnvironment::getInternedString(context, "__iter_index__");
    const proto::ProtoObject* tupleObj = self->getAttribute(context, iterTupleName);
    const proto::ProtoObject* indexObj = self->getAttribute(context, iterIndexName);
    if (get_env_diag()) fprintf(stderr, "DEBUG py_tuple_iter_next: self=%p\n", (void*)self);
    if (!tupleObj || !tupleObj->asTuple(context) || !indexObj) {
        if (get_env_diag()) fprintf(stderr, "DEBUG py_tuple_iter_next FAILING: tupleObj=%p, asTuple=%p, indexObj=%p\n", (void*)tupleObj, (void*)(tupleObj ? tupleObj->asTuple(context) : nullptr), (void*)indexObj);
        return nullptr; // Throw StopIteration instead of infinite None loops!
    }
    const proto::ProtoTuple* tuple = tupleObj->asTuple(context);
    int index = static_cast<int>(indexObj->asLong(context));
    unsigned long size = tuple->getSize(context);
    if (static_cast<unsigned long>(index) >= size) return nullptr;

    const proto::ProtoObject* value = tuple->getAt(context, index);
    const proto::ProtoObject* nextObj = self->setAttribute(context, iterIndexName, context->fromInteger(index + 1));
    if (get_env_diag()) {
        fflush(stderr);
    }
    return value;
}

static const proto::ProtoObject* py_tuple_add(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    if (!posArgs || posArgs->getSize(context) < 1) return PROTO_NONE;
    const proto::ProtoString* dataName = PythonEnvironment::getInternalString(context, "__data__");
    auto unwrap = [&](const proto::ProtoObject* x) -> const proto::ProtoTuple* {
        if (!x) return nullptr;
        if (const proto::ProtoTuple* t = x->asTuple(context)) return t;
        const proto::ProtoObject* d = x->getAttribute(context, dataName);
        return d ? d->asTuple(context) : nullptr;
    };
    const proto::ProtoTuple* selfT = unwrap(self);
    const proto::ProtoObject* otherObj = nullptr;
    if (!selfT && posArgs->getSize(context) >= 2) {
        selfT = unwrap(posArgs->getAt(context, 0));
        otherObj = posArgs->getAt(context, 1);
    } else {
        otherObj = posArgs->getAt(context, 0);
    }
    const proto::ProtoTuple* otherT = unwrap(otherObj);
    if (!selfT || !otherT) return PROTO_NONE;
    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    const proto::ProtoList* result = context->newList();
    for (unsigned long i = 0; i < selfT->getSize(context); ++i)
        result = result->appendLast(context, selfT->getAt(context, static_cast<int>(i)));
    for (unsigned long i = 0; i < otherT->getSize(context); ++i)
        result = result->appendLast(context, otherT->getAt(context, static_cast<int>(i)));
    const proto::ProtoTuple* newTup = context->newTupleFromList(result);
    if (!env || !env->getTuplePrototype()) return newTup ? newTup->asObject(context) : PROTO_NONE;
    proto::ProtoObject* out = const_cast<proto::ProtoObject*>(env->getTuplePrototype()->newChild(context, true));
    out->setAttribute(context, dataName, newTup ? newTup->asObject(context) : PROTO_NONE);
    return out;
}

static const proto::ProtoObject* py_tuple_mul(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    if (!posArgs || posArgs->getSize(context) < 1) return PROTO_NONE;
    const proto::ProtoString* dataName = PythonEnvironment::getInternalString(context, "__data__");
    auto unwrap = [&](const proto::ProtoObject* x) -> const proto::ProtoTuple* {
        if (!x) return nullptr;
        if (const proto::ProtoTuple* t = x->asTuple(context)) return t;
        const proto::ProtoObject* d = x->getAttribute(context, dataName);
        return d ? d->asTuple(context) : nullptr;
    };
    const proto::ProtoTuple* selfT = unwrap(self);
    const proto::ProtoObject* nObj = nullptr;
    if (!selfT && posArgs->getSize(context) >= 2) {
        selfT = unwrap(posArgs->getAt(context, 0));
        nObj = posArgs->getAt(context, 1);
    } else {
        nObj = posArgs->getAt(context, 0);
    }
    if (!selfT) return PROTO_NONE;
    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    // CPython: tuple * x with non-int x raises TypeError via the
    // NotImplemented sentinel path.  bool counts (subclass of int).
    // Returning PROTO_NONE silently produced None for `(1,2) * 2.5`.
    if (!nObj || (!nObj->isInteger(context) && !nObj->isBoolean(context))) {
        return env ? env->getNotImplementedPrototype() : PROTO_NONE;
    }
    long long n = nObj == PROTO_TRUE ? 1LL : (nObj == PROTO_FALSE ? 0LL : nObj->asLong(context));
    if (n < 0) n = 0;
    const proto::ProtoList* result = context->newList();
    unsigned long size = selfT->getSize(context);
    for (long long rep = 0; rep < n; ++rep)
        for (unsigned long i = 0; i < size; ++i)
            result = result->appendLast(context, selfT->getAt(context, static_cast<int>(i)));
    const proto::ProtoTuple* newTup = context->newTupleFromList(result);
    if (!env || !env->getTuplePrototype()) return newTup ? newTup->asObject(context) : PROTO_NONE;
    proto::ProtoObject* out = const_cast<proto::ProtoObject*>(env->getTuplePrototype()->newChild(context, true));
    out->setAttribute(context, dataName, newTup ? newTup->asObject(context) : PROTO_NONE);
    return out;
}

// Helper: lexicographic tuple compare, returns ok=false when either
// operand isn't tuple-shaped or contains an unsupported element type.
static int compare_tuples(proto::ProtoContext* context,
        const proto::ProtoObject* a, const proto::ProtoObject* b, bool* ok) {
    *ok = false;
    auto unwrap = [&](const proto::ProtoObject* x) -> const proto::ProtoTuple* {
        if (!x) return nullptr;
        if (const proto::ProtoTuple* t = x->asTuple(context)) return t;
        const proto::ProtoString* dn = PythonEnvironment::getInternalString(context, "__data__");
        const proto::ProtoObject* d = x->getAttribute(context, dn);
        return d ? d->asTuple(context) : nullptr;
    };
    const proto::ProtoTuple* ta = unwrap(a);
    const proto::ProtoTuple* tb = unwrap(b);
    if (!ta || !tb) return 0;
    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    unsigned long sa = ta->getSize(context);
    unsigned long sb = tb->getSize(context);
    unsigned long n = std::min(sa, sb);
    for (unsigned long i = 0; i < n; ++i) {
        const proto::ProtoObject* ea = ta->getAt(context, static_cast<int>(i));
        const proto::ProtoObject* eb = tb->getAt(context, static_cast<int>(i));
        if (ea == eb) continue;
        if (env) {
            if (env->objectsEqual(context, ea, eb)) continue;
            const proto::ProtoObject* r = env->compareObjects(context, ea, eb, 2 /*lt*/);
            *ok = true;
            if (r == PROTO_TRUE) return -1;
            return 1;
        }
        int c = ea->compare(context, eb);
        if (c != 0) { *ok = true; return c; }
    }
    *ok = true;
    if (sa < sb) return -1;
    if (sa > sb) return 1;
    return 0;
}

static const proto::ProtoObject* py_tuple_cmp_dispatch(proto::ProtoContext* ctx,
        const proto::ProtoObject* self, const proto::ProtoList* args,
        int op /* 0=lt 1=le 2=gt 3=ge */) {
    const proto::ProtoObject* other = nullptr;
    // Detect unbound (cls, a, b) form.
    auto unwrap = [&](const proto::ProtoObject* x) -> const proto::ProtoTuple* {
        if (!x) return nullptr;
        if (const proto::ProtoTuple* t = x->asTuple(ctx)) return t;
        const proto::ProtoString* dn = PythonEnvironment::getInternalString(ctx, "__data__");
        const proto::ProtoObject* d = x->getAttribute(ctx, dn);
        return d ? d->asTuple(ctx) : nullptr;
    };
    if (!unwrap(self) && args && args->getSize(ctx) >= 2) {
        self = args->getAt(ctx, 0);
        other = args->getAt(ctx, 1);
    } else if (args && args->getSize(ctx) >= 1) {
        other = args->getAt(ctx, 0);
    }
    if (!self || !other) return PROTO_FALSE;
    bool ok = false;
    int c = compare_tuples(ctx, self, other, &ok);
    if (!ok) return PROTO_FALSE;
    switch (op) {
        case 0: return c <  0 ? PROTO_TRUE : PROTO_FALSE;
        case 1: return c <= 0 ? PROTO_TRUE : PROTO_FALSE;
        case 2: return c >  0 ? PROTO_TRUE : PROTO_FALSE;
        case 3: return c >= 0 ? PROTO_TRUE : PROTO_FALSE;
    }
    return PROTO_FALSE;
}

static const proto::ProtoObject* py_tuple_lt(
    proto::ProtoContext* ctx, const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* args, const proto::ProtoSparseList*) {
    return py_tuple_cmp_dispatch(ctx, self, args, 0);
}
static const proto::ProtoObject* py_tuple_le(
    proto::ProtoContext* ctx, const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* args, const proto::ProtoSparseList*) {
    return py_tuple_cmp_dispatch(ctx, self, args, 1);
}
static const proto::ProtoObject* py_tuple_gt(
    proto::ProtoContext* ctx, const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* args, const proto::ProtoSparseList*) {
    return py_tuple_cmp_dispatch(ctx, self, args, 2);
}
static const proto::ProtoObject* py_tuple_ge(
    proto::ProtoContext* ctx, const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* args, const proto::ProtoSparseList*) {
    return py_tuple_cmp_dispatch(ctx, self, args, 3);
}

static const proto::ProtoObject* py_tuple_contains(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    const proto::ProtoString* dataName = PythonEnvironment::getInternalString(context, "__data__");
    const proto::ProtoObject* selfTuple = self ? self->asTuple(context) ? self : self->getAttribute(context, dataName) : nullptr;
    if (selfTuple && !selfTuple->asTuple(context)) selfTuple = self->asTuple(context) ? self : nullptr;
    const proto::ProtoObject* receiver = self;
    const proto::ProtoObject* value = nullptr;
    bool selfIsTuple = self && (self->asTuple(context) != nullptr
        || (self->getAttribute(context, dataName)
            && self->getAttribute(context, dataName)->asTuple(context)));
    if (!selfIsTuple && positionalParameters && positionalParameters->getSize(context) >= 2) {
        receiver = positionalParameters->getAt(context, 0);
        value = positionalParameters->getAt(context, 1);
    } else if (positionalParameters && positionalParameters->getSize(context) >= 1) {
        value = positionalParameters->getAt(context, 0);
    }
    if (!receiver || !value) return PROTO_FALSE;
    const proto::ProtoTuple* t = receiver->asTuple(context);
    if (!t) {
        const proto::ProtoObject* d = receiver->getAttribute(context, dataName);
        t = d ? d->asTuple(context) : nullptr;
    }
    if (!t) return PROTO_FALSE;
    return t->has(context, value) ? PROTO_TRUE : PROTO_FALSE;
}

static const proto::ProtoObject* py_tuple_bool(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    const proto::ProtoString* dataName = PythonEnvironment::getInternalString(context, "__data__");
    const proto::ProtoObject* data = self->getAttribute(context, dataName);
    if (!data || !data->asTuple(context)) {
        if (self->asTuple(context)) {
             return self->asTuple(context)->getSize(context) > 0 ? PROTO_TRUE : PROTO_FALSE;
        }
        return PROTO_FALSE;
    }
    return data->asTuple(context)->getSize(context) > 0 ? PROTO_TRUE : PROTO_FALSE;
}

static const proto::ProtoObject* py_tuple_index(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    if (!positionalParameters || positionalParameters->getSize(context) < 1) return PROTO_NONE;
    const proto::ProtoString* dataName = PythonEnvironment::getInternalString(context, "__data__");
    const proto::ProtoObject* data = self->getAttribute(context, dataName);
    if (!data || !data->asTuple(context)) return PROTO_NONE;
    const proto::ProtoTuple* tuple = data->asTuple(context);
    const proto::ProtoObject* value = positionalParameters->getAt(context, 0);
    long long start = 0;
    long long stop = static_cast<long long>(tuple->getSize(context));
    if (positionalParameters->getSize(context) >= 2 && positionalParameters->getAt(context, 1)->isInteger(context))
        start = positionalParameters->getAt(context, 1)->asLong(context);
    if (positionalParameters->getSize(context) >= 3 && positionalParameters->getAt(context, 2)->isInteger(context))
        stop = positionalParameters->getAt(context, 2)->asLong(context);
    if (start < 0) start = 0;
    for (long long i = start; i < stop && static_cast<unsigned long>(i) < tuple->getSize(context); ++i) {
        const proto::ProtoObject* elem = tuple->getAt(context, static_cast<int>(i));
        if (list_elem_equal(context, elem, value))
            return context->fromInteger(i);
    }
    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    if (env) env->raiseValueError(context, PythonEnvironment::getInternedString(context, "tuple.index(x): x not in tuple")->asObject(context));
    return PROTO_NONE;
}

static const proto::ProtoObject* py_tuple_count(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    if (!positionalParameters || positionalParameters->getSize(context) < 1) return context->fromInteger(0);
    const proto::ProtoString* dataName = PythonEnvironment::getInternalString(context, "__data__");
    const proto::ProtoObject* data = self->getAttribute(context, dataName);
    if (!data || !data->asTuple(context)) return context->fromInteger(0);
    const proto::ProtoTuple* tuple = data->asTuple(context);
    const proto::ProtoObject* value = positionalParameters->getAt(context, 0);
    long count = 0;
    unsigned long size = tuple->getSize(context);
    for (unsigned long i = 0; i < size; ++i) {
        const proto::ProtoObject* elem = tuple->getAt(context, static_cast<int>(i));
        if (list_elem_equal(context, elem, value)) count++;
    }
    return context->fromInteger(count);
}

static const proto::ProtoObject* py_str_encode(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    (void)parentLink;
    (void)keywordParameters;
    int posOff = 0;
    const proto::ProtoString* s = str_from_self_or_arg(context, self, positionalParameters, &posOff);
    if (!s) return PROTO_NONE;
    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    if (!env) return PROTO_NONE;
    std::string raw;
    s->toUTF8String(context, raw);

    // Resolve encoding argument. CPython treats `'…'.encode('ascii')`
    // as strict: a non-ASCII character must raise UnicodeEncodeError.
    // Previously this was completely ignored — every encoding produced
    // the UTF-8 bytes — so `_bytes_from_decode_data('with \\xcb')`
    // never raised, breaking test_decode_nonascii_str.
    std::string encoding = "utf-8";
    if (positionalParameters && positionalParameters->getSize(context) >= static_cast<unsigned long>(1 + posOff)) {
        const proto::ProtoObject* enc = positionalParameters->getAt(context, posOff);
        if (enc && enc->isString(context)) {
            enc->asString(context)->toUTF8String(context, encoding);
        } else {
            // CPython: str.encode(non_str) raises (including None).
            //   TypeError: str.encode() argument 'encoding' must be str, not X
            // Previously a non-string encoding silently fell back to
            // utf-8 — `'abc'.encode(5)` produced b'abc' as if no
            // encoding had been specified, masking misuse.
            std::string clsName = (!enc || enc == PROTO_NONE) ? "NoneType" : "object";
            if (enc && enc != PROTO_NONE) {
                const proto::ProtoObject* cls = env->getType(context, enc);
                if (cls) {
                    const proto::ProtoObject* nm = cls->getAttribute(context, env->getNameString());
                    if (nm && nm->isString(context)) nm->asString(context)->toUTF8String(context, clsName);
                }
            }
            env->raiseTypeError(context,
                "str.encode() argument 'encoding' must be str, not " + clsName);
            return nullptr;
        }
    }
    // Also honour encoding= kwarg.
    if (keywordParameters && keywordParameters->getSize(context) > 0 && encoding == "utf-8") {
        const proto::ProtoString* encS = PythonEnvironment::getInternedString(context, "encoding");
        if (keywordParameters->has(context, encS->getHash(context))) {
            const proto::ProtoObject* v = keywordParameters->getAt(context, encS->getHash(context));
            if (v && v->isString(context)) {
                v->asString(context)->toUTF8String(context, encoding);
            } else if (v && v != PROTO_NONE) {
                std::string clsName = "object";
                const proto::ProtoObject* cls = env->getType(context, v);
                if (cls) {
                    const proto::ProtoObject* nm = cls->getAttribute(context, env->getNameString());
                    if (nm && nm->isString(context)) nm->asString(context)->toUTF8String(context, clsName);
                }
                env->raiseTypeError(context,
                    "str.encode() argument 'encoding' must be str, not " + clsName);
                return nullptr;
            }
        }
    }
    // Lower-case + canonical-form normalisation: 'ASCII', 'us-ascii',
    // 'ascii' all map to the same check. CPython does the same via
    // codecs.lookup → name attribute.
    std::string canon;
    canon.reserve(encoding.size());
    for (char c : encoding) {
        if (c >= 'A' && c <= 'Z') canon += static_cast<char>(c - 'A' + 'a');
        else if (c == '-' || c == '_') /* skip */;
        else canon += c;
    }
    if (canon == "ascii" || canon == "usascii") {
        for (size_t i = 0; i < raw.size(); ++i) {
            if (static_cast<unsigned char>(raw[i]) >= 0x80) {
                env->raiseValueError(context,
                    PythonEnvironment::getInternedString(context,
                        "'ascii' codec can't encode character: "
                        "ordinal not in range(128)")->asObject(context));
                return nullptr;
            }
        }
    } else if (canon == "latin1" || canon == "iso88591" || canon == "8859") {
        // latin-1 maps each Unicode code point ≤ 0xFF to a byte.
        // protoPython stores str as UTF-8; iterate code points.
        std::string out;
        size_t i = 0;
        while (i < raw.size()) {
            unsigned char c = static_cast<unsigned char>(raw[i]);
            unsigned int cp = 0;
            int len = 1;
            if (c < 0x80) { cp = c; len = 1; }
            else if ((c & 0xE0) == 0xC0 && i + 1 < raw.size()) {
                cp = ((c & 0x1F) << 6) | (static_cast<unsigned char>(raw[i+1]) & 0x3F);
                len = 2;
            } else {
                env->raiseValueError(context,
                    PythonEnvironment::getInternedString(context,
                        "'latin-1' codec can't encode character: "
                        "ordinal not in range(256)")->asObject(context));
                return nullptr;
            }
            if (cp > 0xFF) {
                env->raiseValueError(context,
                    PythonEnvironment::getInternedString(context,
                        "'latin-1' codec can't encode character: "
                        "ordinal not in range(256)")->asObject(context));
                return nullptr;
            }
            out += static_cast<char>(cp);
            i += len;
        }
        raw = out;
    }
    // utf-8 (default): use raw as-is (protoPython str storage is UTF-8).

    const proto::ProtoObject* bytesProto = env->getBytesPrototype();
    if (!bytesProto) return PROTO_NONE;
    const proto::ProtoObject* b = bytesProto->newChild(context, true);
    // Use ProtoByteBuffer for the bytes payload so non-ASCII octets
    // round-trip without UTF-8 reinterpretation.
    const proto::ProtoByteBuffer* bb = context->newByteBuffer(
        raw.data(), static_cast<unsigned long>(raw.size()));
    b->setAttribute(context,
        PythonEnvironment::getInternalString(context, "__data__"),
        bb->asObject(context));
    return b;
}

static const proto::ProtoObject* py_bytes_decode(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    (void)parentLink;
    (void)positionalParameters;
    (void)keywordParameters;
    std::string raw;
    if (!bytes_data_view(context, self, raw)) return PROTO_NONE;
    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    if (!env) return PROTO_NONE;
    const proto::ProtoObject* strProto = env->getStrPrototype();
    if (!strProto) return PROTO_NONE;
    const proto::ProtoObject* st = strProto->newChild(context, true);
    st->setAttribute(context, PythonEnvironment::getInternalString(context, "__data__"), PythonEnvironment::getInternedString(context, raw.c_str())->asObject(context));
    return st;
}

static const proto::ProtoObject* py_bytes_mul(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    if (!posArgs || posArgs->getSize(context) < 1) return PROTO_NONE;
    const proto::ProtoObject* nObj = posArgs->getAt(context, 0);
    // CPython: bytes * non-int returns NotImplemented so the binary-op
    // dispatcher emits TypeError.  Previously the silent PROTO_NONE
    // produced None for `b'ab' * 2.5` instead of the canonical
    // "unsupported operand type(s) for *".
    if (!nObj->isInteger(context) && !nObj->isBoolean(context)) {
        PythonEnvironment* envE = PythonEnvironment::fromContext(context);
        return envE ? envE->getNotImplementedPrototype() : PROTO_NONE;
    }
    long long n = nObj == PROTO_TRUE ? 1LL
                : nObj == PROTO_FALSE ? 0LL
                : nObj->asLong(context);
    if (n <= 0) return bytes_make_object(context, nullptr, 0);
    std::string raw;
    if (!bytes_data_view(context, self, raw)) return bytes_make_object(context, nullptr, 0);
    std::string repeated;
    repeated.reserve(raw.size() * static_cast<size_t>(n));
    for (long long i = 0; i < n; ++i) repeated.append(raw);
    return bytes_make_object(context, repeated.data(),
        static_cast<unsigned long>(repeated.size()));
}

static const proto::ProtoObject* py_bytes_add(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    if (!posArgs || posArgs->getSize(context) < 1) return PROTO_NONE;
    const proto::ProtoObject* other = posArgs->getAt(context, 0);
    // CPython: bytes accepts only bytes / bytearray for concatenation.
    // bytes_view tolerates ProtoString primitives so callers like
    // bytes.maketrans accept str; but for the operator-level + the
    // CPython rule is strict — raw str must raise TypeError, not be
    // implicitly encoded.  Reject:
    //   - raw ProtoString (b'ab' + 'cd')
    // Anything that does NOT look bytes-shaped returns NotImplemented
    // so the binary-op dispatcher emits the standard
    // "unsupported operand type(s) for +: 'bytes' and 'X'".
    PythonEnvironment* envE = PythonEnvironment::fromContext(context);
    bool otherIsBytes = false;
    if (other && !other->isString(context)) {
        if (other->isByteBuffer(context)) otherIsBytes = true;
        else {
            const proto::ProtoString* dataS = PythonEnvironment::getInternalString(context, "__data__");
            const proto::ProtoObject* d = other->getAttribute(context, dataS);
            if (d && d->isByteBuffer(context)) otherIsBytes = true;
        }
    }
    if (!otherIsBytes) {
        return envE ? envE->getNotImplementedPrototype() : PROTO_NONE;
    }
    std::string a, b;
    if (!bytes_data_view(context, self, a)) return PROTO_NONE;
    if (!bytes_view(context, other, b)) {
        return envE ? envE->getNotImplementedPrototype() : PROTO_NONE;
    }
    std::string out = a + b;
    return bytes_make_object(context, out.data(),
        static_cast<unsigned long>(out.size()));
}

static const proto::ProtoObject* py_bytes_eq(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    if (!posArgs || posArgs->getSize(context) < 1) return PROTO_FALSE;
    std::string a, b;
    if (!bytes_data_view(context, self, a)) return PROTO_FALSE;
    if (!bytes_view(context, posArgs->getAt(context, 0), b)) return PROTO_FALSE;
    return (a == b) ? PROTO_TRUE : PROTO_FALSE;
}

static const proto::ProtoObject* py_bytes_lt(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    if (!posArgs || posArgs->getSize(context) < 1) return PROTO_FALSE;
    std::string a, b;
    bytes_data_view(context, self, a);
    bytes_view(context, posArgs->getAt(context, 0), b);
    return (a < b) ? PROTO_TRUE : PROTO_FALSE;
}
static const proto::ProtoObject* py_bytes_le(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    if (!posArgs || posArgs->getSize(context) < 1) return PROTO_FALSE;
    std::string a, b;
    bytes_data_view(context, self, a);
    bytes_view(context, posArgs->getAt(context, 0), b);
    return (a <= b) ? PROTO_TRUE : PROTO_FALSE;
}
static const proto::ProtoObject* py_bytes_gt(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    if (!posArgs || posArgs->getSize(context) < 1) return PROTO_FALSE;
    std::string a, b;
    bytes_data_view(context, self, a);
    bytes_view(context, posArgs->getAt(context, 0), b);
    return (a > b) ? PROTO_TRUE : PROTO_FALSE;
}
static const proto::ProtoObject* py_bytes_ge(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    if (!posArgs || posArgs->getSize(context) < 1) return PROTO_FALSE;
    std::string a, b;
    bytes_data_view(context, self, a);
    bytes_view(context, posArgs->getAt(context, 0), b);
    return (a >= b) ? PROTO_TRUE : PROTO_FALSE;
}

// Wrap a raw ProtoList into a Python `list` instance with `__data__`
// pointing at the list and `__class__` set to `list`.  Without this,
// `len()` and `repr()` see no data and report 0/empty even though
// iteration finds the elements via the prototype's __iter__.
static const proto::ProtoObject* wrap_list_as_pylist(
    proto::ProtoContext* context, const proto::ProtoList* lst) {
    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    if (!env || !env->getListPrototype()) return lst->asObject(context);
    proto::ProtoObject* instance = const_cast<proto::ProtoObject*>(
        env->getListPrototype()->newChild(context, true));
    instance->setAttribute(context, env->getDataString(), lst->asObject(context));
    instance->setAttribute(context, env->getClassString(), env->getListPrototype());
    return instance;
}

// AA-round helpers — fresh bytes API surface, all routed through
// bytes_data_view and bytes_make_object.
static const proto::ProtoObject* py_bytes_upper(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList*, const proto::ProtoSparseList*) {
    std::string raw;
    if (!bytes_data_view(context, self, raw)) return PROTO_NONE;
    for (auto& c : raw) {
        unsigned char u = static_cast<unsigned char>(c);
        if (u >= 'a' && u <= 'z') c = static_cast<char>(u - 32);
    }
    return bytes_make_object(context, raw.data(), static_cast<unsigned long>(raw.size()));
}

static const proto::ProtoObject* py_bytes_lower(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList*, const proto::ProtoSparseList*) {
    std::string raw;
    if (!bytes_data_view(context, self, raw)) return PROTO_NONE;
    for (auto& c : raw) {
        unsigned char u = static_cast<unsigned char>(c);
        if (u >= 'A' && u <= 'Z') c = static_cast<char>(u + 32);
    }
    return bytes_make_object(context, raw.data(), static_cast<unsigned long>(raw.size()));
}

static const proto::ProtoObject* py_bytes_swapcase(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList*, const proto::ProtoSparseList*) {
    std::string raw;
    if (!bytes_data_view(context, self, raw)) return PROTO_NONE;
    for (auto& c : raw) {
        unsigned char u = static_cast<unsigned char>(c);
        if (u >= 'a' && u <= 'z') c = static_cast<char>(u - 32);
        else if (u >= 'A' && u <= 'Z') c = static_cast<char>(u + 32);
    }
    return bytes_make_object(context, raw.data(), static_cast<unsigned long>(raw.size()));
}

static const proto::ProtoObject* py_bytes_title(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList*, const proto::ProtoSparseList*) {
    std::string raw;
    if (!bytes_data_view(context, self, raw)) return PROTO_NONE;
    bool prevAlpha = false;
    for (auto& c : raw) {
        unsigned char u = static_cast<unsigned char>(c);
        bool isAlpha = (u >= 'a' && u <= 'z') || (u >= 'A' && u <= 'Z');
        if (isAlpha) {
            if (!prevAlpha) {
                if (u >= 'a' && u <= 'z') c = static_cast<char>(u - 32);
            } else {
                if (u >= 'A' && u <= 'Z') c = static_cast<char>(u + 32);
            }
        }
        prevAlpha = isAlpha;
    }
    return bytes_make_object(context, raw.data(), static_cast<unsigned long>(raw.size()));
}

static const proto::ProtoObject* py_bytes_partition_impl(
    proto::ProtoContext* context, const proto::ProtoObject* self,
    const proto::ProtoList* posArgs, bool reverse) {
    std::string raw;
    if (!bytes_data_view(context, self, raw) || !posArgs || posArgs->getSize(context) < 1) return PROTO_NONE;
    std::string sep;
    if (!bytes_view(context, posArgs->getAt(context, 0), sep) || sep.empty()) return PROTO_NONE;
    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    if (!env) return PROTO_NONE;
    size_t pos = reverse ? raw.rfind(sep) : raw.find(sep);
    const proto::ProtoObject* before;
    const proto::ProtoObject* sepObj;
    const proto::ProtoObject* after;
    if (pos == std::string::npos) {
        // Not found: return (self, b'', b'') for partition; (b'', b'', self) for rpartition.
        const proto::ProtoObject* empty = bytes_make_object(context, nullptr, 0);
        if (reverse) { before = empty; sepObj = empty; after = bytes_make_object(context, raw.data(), raw.size()); }
        else         { before = bytes_make_object(context, raw.data(), raw.size()); sepObj = empty; after = empty; }
    } else {
        std::string b = raw.substr(0, pos);
        std::string a = raw.substr(pos + sep.size());
        before = bytes_make_object(context, b.data(), static_cast<unsigned long>(b.size()));
        sepObj = bytes_make_object(context, sep.data(), static_cast<unsigned long>(sep.size()));
        after  = bytes_make_object(context, a.data(), static_cast<unsigned long>(a.size()));
    }
    const proto::ProtoList* l = context->newList()
        ->appendLast(context, before)
        ->appendLast(context, sepObj)
        ->appendLast(context, after);
    return env->newTuple(l);
}

static const proto::ProtoObject* py_bytes_partition(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    return py_bytes_partition_impl(context, self, posArgs, false);
}

static const proto::ProtoObject* py_bytes_rpartition(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    return py_bytes_partition_impl(context, self, posArgs, true);
}

static const proto::ProtoObject* py_bytes_zfill(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    std::string raw;
    if (!bytes_data_view(context, self, raw) || !posArgs || posArgs->getSize(context) < 1) return PROTO_NONE;
    long long width = posArgs->getAt(context, 0)->asLong(context);
    if (static_cast<long long>(raw.size()) >= width) {
        return bytes_make_object(context, raw.data(), static_cast<unsigned long>(raw.size()));
    }
    size_t pad = static_cast<size_t>(width) - raw.size();
    std::string out;
    out.reserve(static_cast<size_t>(width));
    // Preserve a leading sign byte before the zeros.
    if (!raw.empty() && (raw[0] == '+' || raw[0] == '-')) {
        out += raw[0];
        out.append(pad, '0');
        out.append(raw.begin() + 1, raw.end());
    } else {
        out.append(pad, '0');
        out.append(raw);
    }
    return bytes_make_object(context, out.data(), static_cast<unsigned long>(out.size()));
}

static const proto::ProtoObject* py_bytes_splitlines(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    std::string raw;
    if (!bytes_data_view(context, self, raw)) return PROTO_NONE;
    bool keepends = false;
    if (posArgs && posArgs->getSize(context) >= 1) {
        const proto::ProtoObject* k = posArgs->getAt(context, 0);
        if (k == PROTO_TRUE) keepends = true;
        else if (k->isInteger(context)) keepends = (k->asLong(context) != 0);
    }
    const proto::ProtoList* result = context->newList();
    size_t i = 0;
    while (i < raw.size()) {
        size_t j = i;
        while (j < raw.size() && raw[j] != '\n' && raw[j] != '\r') ++j;
        size_t end = j;
        if (j < raw.size()) {
            // CRLF or \n or \r — single line break.
            size_t brk = 1;
            if (raw[j] == '\r' && j + 1 < raw.size() && raw[j + 1] == '\n') brk = 2;
            if (keepends) end = j + brk;
            std::string line = raw.substr(i, end - i);
            result = result->appendLast(context,
                bytes_make_object(context, line.data(), static_cast<unsigned long>(line.size())));
            i = j + brk;
        } else {
            std::string line = raw.substr(i);
            result = result->appendLast(context,
                bytes_make_object(context, line.data(), static_cast<unsigned long>(line.size())));
            i = j;
        }
    }
    return wrap_list_as_pylist(context, result);
}

static const proto::ProtoObject* py_bytes_contains(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    if (!posArgs || posArgs->getSize(context) < 1) return PROTO_FALSE;
    std::string haystack;
    if (!bytes_data_view(context, self, haystack)) return PROTO_FALSE;
    const proto::ProtoObject* needleObj = posArgs->getAt(context, 0);
    std::string needle;
    if (needleObj->isInteger(context)) {
        long long v = needleObj->asLong(context);
        if (v < 0 || v > 255) {
            PythonEnvironment* env = PythonEnvironment::fromContext(context);
            if (env) env->raiseValueError(context,
                PythonEnvironment::getInternedString(context, "byte must be in range(0, 256)")->asObject(context));
            return PROTO_FALSE;
        }
        needle = static_cast<char>(static_cast<unsigned char>(v));
    } else if (needleObj->isString(context)) {
        // CPython: 'a' in b'abc' raises
        //   TypeError: a bytes-like object is required, not 'str'
        // bytes_view tolerates raw strings (for internal callers like
        // bytes.maketrans) so reject explicitly here for the operator
        // `in` form.  Wrapped bytes / bytearray instances are not raw
        // strings — isString returns false for them — so they keep
        // working through bytes_view below.
        PythonEnvironment* env = PythonEnvironment::fromContext(context);
        if (env) env->raiseTypeError(context,
            "a bytes-like object is required, not 'str'");
        return nullptr;
    } else if (!bytes_view(context, needleObj, needle)) {
        return PROTO_FALSE;
    }
    return haystack.find(needle) != std::string::npos ? PROTO_TRUE : PROTO_FALSE;
}

static const proto::ProtoObject* py_bytes_hash(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList*, const proto::ProtoSparseList*) {
    std::string raw;
    if (!bytes_data_view(context, self, raw)) return context->fromInteger(0);
    // FNV-1a 64-bit; fits in long long when reinterpreted.
    unsigned long long h = 14695981039346656037ULL;
    for (unsigned char c : raw) {
        h ^= static_cast<unsigned long long>(c);
        h *= 1099511628211ULL;
    }
    long long sh = static_cast<long long>(h);
    if (sh == -1) sh = -2;  // CPython convention
    return context->fromInteger(sh);
}

static const proto::ProtoObject* py_bytes_hex(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList*, const proto::ProtoSparseList*) {
    std::string raw;
    if (!bytes_data_view(context, self, raw))
        return PythonEnvironment::getInternedString(context, "")->asObject(context);
    static const char hex[] = "0123456789abcdef";
    std::string out;
    out.reserve(raw.size() * 2);
    for (unsigned char c : raw) {
        out += hex[c >> 4];
        out += hex[c & 0x0f];
    }
    return PythonEnvironment::getInternedString(context, out.c_str())->asObject(context);
}

// bytes.maketrans(frm, to) → returns a list of 256 ints (translation table).
// Using a list instead of bytes avoids the null-byte truncation issue with ProtoString storage.
static const proto::ProtoObject* py_bytes_maketrans(
    proto::ProtoContext* context,
    const proto::ProtoObject* /*self*/,
    const proto::ParentLink*,
    const proto::ProtoList* posArgs,
    const proto::ProtoSparseList*) {

    std::array<int, 256> table;
    for (int i = 0; i < 256; ++i) table[i] = i;

    if (posArgs->getSize(context) >= 2) {
        std::string frm_str, to_str;
        bytes_view(context, posArgs->getAt(context, 0), frm_str);
        bytes_view(context, posArgs->getAt(context, 1), to_str);
        size_t n = std::min(frm_str.size(), to_str.size());
        for (size_t i = 0; i < n; ++i)
            table[static_cast<unsigned char>(frm_str[i])] = static_cast<unsigned char>(to_str[i]);
    }

    const proto::ProtoList* result = context->newList();
    for (int i = 0; i < 256; ++i)
        result = result->appendLast(context, context->fromInteger(table[i]));
    return wrap_list_as_pylist(context, result);
}

// bytes.translate(table, delete=b'') — applies a translation table produced by bytes.maketrans.
static const proto::ProtoObject* py_bytes_translate(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*,
    const proto::ProtoList* posArgs,
    const proto::ProtoSparseList* kwargs) {

    std::string raw;
    if (!bytes_data_view(context, self, raw)) return self;

    // Build identity mapping; override from table arg when provided.
    std::array<int, 256> table;
    for (int i = 0; i < 256; ++i) table[i] = i;

    if (posArgs->getSize(context) >= 1) {
        const proto::ProtoObject* tableObj = posArgs->getAt(context, 0);
        if (tableObj && tableObj != PROTO_NONE) {
            const proto::ProtoList* lst = tableObj->asList(context);
            if (lst && lst->getSize(context) == 256) {
                for (int i = 0; i < 256; ++i) {
                    const proto::ProtoObject* v = lst->getAt(context, i);
                    if (v && v->isInteger(context)) {
                        long long iv = v->asLong(context);
                        table[i] = (iv >= 0 && iv < 256) ? static_cast<int>(iv) : -1;
                    }
                }
            }
        }
    }

    // Collect delete set. CPython accepts `delete` either as the
    // second positional or as a keyword. base64.b16decode passes it
    // by keyword (`s.translate(None, delete=b'0123…')`); the
    // previous positional-only check missed that and the function
    // returned the input unchanged, breaking b16decode's validity
    // gate.
    std::string del_str;
    const proto::ProtoObject* delObj = nullptr;
    if (posArgs->getSize(context) >= 2) {
        delObj = posArgs->getAt(context, 1);
    } else if (kwargs) {
        const proto::ProtoString* delS =
            PythonEnvironment::getInternedString(context, "delete");
        delObj = kwargs->getAt(context, delS->getHash(context));
    }
    if (delObj && delObj != PROTO_NONE) {
        bytes_view(context, delObj, del_str);
    }

    std::string out;
    out.reserve(raw.size());
    for (unsigned char c : raw) {
        if (!del_str.empty()) {
            bool deleted = false;
            for (unsigned char d : del_str) { if (d == c) { deleted = true; break; } }
            if (deleted) continue;
        }
        int mapped = table[c];
        if (mapped >= 0) out += static_cast<char>(static_cast<unsigned char>(mapped));
    }
    return bytes_make_object(context, out.data(), static_cast<unsigned long>(out.size()));
}

static const proto::ProtoObject* py_bytes_fromhex(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    if (posArgs->getSize(context) < 1) return PROTO_NONE;
    const proto::ProtoObject* strObj = posArgs->getAt(context, 0);
    if (!strObj->isString(context)) return PROTO_NONE;
    std::string hexStr;
    strObj->asString(context)->toUTF8String(context, hexStr);
    std::string raw;
    for (size_t i = 0; i + 1 < hexStr.size(); i += 2) {
        int hi = 0, lo = 0;
        char c1 = hexStr[i], c2 = hexStr[i + 1];
        if (c1 >= '0' && c1 <= '9') hi = c1 - '0';
        else if (c1 >= 'a' && c1 <= 'f') hi = c1 - 'a' + 10;
        else if (c1 >= 'A' && c1 <= 'F') hi = c1 - 'A' + 10;
        else continue;
        if (c2 >= '0' && c2 <= '9') lo = c2 - '0';
        else if (c2 >= 'a' && c2 <= 'f') lo = c2 - 'a' + 10;
        else if (c2 >= 'A' && c2 <= 'F') lo = c2 - 'A' + 10;
        else continue;
        raw += static_cast<char>(hi * 16 + lo);
    }
    return bytes_make_object(context, raw.data(), static_cast<unsigned long>(raw.size()));
}

// CPython bytes.find / rfind / count / index / rindex require an
// int or bytes-like needle.  Raw str silently coerced into bytes
// via bytes_view, returning the byte-offset of the str interpreted
// as bytes — `b'abc'.find('b')` returned 1 instead of raising
// TypeError("argument should be integer or bytes-like object, not 'str'").
// Returns true iff the needle is OK; sets pending TypeError on str.
static bool bytes_needle_validate(proto::ProtoContext* context,
                                  const proto::ProtoObject* sub) {
    if (!sub) return false;
    if (sub->isInteger(context) || sub == PROTO_TRUE || sub == PROTO_FALSE) return true;
    if (sub->isString(context)) {
        // Reject a raw ProtoString primitive.  Wrapped bytes / bytearray
        // are not raw strings — isString returns false for those carrier
        // shapes — so they keep working.
        PythonEnvironment* env = PythonEnvironment::fromContext(context);
        if (env) env->raiseTypeError(context,
            "argument should be integer or bytes-like object, not 'str'");
        return false;
    }
    return true;
}

static const proto::ProtoObject* py_bytes_find(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    std::string haystack;
    if (!bytes_data_view(context, self, haystack) || posArgs->getSize(context) < 1)
        return context->fromInteger(-1);
    const proto::ProtoObject* sub = posArgs->getAt(context, 0);
    if (!bytes_needle_validate(context, sub)) return nullptr;
    long long start = 0, end = static_cast<long long>(haystack.size());
    if (posArgs->getSize(context) >= 2 && posArgs->getAt(context, 1)->isInteger(context))
        start = posArgs->getAt(context, 1)->asLong(context);
    if (posArgs->getSize(context) >= 3 && posArgs->getAt(context, 2)->isInteger(context))
        end = posArgs->getAt(context, 2)->asLong(context);
    std::string needle;
    bytes_needle_from_arg(context, sub, needle);
    if (needle.empty() && !sub->isInteger(context) && sub->getAttribute(context, PythonEnvironment::getInternalString(context, "__data__")) == nullptr && !sub->isString(context) && !sub->isByteBuffer(context))
        return context->fromInteger(-1);
    size_t pos = haystack.find(needle, static_cast<size_t>(start));
    if (pos == std::string::npos || static_cast<long long>(pos) >= end)
        return context->fromInteger(-1);
    return context->fromInteger(static_cast<long long>(pos));
}

static const proto::ProtoObject* py_bytes_count(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    std::string haystack;
    if (!bytes_data_view(context, self, haystack) || posArgs->getSize(context) < 1)
        return context->fromInteger(0);
    const proto::ProtoObject* sub = posArgs->getAt(context, 0);
    if (!bytes_needle_validate(context, sub)) return nullptr;
    long long start = 0, end = static_cast<long long>(haystack.size());
    if (posArgs->getSize(context) >= 2 && posArgs->getAt(context, 1)->isInteger(context))
        start = posArgs->getAt(context, 1)->asLong(context);
    if (posArgs->getSize(context) >= 3 && posArgs->getAt(context, 2)->isInteger(context))
        end = posArgs->getAt(context, 2)->asLong(context);
    std::string needle;
    bytes_needle_from_arg(context, sub, needle);
    size_t count = 0;
    size_t pos = static_cast<size_t>(start);
    while (pos < haystack.size() && static_cast<long long>(pos) < end) {
        size_t found = haystack.find(needle, pos);
        if (found == std::string::npos || static_cast<long long>(found) >= end) break;
        count++;
        pos = found + (needle.empty() ? 1 : needle.size());
    }
    return context->fromInteger(static_cast<long long>(count));
}

static void bytes_needle_from_arg(proto::ProtoContext* context, const proto::ProtoObject* arg, std::string& out) {
    out.clear();
    if (arg->isInteger(context)) {
        long long v = arg->asLong(context);
        if (v >= 0 && v <= 255) out = static_cast<char>(static_cast<unsigned char>(v));
        return;
    }
    // bytes_view handles native ProtoString, ProtoByteBuffer, and the
    // bytes/bytearray instance shapes (reads __data__ in either form).
    bytes_view(context, arg, out);
}

static const proto::ProtoObject* py_bytes_startswith(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    std::string haystack;
    if (!bytes_data_view(context, self, haystack) || posArgs->getSize(context) < 1) return PROTO_FALSE;
    const proto::ProtoObject* prefArg = posArgs->getAt(context, 0);
    // CPython: startswith requires a bytes (or tuple of bytes).  Raw
    // str silently coerced via bytes_view returning True/False.
    if (prefArg && prefArg->isString(context)) {
        PythonEnvironment* env = PythonEnvironment::fromContext(context);
        if (env) env->raiseTypeError(context,
            "startswith first arg must be bytes or a tuple of bytes, not str");
        return nullptr;
    }
    std::string prefix;
    bytes_needle_from_arg(context, prefArg, prefix);
    long long start = 0, end = static_cast<long long>(haystack.size());
    if (posArgs->getSize(context) >= 2 && posArgs->getAt(context, 1)->isInteger(context))
        start = posArgs->getAt(context, 1)->asLong(context);
    if (posArgs->getSize(context) >= 3 && posArgs->getAt(context, 2)->isInteger(context))
        end = posArgs->getAt(context, 2)->asLong(context);
    if (start < 0) start = 0;
    if (end > static_cast<long long>(haystack.size())) end = static_cast<long long>(haystack.size());
    if (prefix.size() > static_cast<size_t>(end - start) || start > end) return PROTO_FALSE;
    return haystack.compare(static_cast<size_t>(start), prefix.size(), prefix) == 0 ? PROTO_TRUE : PROTO_FALSE;
}

static const proto::ProtoObject* py_bytes_endswith(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    std::string haystack;
    if (!bytes_data_view(context, self, haystack) || posArgs->getSize(context) < 1) return PROTO_FALSE;
    const proto::ProtoObject* sufArg = posArgs->getAt(context, 0);
    if (sufArg && sufArg->isString(context)) {
        PythonEnvironment* env = PythonEnvironment::fromContext(context);
        if (env) env->raiseTypeError(context,
            "endswith first arg must be bytes or a tuple of bytes, not str");
        return nullptr;
    }
    std::string suffix;
    bytes_needle_from_arg(context, sufArg, suffix);
    long long start = 0, end = static_cast<long long>(haystack.size());
    if (posArgs->getSize(context) >= 2 && posArgs->getAt(context, 1)->isInteger(context))
        start = posArgs->getAt(context, 1)->asLong(context);
    if (posArgs->getSize(context) >= 3 && posArgs->getAt(context, 2)->isInteger(context))
        end = posArgs->getAt(context, 2)->asLong(context);
    if (start < 0) start = 0;
    if (end > static_cast<long long>(haystack.size())) end = static_cast<long long>(haystack.size());
    if (suffix.size() > static_cast<size_t>(end - start) || start > end) return PROTO_FALSE;
    size_t pos = static_cast<size_t>(end) - suffix.size();
    if (pos < static_cast<size_t>(start)) return PROTO_FALSE;
    return haystack.compare(pos, suffix.size(), suffix) == 0 ? PROTO_TRUE : PROTO_FALSE;
}

static const proto::ProtoObject* py_bytes_index(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    const proto::ProtoObject* r = py_bytes_find(context, self, nullptr, posArgs, nullptr);
    if (!r || !r->isInteger(context) || r->asLong(context) < 0) {
        PythonEnvironment* env = PythonEnvironment::fromContext(context);
        if (env) env->raiseValueError(context, PythonEnvironment::getInternedString(context, "subsection not found")->asObject(context));
        return PROTO_NONE;
    }
    return r;
}

static const proto::ProtoObject* py_bytes_rfind(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    std::string haystack;
    if (!bytes_data_view(context, self, haystack) || posArgs->getSize(context) < 1)
        return context->fromInteger(-1);
    const proto::ProtoObject* sub = posArgs->getAt(context, 0);
    if (!bytes_needle_validate(context, sub)) return nullptr;
    long long start = 0, end = static_cast<long long>(haystack.size());
    if (posArgs->getSize(context) >= 2 && posArgs->getAt(context, 1)->isInteger(context))
        start = posArgs->getAt(context, 1)->asLong(context);
    if (posArgs->getSize(context) >= 3 && posArgs->getAt(context, 2)->isInteger(context))
        end = posArgs->getAt(context, 2)->asLong(context);
    std::string needle;
    bytes_needle_from_arg(context, sub, needle);
    if (start >= end || static_cast<size_t>(start) >= haystack.size())
        return context->fromInteger(-1);
    size_t len = static_cast<size_t>(std::min(end, static_cast<long long>(haystack.size())) - start);
    std::string slice = haystack.substr(static_cast<size_t>(start), len);
    size_t found = slice.rfind(needle);
    if (found == std::string::npos)
        return context->fromInteger(-1);
    return context->fromInteger(static_cast<long long>(start) + static_cast<long long>(found));
}

static const proto::ProtoObject* py_bytes_rindex(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    const proto::ProtoObject* r = py_bytes_rfind(context, self, nullptr, posArgs, nullptr);
    if (!r || !r->isInteger(context) || r->asLong(context) < 0) {
        PythonEnvironment* env = PythonEnvironment::fromContext(context);
        if (env) env->raiseValueError(context, PythonEnvironment::getInternedString(context, "subsection not found")->asObject(context));
        return PROTO_NONE;
    }
    return r;
}

static const proto::ProtoObject* py_bytes_replace(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    std::string raw;
    if (!bytes_data_view(context, self, raw) || posArgs->getSize(context) < 2) return PROTO_NONE;
    std::string old_str, new_str;
    bytes_needle_from_arg(context, posArgs->getAt(context, 0), old_str);
    bytes_needle_from_arg(context, posArgs->getAt(context, 1), new_str);
    long long count = -1;
    if (posArgs->getSize(context) >= 3 && posArgs->getAt(context, 2)->isInteger(context))
        count = posArgs->getAt(context, 2)->asLong(context);
    std::string out;
    size_t start = 0;
    long long n = 0;
    while (count < 0 || n < count) {
        size_t pos = raw.find(old_str, start);
        if (pos == std::string::npos) break;
        out += raw.substr(start, pos - start);
        out += new_str;
        start = pos + old_str.size();
        n++;
    }
    out += raw.substr(start);
    return bytes_make_object(context, out.data(), static_cast<unsigned long>(out.size()));
}

static const proto::ProtoObject* py_bytes_isdigit(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList*, const proto::ProtoSparseList*) {
    std::string raw;
    if (!bytes_data_view(context, self, raw) || raw.empty()) return PROTO_FALSE;
    for (unsigned char c : raw)
        if (!std::isdigit(c)) return PROTO_FALSE;
    return PROTO_TRUE;
}

static const proto::ProtoObject* py_bytes_isalpha(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList*, const proto::ProtoSparseList*) {
    std::string raw;
    if (!bytes_data_view(context, self, raw) || raw.empty()) return PROTO_FALSE;
    for (unsigned char c : raw)
        if (!std::isalpha(c)) return PROTO_FALSE;
    return PROTO_TRUE;
}

static const proto::ProtoObject* py_bytes_isascii(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList*, const proto::ProtoSparseList*) {
    std::string raw;
    if (!bytes_data_view(context, self, raw)) return PROTO_FALSE;
    for (unsigned char c : raw)
        if (c > 127) return PROTO_FALSE;
    return PROTO_TRUE;
}

static const proto::ProtoObject* py_bytes_removeprefix(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    std::string raw;
    if (!bytes_data_view(context, self, raw) || !posArgs || posArgs->getSize(context) < 1) return PROTO_NONE;
    std::string prefix;
    bytes_view(context, posArgs->getAt(context, 0), prefix);
    if (prefix.size() <= raw.size() && raw.compare(0, prefix.size(), prefix) == 0) {
        std::string out = raw.substr(prefix.size());
        return bytes_make_object(context, out.data(), static_cast<unsigned long>(out.size()));
    }
    return const_cast<proto::ProtoObject*>(self);
}

static const proto::ProtoObject* py_bytes_removesuffix(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    std::string raw;
    if (!bytes_data_view(context, self, raw) || !posArgs || posArgs->getSize(context) < 1) return PROTO_NONE;
    std::string suffix;
    bytes_view(context, posArgs->getAt(context, 0), suffix);
    if (suffix.size() <= raw.size() && raw.compare(raw.size() - suffix.size(), suffix.size(), suffix) == 0) {
        std::string out = raw.substr(0, raw.size() - suffix.size());
        return bytes_make_object(context, out.data(), static_cast<unsigned long>(out.size()));
    }
    return const_cast<proto::ProtoObject*>(self);
}

static bool bytes_byte_in_chars(unsigned char c, const std::string& ch) {
    if (ch.empty()) return (c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v');
    return ch.find(c) != std::string::npos;
}

static const proto::ProtoObject* py_bytes_lstrip(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    std::string raw;
    if (!bytes_data_view(context, self, raw)) return PROTO_NONE;
    std::string chars;
    if (posArgs && posArgs->getSize(context) >= 1) {
        bytes_view(context, posArgs->getAt(context, 0), chars);
    }
    size_t start = 0;
    while (start < raw.size() && bytes_byte_in_chars(static_cast<unsigned char>(raw[start]), chars)) start++;
    std::string out = raw.substr(start);
    return bytes_make_object(context, out.data(), static_cast<unsigned long>(out.size()));
}

static const proto::ProtoObject* py_bytes_rstrip(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    std::string raw;
    if (!bytes_data_view(context, self, raw)) return PROTO_NONE;
    std::string chars;
    if (posArgs && posArgs->getSize(context) >= 1) {
        bytes_view(context, posArgs->getAt(context, 0), chars);
    }
    size_t end = raw.size();
    while (end > 0 && bytes_byte_in_chars(static_cast<unsigned char>(raw[end - 1]), chars)) end--;
    std::string out = raw.substr(0, end);
    return bytes_make_object(context, out.data(), static_cast<unsigned long>(out.size()));
}

static const proto::ProtoObject* py_bytes_strip(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    std::string raw;
    if (!bytes_data_view(context, self, raw)) return PROTO_NONE;
    std::string chars;
    if (posArgs && posArgs->getSize(context) >= 1) {
        bytes_view(context, posArgs->getAt(context, 0), chars);
    }
    size_t start = 0;
    while (start < raw.size() && bytes_byte_in_chars(static_cast<unsigned char>(raw[start]), chars)) start++;
    size_t end = raw.size();
    while (end > start && bytes_byte_in_chars(static_cast<unsigned char>(raw[end - 1]), chars)) end--;
    std::string out = raw.substr(start, end - start);
    return bytes_make_object(context, out.data(), static_cast<unsigned long>(out.size()));
}

static std::string bytes_sep_from_arg(proto::ProtoContext* context, const proto::ProtoObject* arg) {
    if (!arg) return " ";
    if (arg->isInteger(context)) {
        long long v = arg->asLong(context);
        if (v < 0 || v > 255) return " ";
        return std::string(1, static_cast<char>(static_cast<unsigned char>(v)));
    }
    std::string r;
    if (bytes_view(context, arg, r)) return r;
    return " ";
}

static const proto::ProtoObject* py_bytes_split(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    std::string raw;
    if (!bytes_data_view(context, self, raw)) return PROTO_NONE;
    std::string sep = (posArgs && posArgs->getSize(context) >= 1) ? bytes_sep_from_arg(context, posArgs->getAt(context, 0)) : " ";
    if (sep.empty()) return PROTO_NONE;
    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    if (!env) return PROTO_NONE;
    const proto::ProtoList* result = context->newList();
    size_t start = 0;
    for (;;) {
        size_t pos = raw.find(sep, start);
        if (pos == std::string::npos) {
            std::string seg = raw.substr(start);
            const proto::ProtoObject* b = bytes_make_object(context, seg.data(), static_cast<unsigned long>(seg.size()));
            result = result->appendLast(context, b);
            break;
        }
        std::string seg = raw.substr(start, pos - start);
        const proto::ProtoObject* b = bytes_make_object(context, seg.data(), static_cast<unsigned long>(seg.size()));
        result = result->appendLast(context, b);
        start = pos + sep.size();
    }
    return wrap_list_as_pylist(context, result);
}

static const proto::ProtoObject* py_bytes_join(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    std::string sepStr;
    if (!bytes_data_view(context, self, sepStr) || !posArgs || posArgs->getSize(context) < 1) return PROTO_NONE;
    const proto::ProtoObject* iterable = posArgs->getAt(context, 0);
    const proto::ProtoObject* iterM = iterable->getAttribute(context, PythonEnvironment::getInternalString(context, "__iter__"));
    if (!iterM || !iterM->asMethod(context)) return PROTO_NONE;
    const proto::ProtoObject* it = iterM->asMethod(context)(context, iterable, nullptr, context->newList(), nullptr);
    if (!it) return PROTO_NONE;
    const proto::ProtoObject* nextM = it->getAttribute(context, PythonEnvironment::getInternalString(context, "__next__"));
    if (!nextM || !nextM->asMethod(context)) return PROTO_NONE;
    std::string out;
    bool first = true;
    for (;;) {
        const proto::ProtoObject* item = nextM->asMethod(context)(context, it, nullptr, context->newList(), nullptr);
        if (!item || item == PROTO_NONE) break;
        if (!first) out += sepStr;
        first = false;
        if (item->isInteger(context)) {
            long long v = item->asLong(context);
            if (v >= 0 && v <= 255) out += static_cast<char>(static_cast<unsigned char>(v));
        } else {
            std::string p;
            if (bytes_view(context, item, p)) out += p;
        }
    }
    return bytes_make_object(context, out.data(), static_cast<unsigned long>(out.size()));
}

static const proto::ProtoString* str_from_self(proto::ProtoContext* context, const proto::ProtoObject* self) {
    if (self->isString(context)) return self->asString(context);
    const proto::ProtoObject* data = self->getAttribute(context, PythonEnvironment::getInternalString(context, "__data__"));
    return data && data->isString(context) ? data->asString(context) : nullptr;
}

static const proto::ProtoObject* py_str_iter(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    const proto::ProtoString* str = str_from_self(context, self);
    if (!str) return PROTO_NONE;
    const proto::ProtoStringIterator* it = str->getIterator(context);
    return it ? it->asObject(context) : PROTO_NONE;
}

// Helper: extract str from receiver in bound and unbound forms.  When
// posOff is non-null, on the unbound match it's set to 1 so the caller
// can skip the receiver positional in subsequent arg parsing.
static const proto::ProtoString* str_from_self_or_arg(proto::ProtoContext* context,
        const proto::ProtoObject* self, const proto::ProtoList* posArgs,
        int* posOff) {
    const proto::ProtoString* s = str_from_self(context, self);
    if (posOff) *posOff = 0;
    if (!s && posArgs && posArgs->getSize(context) >= 1) {
        s = str_from_self(context, posArgs->getAt(context, 0));
        if (s && posOff) *posOff = 1;
    }
    return s;
}

enum class StrCmpOp { Lt, Le, Eq, Ne, Gt, Ge };

static const proto::ProtoObject* py_str_cmp_dispatch(proto::ProtoContext* context,
        const proto::ProtoObject* self, const proto::ProtoList* args,
        StrCmpOp op) {
    int posOff = 0;
    const proto::ProtoString* a = str_from_self_or_arg(context, self, args, &posOff);
    if (!a || !args || args->getSize(context) < static_cast<unsigned long>(1 + posOff)) {
        PythonEnvironment* env = PythonEnvironment::fromContext(context);
        return env ? env->getNotImplementedPrototype() : PROTO_NONE;
    }
    const proto::ProtoObject* bObj = args->getAt(context, posOff);
    if (!bObj || !bObj->isString(context)) {
        PythonEnvironment* env = PythonEnvironment::fromContext(context);
        return env ? env->getNotImplementedPrototype() : PROTO_NONE;
    }
    const proto::ProtoString* b = bObj->asString(context);
    std::string sa, sb;
    a->toUTF8String(context, sa);
    b->toUTF8String(context, sb);
    int c = sa.compare(sb);
    bool r = false;
    switch (op) {
        case StrCmpOp::Lt: r = c <  0; break;
        case StrCmpOp::Le: r = c <= 0; break;
        case StrCmpOp::Eq: r = c == 0; break;
        case StrCmpOp::Ne: r = c != 0; break;
        case StrCmpOp::Gt: r = c >  0; break;
        case StrCmpOp::Ge: r = c >= 0; break;
    }
    return r ? PROTO_TRUE : PROTO_FALSE;
}

static const proto::ProtoObject* py_str_lt(
    proto::ProtoContext* ctx, const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* args, const proto::ProtoSparseList*) {
    return py_str_cmp_dispatch(ctx, self, args, StrCmpOp::Lt);
}
static const proto::ProtoObject* py_str_le(
    proto::ProtoContext* ctx, const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* args, const proto::ProtoSparseList*) {
    return py_str_cmp_dispatch(ctx, self, args, StrCmpOp::Le);
}
static const proto::ProtoObject* py_str_eq_dunder(
    proto::ProtoContext* ctx, const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* args, const proto::ProtoSparseList*) {
    return py_str_cmp_dispatch(ctx, self, args, StrCmpOp::Eq);
}
static const proto::ProtoObject* py_str_ne_dunder(
    proto::ProtoContext* ctx, const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* args, const proto::ProtoSparseList*) {
    return py_str_cmp_dispatch(ctx, self, args, StrCmpOp::Ne);
}
static const proto::ProtoObject* py_str_gt(
    proto::ProtoContext* ctx, const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* args, const proto::ProtoSparseList*) {
    return py_str_cmp_dispatch(ctx, self, args, StrCmpOp::Gt);
}
static const proto::ProtoObject* py_str_ge(
    proto::ProtoContext* ctx, const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* args, const proto::ProtoSparseList*) {
    return py_str_cmp_dispatch(ctx, self, args, StrCmpOp::Ge);
}

static const proto::ProtoObject* py_str_contains(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    const proto::ProtoString* str = str_from_self(context, self);
    const proto::ProtoObject* item = nullptr;
    if (!str && positionalParameters && positionalParameters->getSize(context) >= 2) {
        // Unbound: str.__contains__(receiver, needle)
        str = str_from_self(context, positionalParameters->getAt(context, 0));
        item = positionalParameters->getAt(context, 1);
    } else if (positionalParameters && positionalParameters->getSize(context) >= 1) {
        item = positionalParameters->getAt(context, 0);
    }
    if (!str) return PROTO_FALSE;
    if (!item) return PROTO_FALSE;
    if (!item->isString(context)) {
        // CPython: `5 in 'hello'` raises
        //   TypeError: 'in <string>' requires string as left operand, not int
        // Previously the function silently returned False, masking
        // type bugs at every call site.
        PythonEnvironment* env = PythonEnvironment::fromContext(context);
        if (env) {
            std::string clsName = "object";
            const proto::ProtoObject* cls = env->getType(context, item);
            if (cls) {
                const proto::ProtoObject* nm = cls->getAttribute(context, env->getNameString());
                if (nm && nm->isString(context)) nm->asString(context)->toUTF8String(context, clsName);
            }
            env->raiseTypeError(context,
                "'in <string>' requires string as left operand, not " + clsName);
        }
        return nullptr;
    }
    std::string haystack;
    str->toUTF8String(context, haystack);
    std::string needle;
    item->asString(context)->toUTF8String(context, needle);
    return haystack.find(needle) != std::string::npos ? PROTO_TRUE : PROTO_FALSE;
}

static bool is_ascii_whitespace(char c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v';
}

static bool char_in_chars(unsigned char c, const std::string& ch) {
    if (ch.empty()) return is_ascii_whitespace(c);
    return ch.find(c) != std::string::npos;
}

static const proto::ProtoObject* py_str_find(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    const proto::ProtoString* str = str_from_self(context, self);
    int posOff = 0;
    if (!str && positionalParameters && positionalParameters->getSize(context) >= 2) {
        str = str_from_self(context, positionalParameters->getAt(context, 0));
        if (str) posOff = 1;
    }
    if (!str || positionalParameters->getSize(context) < static_cast<unsigned long>(1 + posOff)) return context->fromInteger(-1);
    if (posOff > 0) {
        proto::ProtoList* shifted = const_cast<proto::ProtoList*>(context->newList());
        for (unsigned long i = posOff; i < positionalParameters->getSize(context); ++i) {
            shifted = const_cast<proto::ProtoList*>(shifted->appendLast(context, positionalParameters->getAt(context, static_cast<int>(i))));
        }
        positionalParameters = shifted;
    }
    std::string haystack;
    str->toUTF8String(context, haystack);
    const proto::ProtoObject* subObj = positionalParameters->getAt(context, 0);
    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    if (!subObj->isString(context)) {
        if (env) env->raiseTypeError(context, "substring must be str");
        return context->fromInteger(-1);
    }
    std::string needle;
    subObj->asString(context)->toUTF8String(context, needle);

    long long start = 0;
    long long end = static_cast<long long>(haystack.size());
    if (positionalParameters->getSize(context) >= 2) {
        const proto::ProtoObject* sObj = positionalParameters->getAt(context, 1);
        if (sObj->isInteger(context)) {
            start = sObj->asLong(context);
            if (start < 0) start += static_cast<long long>(haystack.size());
            if (start < 0) start = 0;
        }
    }
    if (positionalParameters->getSize(context) >= 3) {
        const proto::ProtoObject* eObj = positionalParameters->getAt(context, 2);
        if (eObj->isInteger(context)) {
            end = eObj->asLong(context);
            if (end < 0) end += static_cast<long long>(haystack.size());
            if (end > static_cast<long long>(haystack.size())) end = static_cast<long long>(haystack.size());
        }
    }

    if (start > static_cast<long long>(haystack.size())) return context->fromInteger(-1);
    if (end < start) return context->fromInteger(-1);

    std::string searchSpace = haystack.substr(static_cast<size_t>(start), static_cast<size_t>(end - start));
    size_t pos = searchSpace.find(needle);
    return context->fromInteger(pos == std::string::npos ? -1 : static_cast<long long>(pos + start));
}

static const proto::ProtoObject* py_str_index(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    const proto::ProtoObject* result = py_str_find(context, self, parentLink, positionalParameters, keywordParameters);
    if (!result || !result->isInteger(context)) return PROTO_NONE;
    long long pos = result->asLong(context);
    if (pos < 0) {
        PythonEnvironment* env = PythonEnvironment::fromContext(context);
        if (env) env->raiseValueError(context, PythonEnvironment::getInternedString(context, "substring not found")->asObject(context));
        return PROTO_NONE;
    }
    return result;
}

static const proto::ProtoObject* py_str_rfind(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    const proto::ProtoString* str = str_from_self(context, self);
    if (!str || posArgs->getSize(context) < 1) return context->fromInteger(-1);
    std::string haystack;
    str->toUTF8String(context, haystack);
    const proto::ProtoObject* subObj = posArgs->getAt(context, 0);
    if (!subObj->isString(context)) {
        // CPython: rfind requires a str needle.  Silent -1 hid type bugs
        // exactly the way str.find used to before being fixed.
        PythonEnvironment* envE = PythonEnvironment::fromContext(context);
        if (envE) envE->raiseTypeError(context, "substring must be str");
        return nullptr;
    }
    std::string needle;
    subObj->asString(context)->toUTF8String(context, needle);
    long long start = 0, end = static_cast<long long>(haystack.size());
    if (posArgs->getSize(context) >= 2 && posArgs->getAt(context, 1)->isInteger(context))
        start = posArgs->getAt(context, 1)->asLong(context);
    if (posArgs->getSize(context) >= 3 && posArgs->getAt(context, 2)->isInteger(context))
        end = posArgs->getAt(context, 2)->asLong(context);
    if (start < 0) start = 0;
    if (end > static_cast<long long>(haystack.size())) end = static_cast<long long>(haystack.size());
    if (start >= end) return context->fromInteger(-1);
    std::string slice = haystack.substr(static_cast<size_t>(start), static_cast<size_t>(end - start));
    size_t found = slice.rfind(needle);
    if (found == std::string::npos) return context->fromInteger(-1);
    return context->fromInteger(static_cast<long long>(start) + static_cast<long long>(found));
}

static const proto::ProtoObject* py_str_rindex(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    const proto::ProtoObject* r = py_str_rfind(context, self, nullptr, posArgs, nullptr);
    if (!r || !r->isInteger(context) || r->asLong(context) < 0) {
        PythonEnvironment* env = PythonEnvironment::fromContext(context);
        if (env) env->raiseValueError(context, PythonEnvironment::getInternedString(context, "substring not found")->asObject(context));
        return PROTO_NONE;
    }
    return r;
}

static const proto::ProtoObject* py_str_count(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    const proto::ProtoString* str = str_from_self(context, self);
    int posOff = 0;
    if (!str && positionalParameters && positionalParameters->getSize(context) >= 2) {
        str = str_from_self(context, positionalParameters->getAt(context, 0));
        if (str) posOff = 1;
    }
    if (!str || positionalParameters->getSize(context) < static_cast<unsigned long>(1 + posOff)) return context->fromInteger(0);
    if (posOff > 0) {
        proto::ProtoList* shifted = const_cast<proto::ProtoList*>(context->newList());
        for (unsigned long i = posOff; i < positionalParameters->getSize(context); ++i) {
            shifted = const_cast<proto::ProtoList*>(shifted->appendLast(context, positionalParameters->getAt(context, static_cast<int>(i))));
        }
        positionalParameters = shifted;
    }
    std::string haystack;
    str->toUTF8String(context, haystack);
    const proto::ProtoObject* subObj = positionalParameters->getAt(context, 0);
    if (!subObj->isString(context)) {
        // CPython: str.count requires a str needle.  Returning 0 silently
        // hid type bugs (e.g. count(5) treated as "no match" rather than
        // surfacing the misuse).
        PythonEnvironment* envE = PythonEnvironment::fromContext(context);
        if (envE) envE->raiseTypeError(context,
            "must be str, not "
            + std::string(subObj == PROTO_NONE ? "NoneType"
                          : subObj->isInteger(context) ? "int"
                          : subObj->isFloat(context) ? "float"
                          : "object"));
        return nullptr;
    }
    std::string needle;
    subObj->asString(context)->toUTF8String(context, needle);
    if (needle.empty()) return context->fromInteger(static_cast<long long>(haystack.size()) + 1);
    long long start = 0;
    long long end = static_cast<long long>(haystack.size());
    if (positionalParameters->getSize(context) >= 2 && positionalParameters->getAt(context, 1) != PROTO_NONE)
        start = positionalParameters->getAt(context, 1)->asLong(context);
    if (positionalParameters->getSize(context) >= 3 && positionalParameters->getAt(context, 2) != PROTO_NONE)
        end = positionalParameters->getAt(context, 2)->asLong(context);
    if (start < 0) start += static_cast<long long>(haystack.size());
    if (end < 0) end += static_cast<long long>(haystack.size());
    if (start < 0) start = 0;
    if (end > static_cast<long long>(haystack.size())) end = static_cast<long long>(haystack.size());
    if (start >= end) return context->fromInteger(0);
    size_t count = 0;
    size_t pos = static_cast<size_t>(start);
    const size_t endPos = static_cast<size_t>(end);
    while (pos < endPos) {
        size_t found = haystack.find(needle, pos);
        if (found == std::string::npos || found >= endPos) break;
        count++;
        pos = found + needle.size();
    }
    return context->fromInteger(static_cast<long long>(count));
}

static const proto::ProtoObject* py_str_bool(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    const proto::ProtoString* str = str_from_self(context, self);
    if (!str) return PROTO_FALSE;
    return str->getSize(context) > 0 ? PROTO_TRUE : PROTO_FALSE;
}

static const proto::ProtoObject* py_str_getitem(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    const proto::ProtoString* str = str_from_self(context, self);
    int indexArgOff = 0;
    // Unbound form: `str.__getitem__("hello", slice(4))` — self is
    // the str type rather than a string, and positional[0] carries
    // the actual receiver.  Detect by trying str_from_self on
    // positional[0] when self yielded nothing.
    if (!str && positionalParameters && positionalParameters->getSize(context) >= 1) {
        str = str_from_self(context, positionalParameters->getAt(context, 0));
        if (str) indexArgOff = 1;
    }
    if (!str || positionalParameters->getSize(context) < static_cast<unsigned long>(indexArgOff + 1)) return PROTO_NONE;
    std::string s;
    str->toUTF8String(context, s);
    long long size = static_cast<long long>(s.size());
    const proto::ProtoObject* indexObj = positionalParameters->getAt(context, indexArgOff);

    SliceBounds sb = get_slice_bounds(context, indexObj, size);
    if (sb.isSlice) {
        std::string sub;
        for (long long i = sb.start; (sb.step > 0 ? i < sb.stop : i > sb.stop); i += sb.step) {
            sub += s[static_cast<size_t>(i)];
        }
        return PythonEnvironment::getInternedString(context, sub.c_str())->asObject(context);
    }

    // bool subclasses int — accept True/False as 1/0.
    if (indexObj->isInteger(context) || indexObj == PROTO_TRUE || indexObj == PROTO_FALSE) {
        int idx = indexObj == PROTO_TRUE ? 1
                : indexObj == PROTO_FALSE ? 0
                : static_cast<int>(indexObj->asLong(context));
        if (idx < 0) idx += static_cast<int>(size);
        if (idx < 0 || static_cast<unsigned long>(idx) >= size) {
            PythonEnvironment* env = PythonEnvironment::fromContext(context);
            if (env) env->raiseIndexError(context, "string index out of range");
            return PROTO_NONE;
        }
        char c[2] = { s[static_cast<size_t>(idx)], '\0' };
        return PythonEnvironment::getInternedString(context, c)->asObject(context);
    }

    // CPython __index__ protocol — same fix as list / tuple subscript.
    {
        PythonEnvironment* envE = PythonEnvironment::fromContext(context);
        if (envE) {
            const proto::ProtoString* indexS =
                PythonEnvironment::getInternedString(context, "__index__");
            const proto::ProtoObject* indexM = envE->getAttribute(context, indexObj, indexS, false);
            if (indexM && indexM != PROTO_NONE) {
                const proto::ProtoObject* idxRes = nullptr;
                if (indexM->asMethod(context)) {
                    idxRes = indexM->asMethod(context)(context,
                        const_cast<proto::ProtoObject*>(indexObj), nullptr,
                        envE->getEmptyList(), nullptr);
                } else {
                    const proto::ProtoList* sa = context->newList()->appendLast(context, indexObj);
                    idxRes = ::protoPython::invokePythonCallable(context, indexM, sa, nullptr);
                }
                if (idxRes && idxRes->isInteger(context)) {
                    int idx = static_cast<int>(idxRes->asLong(context));
                    if (idx < 0) idx += static_cast<int>(size);
                    if (idx < 0 || static_cast<unsigned long>(idx) >= size) {
                        envE->raiseIndexError(context, "string index out of range");
                        return PROTO_NONE;
                    }
                    char c[2] = { s[static_cast<size_t>(idx)], '\0' };
                    return PythonEnvironment::getInternedString(context, c)->asObject(context);
                }
            }
        }
    }

    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    if (env) env->raiseTypeError(context, "string indices must be integers or slices");
    return PROTO_NONE;
}

static const proto::ProtoObject* py_slice_call(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    const proto::ProtoString* startName = env ? env->getStartString() : PythonEnvironment::getInternedString(context, "start");
    const proto::ProtoString* stopName = env ? env->getStopString() : PythonEnvironment::getInternedString(context, "stop");
    const proto::ProtoString* stepName = env ? env->getStepString() : PythonEnvironment::getInternedString(context, "step");
    unsigned long n = positionalParameters ? positionalParameters->getSize(context) : 0UL;
    // When invoked as __new__ (via type.__call__), positionalParameters[0]
    // is the cls (sliceType).  When invoked as a direct method, args
    // start at [0].  Detect by comparing the first positional to the
    // sliceType prototype.
    unsigned long base = 0;
    const proto::ProtoObject* targetCls = self;
    if (n >= 1 && env && env->getSliceType()) {
        const proto::ProtoObject* first = positionalParameters->getAt(context, 0);
        if (first == env->getSliceType()) {
            base = 1;
            targetCls = first;
        }
    }
    unsigned long argCount = n - base;
    // CPython: slice() requires at least 1 positional argument.  Without
    // this guard `slice()` returned slice(None, None, None) silently —
    // every misuse looked like a "match everything" slice and the bug
    // never surfaced.
    if (argCount == 0) {
        if (env) env->raiseTypeError(context,
            "slice expected at least 1 argument, got 0");
        return nullptr;
    }
    const proto::ProtoObject* start = PROTO_NONE;
    const proto::ProtoObject* stop = PROTO_NONE;
    const proto::ProtoObject* step = PROTO_NONE;
    if (argCount == 1) {
        stop = positionalParameters->getAt(context, base);
    } else if (argCount >= 2) {
        start = positionalParameters->getAt(context, base);
        stop = positionalParameters->getAt(context, base + 1);
        if (argCount >= 3) step = positionalParameters->getAt(context, base + 2);
    }
    const proto::ProtoObject* sliceObj = context->newObject(false);
    if (targetCls) sliceObj = sliceObj->addParent(context, targetCls);
    // CPython slice(): missing args become None, NOT 0.  The previous
    // defaults (0 for start/stop, 1 for step) made
    // `slice(100, 200).step` return 1 instead of None and broke
    // user code that branches on `step is None`.
    sliceObj = sliceObj->setAttribute(context, startName, start);
    sliceObj = sliceObj->setAttribute(context, stopName, stop);
    sliceObj = sliceObj->setAttribute(context, stepName, step);
    return sliceObj;
}

static const proto::ProtoObject* py_slice_repr(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    if (env && self == env->getSliceType()) {
        return py_type_repr(context, self, parentLink, positionalParameters, keywordParameters);
    }
    const proto::ProtoObject* start = self->getAttribute(context, env ? env->getStartString() : PythonEnvironment::getInternedString(context, "start"));
    const proto::ProtoObject* stop = self->getAttribute(context, env ? env->getStopString() : PythonEnvironment::getInternedString(context, "stop"));
    const proto::ProtoObject* step = self->getAttribute(context, env ? env->getStepString() : PythonEnvironment::getInternedString(context, "step"));
    // CPython slice repr always includes the third (step) component
    // even when None or 1: `slice(None, 5, None)`, `slice(1, 10, 2)`,
    // `slice(1, 10, None)`.  Previously the step was elided unless it
    // was a non-default int — `slice(5)` printed as `slice(None, 5)`
    // which doesn't round-trip through `eval(repr(s))`.
    auto fmt = [&](const proto::ProtoObject* v) -> std::string {
        if (!v || v == PROTO_NONE) return "None";
        if (v->isInteger(context)) return std::to_string(v->asLong(context));
        return PythonEnvironment::reprObject(context, v);
    };
    std::string out = "slice(" + fmt(start) + ", " + fmt(stop) + ", " + fmt(step) + ")";
    return PythonEnvironment::getInternedString(context, out.c_str())->asObject(context);
}

static const proto::ProtoObject* py_str_upper(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    const proto::ProtoString* str = str_from_self(context, self);
    // Unbound form: str.upper(thing) — self may be the class.
    if (!str && positionalParameters && positionalParameters->getSize(context) >= 1) {
        str = str_from_self(context, positionalParameters->getAt(context, 0));
    }
    if (!str) {
        PythonEnvironment* env = PythonEnvironment::fromContext(context);
        if (env) env->raiseTypeError(context,
            "descriptor 'upper' for 'str' objects doesn't apply to a non-str object");
        return nullptr;
    }
    std::string s;
    str->toUTF8String(context, s);
    for (char& c : s) {
        if (c >= 'a' && c <= 'z') c -= 32;
    }
    return PythonEnvironment::getInternedString(context, s.c_str())->asObject(context);
}

// Apply a format spec (like "02d", ".2f", ">10s") to an object's string representation.
// Mirror CPython's default __format__: when the spec is empty, the
// conversion is `str(obj)`, not `repr(obj)`.  reprObject quotes strings
// (`'a'`) which is the right shape for `{!r}` but wrong for `{}`.
static std::string applyFormatSpec(proto::ProtoContext* context, const proto::ProtoObject* obj, const std::string& spec) {
    if (spec.empty()) {
        if (obj && obj->isString(context)) {
            std::string s;
            obj->asString(context)->toUTF8String(context, s);
            return s;
        }
        return PythonEnvironment::reprObject(context, obj);
    }
    // Parse the format spec: [[fill]align][sign][#][0][width][grouping][.precision][type]
    size_t si = 0;
    char fill = ' ';
    char align = '\0';
    // Check for optional [[fill]align]
    if (spec.size() >= 2 && (spec[1] == '<' || spec[1] == '>' || spec[1] == '^' || spec[1] == '=')) {
        fill = spec[si++];
        align = spec[si++];
    } else if (si < spec.size() && (spec[si] == '<' || spec[si] == '>' || spec[si] == '^' || spec[si] == '=')) {
        align = spec[si++];
    }
    // Sign
    char signChar = '\0';
    if (si < spec.size() && (spec[si] == '+' || spec[si] == '-' || spec[si] == ' '))
        signChar = spec[si++];
    // '#' alt form
    bool altForm = false;
    if (si < spec.size() && spec[si] == '#') { altForm = true; si++; }
    // Zero-fill flag: a leading '0' before width digits is always the zero-fill flag
    if (si < spec.size() && spec[si] == '0') {
        si++;  // consume the zero-fill flag
        if (align == '\0') { align = '='; fill = '0'; }
    }
    // Width (digits after optional zero-fill)
    int width = 0;
    while (si < spec.size() && spec[si] >= '0' && spec[si] <= '9')
        width = width * 10 + (spec[si++] - '0');
    // Grouping
    if (si < spec.size() && (spec[si] == '_' || spec[si] == ',')) si++;
    // Precision
    int prec = -1;
    if (si < spec.size() && spec[si] == '.') {
        si++;
        prec = 0;
        while (si < spec.size() && spec[si] >= '0' && spec[si] <= '9')
            prec = prec * 10 + (spec[si++] - '0');
    }
    // Type
    char type = '\0';
    if (si < spec.size()) type = spec[si];

    // Build snprintf-compatible format string and convert object
    std::string result;
    if (type == 'd' || type == 'i' || type == 'o' || type == 'x' || type == 'X'
        || type == 'b' || type == 'u' || type == 'n') {
        long long v = obj ? obj->asLong(context) : 0LL;
        // Reconstruct a C format string
        std::string cfmt = "%";
        if (signChar) cfmt += signChar;
        if (altForm && (type == 'x' || type == 'X' || type == 'o')) cfmt += '#';
        if (fill == '0' && (align == '=' || align == '\0')) cfmt += '0';
        if (width > 0) cfmt += std::to_string(width);
        if (prec >= 0) { cfmt += '.'; cfmt += std::to_string(prec); }
        cfmt += "ll";
        if (type == 'b') {
            // binary: manual
            if (v == 0) { result = "0"; }
            else {
                unsigned long long uv = static_cast<unsigned long long>(v);
                result = "";
                while (uv > 0) { result = (char)('0' + (uv & 1)) + result; uv >>= 1; }
            }
            if (altForm) result = "0b" + result;
        } else {
            char t = (type == 'u' || type == 'n') ? 'd' : type;
            cfmt += t;
            char buf[128]; snprintf(buf, sizeof(buf), cfmt.c_str(), v);
            result = buf;
        }
    } else if (type == 'f' || type == 'F' || type == 'e' || type == 'E'
               || type == 'g' || type == 'G' || type == '%') {
        double v = obj ? obj->asDouble(context) : 0.0;
        if (type == '%') v *= 100.0;
        std::string cfmt = "%";
        if (signChar) cfmt += signChar;
        if (fill == '0' && (align == '=' || align == '\0')) cfmt += '0';
        if (width > 0) cfmt += std::to_string(width);
        if (prec >= 0) { cfmt += '.'; cfmt += std::to_string(prec); }
        else if (type == 'f' || type == 'F' || type == '%') { cfmt += ".6"; }
        cfmt += (type == '%') ? 'f' : type;
        char buf[256]; snprintf(buf, sizeof(buf), cfmt.c_str(), v);
        result = buf;
        if (type == '%') result += '%';
    } else if (type == 's' || type == '\0') {
        // 's' (and the default '\0' for non-numeric types) mirrors str(),
        // not repr(): a string renders as its bare content, never quoted.
        if (obj && obj->isString(context)) {
            obj->asString(context)->toUTF8String(context, result);
        } else {
            result = PythonEnvironment::reprObject(context, obj);
        }
        if (prec >= 0 && static_cast<int>(result.size()) > prec)
            result = result.substr(0, prec);
    } else if (type == 'c') {
        if (obj && obj->isString(context)) {
            std::string s; obj->asString(context)->toUTF8String(context, s);
            result = s.empty() ? "" : std::string(1, s[0]);
        } else {
            result = std::string(1, static_cast<char>(obj ? obj->asLong(context) : 0));
        }
    } else {
        result = PythonEnvironment::reprObject(context, obj);
    }

    // Apply width and alignment
    if (width > 0 && static_cast<int>(result.size()) < width) {
        int pad = width - static_cast<int>(result.size());
        if (align == '<' || (align == '\0' && (type == 's' || type == '\0'))) {
            result = result + std::string(pad, fill);
        } else if (align == '^') {
            int lpad = pad / 2, rpad = pad - lpad;
            result = std::string(lpad, fill) + result + std::string(rpad, fill);
        } else {
            // '>' or '=' or default for numbers
            result = std::string(pad, fill) + result;
        }
    }
    return result;
}

static const proto::ProtoObject* py_str_format(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    int formatPosOff = 0;
    const proto::ProtoString* str = str_from_self_or_arg(context, self, positionalParameters, &formatPosOff);
    if (!str) return PROTO_NONE;
    std::string tpl;
    str->toUTF8String(context, tpl);
    std::string out;
    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    unsigned long autoIdx = static_cast<unsigned long>(formatPosOff);

    for (size_t i = 0; i < tpl.size(); ++i) {
        if (tpl[i] == '{' && i + 1 < tpl.size() && tpl[i + 1] == '{') {
            out += '{'; i++; continue;
        }
        if (tpl[i] == '}' && i + 1 < tpl.size() && tpl[i + 1] == '}') {
            out += '}'; i++; continue;
        }
        if (tpl[i] != '{') { out += tpl[i]; continue; }

        // Find matching '}'
        ++i;
        size_t fieldStart = i;
        int depth = 1;
        while (i < tpl.size() && depth > 0) {
            if (tpl[i] == '{') ++depth;
            else if (tpl[i] == '}') --depth;
            if (depth > 0) ++i;
        }
        std::string field = tpl.substr(fieldStart, i - fieldStart);

        // Parse: field_name (!conversion) (:format_spec)
        std::string fieldName, formatSpec;
        char conversion = '\0';
        size_t excl = field.find('!');
        size_t colon = field.find(':');
        // colon inside nested braces is part of format_spec
        if (excl != std::string::npos && (colon == std::string::npos || excl < colon)) {
            fieldName = field.substr(0, excl);
            if (excl + 1 < field.size()) conversion = field[excl + 1];
            if (colon != std::string::npos) formatSpec = field.substr(colon + 1);
        } else if (colon != std::string::npos) {
            fieldName = field.substr(0, colon);
            formatSpec = field.substr(colon + 1);
        } else {
            fieldName = field;
        }

        // Resolve value
        const proto::ProtoObject* val = PROTO_NONE;
        if (fieldName.empty()) {
            // auto-index
            if (positionalParameters && autoIdx < positionalParameters->getSize(context))
                val = positionalParameters->getAt(context, static_cast<int>(autoIdx));
            autoIdx++;
        } else if (!fieldName.empty() && fieldName[0] >= '0' && fieldName[0] <= '9') {
            // numeric index — shifted by formatPosOff when called unbound
            unsigned long idx = std::stoul(fieldName) + static_cast<unsigned long>(formatPosOff);
            if (positionalParameters && idx < positionalParameters->getSize(context))
                val = positionalParameters->getAt(context, static_cast<int>(idx));
        } else {
            // keyword
            if (keywordParameters && env) {
                const proto::ProtoString* keyS = PythonEnvironment::getInternedString(context, fieldName.c_str());
                const proto::ProtoObject* found = keywordParameters->getAt(context, keyS->getHash(context));
                if (found) val = found;
            }
        }

        // Apply conversion
        if (conversion == 'r') {
            std::string s = PythonEnvironment::reprObject(context, val);
            // Add quotes for strings
            if (val && val->isString(context)) {
                std::string raw; val->asString(context)->toUTF8String(context, raw);
                s = "'" + raw + "'";
            }
            out += formatSpec.empty() ? s : applyFormatSpec(context, PythonEnvironment::getInternedString(context, s.c_str())->asObject(context), formatSpec);
        } else if (conversion == 's') {
            // !s applies str(), which for str returns the bare content
            // (no quotes).  reprObject would re-quote it.
            std::string s;
            if (val && val->isString(context)) {
                val->asString(context)->toUTF8String(context, s);
            } else {
                s = PythonEnvironment::reprObject(context, val);
            }
            out += formatSpec.empty() ? s : applyFormatSpec(context, PythonEnvironment::getInternedString(context, s.c_str())->asObject(context), formatSpec);
        } else {
            out += applyFormatSpec(context, val, formatSpec);
        }
    }
    return PythonEnvironment::getInternedString(context, out.c_str())->asObject(context);
}

// str.__mod__(other): implements "format_string % args"
static const proto::ProtoObject* py_str_mod(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList*) {
    const proto::ProtoString* fmtStr = str_from_self(context, self);
    if (!fmtStr) return PROTO_NONE;
    std::string fmt;
    fmtStr->toUTF8String(context, fmt);

    // Collect arguments: single value or a tuple
    const proto::ProtoObject* argObj = (positionalParameters && positionalParameters->getSize(context) >= 1)
        ? positionalParameters->getAt(context, 0) : PROTO_NONE;
    const proto::ProtoTuple* argTuple = argObj ? argObj->asTuple(context) : nullptr;
    unsigned long argCount = argTuple ? argTuple->getSize(context) : 1;
    unsigned long argIdx = 0;

    // Tracks whether getNextArg fell off the end so the caller can raise
    // TypeError("not enough arguments for format string") — the prior
    // behaviour returned PROTO_NONE and silently rendered "None" for the
    // missing slot.  Treating PROTO_NONE as a sentinel doesn't work
    // because `'%s' % None` is a legitimate call producing 'None'.
    bool argExhausted = false;
    auto getNextArg = [&]() -> const proto::ProtoObject* {
        if (argTuple) {
            if (argIdx >= argTuple->getSize(context)) {
                argExhausted = true;
                return PROTO_NONE;
            }
            return argTuple->getAt(context, static_cast<int>(argIdx++));
        }
        if (argIdx > 0) {
            argExhausted = true;
            return PROTO_NONE;
        }
        argIdx++;
        return argObj;
    };

    PythonEnvironment* env = PythonEnvironment::fromContext(context);

    // Numeric extraction helpers — tolerate int/float subclasses, whose
    // tagged value lives behind `__data__` rather than in the receiver
    // pointer itself.  CPython's PyArg %d / %f routines do the same via
    // nb_int / nb_float; here we short-circuit to __data__ which is the
    // canonical storage convention for wrapped numerics.
    auto extractDouble = [&](const proto::ProtoObject* x) -> double {
        if (!x || x == PROTO_NONE) return 0.0;
        if (x->isInteger(context)) return static_cast<double>(x->asLong(context));
        if (x->isBoolean(context)) return (x == PROTO_TRUE) ? 1.0 : 0.0;
        if (x->isFloat(context)) return x->asDouble(context);
        const proto::ProtoString* dataS = env ? env->getDataString()
            : PythonEnvironment::getInternalString(context, "__data__");
        const proto::ProtoObject* d = x->getAttribute(context, dataS);
        if (d && d != PROTO_NONE) {
            if (d->isFloat(context))   return d->asDouble(context);
            if (d->isInteger(context)) return static_cast<double>(d->asLong(context));
        }
        return 0.0;
    };
    // Numeric arg validation for %d/%i/%u/%o/%x/%X: CPython raises
    //   TypeError: %d format: a number is required, not <type>
    // when the arg is not int / float / bool / wrapped-numeric.  Previously
    // extractLong silently returned 0 for str / list / None, masking
    // misuse like `'%d' % 'a'`.
    auto requireNumeric = [&](char spec, const proto::ProtoObject* x) -> bool {
        bool isNum = false;
        if (x && x != PROTO_NONE) {
            if (x->isInteger(context) || x->isFloat(context) || x->isBoolean(context)) {
                isNum = true;
            } else {
                const proto::ProtoString* dataS = env ? env->getDataString()
                    : PythonEnvironment::getInternalString(context, "__data__");
                const proto::ProtoObject* d = x->getAttribute(context, dataS);
                if (d && d != PROTO_NONE && (d->isInteger(context) || d->isFloat(context))) {
                    isNum = true;
                }
            }
        }
        if (!isNum) {
            if (env) {
                std::string clsName = "NoneType";
                if (x && x != PROTO_NONE) {
                    const proto::ProtoObject* cls = env->getType(context, x);
                    if (cls) {
                        const proto::ProtoObject* nm = cls->getAttribute(context, env->getNameString());
                        if (nm && nm->isString(context)) nm->asString(context)->toUTF8String(context, clsName);
                    }
                }
                env->raiseTypeError(context,
                    std::string("%") + spec + " format: a number is required, not " + clsName);
            }
            return false;
        }
        return true;
    };

    auto extractLong = [&](const proto::ProtoObject* x) -> long long {
        if (!x || x == PROTO_NONE) return 0LL;
        if (x->isInteger(context)) return x->asLong(context);
        if (x->isBoolean(context)) return (x == PROTO_TRUE) ? 1LL : 0LL;
        if (x->isFloat(context))   return static_cast<long long>(x->asDouble(context));
        const proto::ProtoString* dataS = env ? env->getDataString()
            : PythonEnvironment::getInternalString(context, "__data__");
        const proto::ProtoObject* d = x->getAttribute(context, dataS);
        if (d && d != PROTO_NONE) {
            if (d->isInteger(context)) return d->asLong(context);
            if (d->isFloat(context))   return static_cast<long long>(d->asDouble(context));
        }
        return 0LL;
    };

    std::string out;
    for (size_t i = 0; i < fmt.size(); ++i) {
        if (fmt[i] != '%') {
            out += fmt[i];
            continue;
        }
        ++i;
        if (i >= fmt.size()) {
            // `'%' % None` and similar: trailing % with no conversion
            // is incomplete — CPython raises ValueError.
            if (env) env->raiseValueError(context,
                PythonEnvironment::getInternedString(context,
                    "incomplete format")->asObject(context));
            return nullptr;
        }

        // Dict-style key lookup: %(key)spec
        const proto::ProtoObject* dictArg = nullptr;
        if (fmt[i] == '(') {
            ++i; // skip '('
            size_t keyStart = i;
            while (i < fmt.size() && fmt[i] != ')') ++i;
            if (i >= fmt.size()) {
                // Unterminated mapping key — `'%(n' % {}`.
                if (env) env->raiseValueError(context,
                    PythonEnvironment::getInternedString(context,
                        "incomplete format key")->asObject(context));
                return nullptr;
            }
            std::string keyName = fmt.substr(keyStart, i - keyStart);
            if (i < fmt.size()) ++i; // skip ')'
            // CPython: %(key) requires the argument to be a mapping.
            // Reject None and primitive non-mappings up front.
            if (!argObj || argObj == PROTO_NONE
                || argObj->isString(context) || argObj->isInteger(context)
                || argObj->isFloat(context) || argObj->isBoolean(context)
                || (env && argObj == env->getNonePrototype())) {
                if (env) env->raiseTypeError(context,
                    "format requires a mapping");
                return nullptr;
            }
            // Look up the key in the dict argument
            const proto::ProtoString* keyStr = PythonEnvironment::getInternedString(context, keyName.c_str());
            if (env) {
                dictArg = env->getItem(argObj, keyStr->asObject(context), context);
            }
        }

        // Collect flags, width, precision to reconstruct snprintf format spec.
        // Python allows `*` in place of a numeric width or precision —
        // the value is pulled from the next positional argument and
        // converted to int.
        std::string fmtFlags;
        while (i < fmt.size() && (fmt[i] == '-' || fmt[i] == '+' || fmt[i] == ' ' || fmt[i] == '0' || fmt[i] == '#'))
            fmtFlags += fmt[i++];
        std::string fmtWidth;
        if (i < fmt.size() && fmt[i] == '*') {
            ++i;
            const proto::ProtoObject* widthArg = getNextArg();
            long long w = 0;
            if (widthArg && widthArg->isInteger(context)) {
                w = widthArg->asLong(context);
            } else if (widthArg && widthArg->isBoolean(context)) {
                w = widthArg->asBoolean(context) ? 1 : 0;
            } else {
                // `'%*s' % 'abc'` — * requires an int.
                if (env) env->raiseTypeError(context,
                    "* wants int");
                return nullptr;
            }
            if (w < 0) { fmtFlags += '-'; w = -w; }
            fmtWidth = std::to_string(w);
        } else {
            while (i < fmt.size() && fmt[i] >= '0' && fmt[i] <= '9')
                fmtWidth += fmt[i++];
        }
        std::string fmtPrec;
        if (i < fmt.size() && fmt[i] == '.') {
            fmtPrec += fmt[i++];
            if (i < fmt.size() && fmt[i] == '*') {
                ++i;
                const proto::ProtoObject* precArg = getNextArg();
                long long p = 0;
                if (precArg && precArg->isInteger(context)) {
                    p = precArg->asLong(context);
                } else if (precArg && precArg->isBoolean(context)) {
                    p = precArg->asBoolean(context) ? 1 : 0;
                } else {
                    if (env) env->raiseTypeError(context, "* wants int");
                    return nullptr;
                }
                if (p < 0) p = 0;
                fmtPrec += std::to_string(p);
            } else {
                while (i < fmt.size() && fmt[i] >= '0' && fmt[i] <= '9')
                    fmtPrec += fmt[i++];
            }
        }

        if (i >= fmt.size()) {
            if (env) env->raiseValueError(context,
                PythonEnvironment::getInternedString(context,
                    "incomplete format")->asObject(context));
            return nullptr;
        }
        char spec = fmt[i];

        if (spec == '%') {
            out += '%';
            continue;
        }

        // Rebuild a snprintf-compatible format string from collected parts
        // For integers: use ll; for floats: use standard; for strings: apply width/flags manually
        auto makeIntFmt = [&](char suffix) -> std::string {
            return std::string("%") + fmtFlags + fmtWidth + fmtPrec + "ll" + suffix;
        };
        auto makeFltFmt = [&](char suffix) -> std::string {
            return std::string("%") + fmtFlags + fmtWidth + fmtPrec + suffix;
        };

        const proto::ProtoObject* arg = dictArg ? dictArg : getNextArg();
        // CPython: a % conversion that consumes past the supplied tuple
        // raises TypeError("not enough arguments for format string").
        // The dictArg path is exempt: %(key)s carries its own argument
        // identity and never advances argIdx.  '%%' (handled above) also
        // doesn't consume an arg.
        if (!dictArg && argExhausted) {
            if (env) env->raiseTypeError(context,
                "not enough arguments for format string");
            return nullptr;
        }
        switch (spec) {
            case 's': {
                // CPython %s calls str(), NOT repr() — string args
                // come through verbatim (no quotes).
                std::string s;
                if (arg && arg != PROTO_NONE && arg->isString(context)) {
                    arg->asString(context)->toUTF8String(context, s);
                } else {
                    s = PythonEnvironment::reprObject(context, arg);
                }
                if (fmtWidth.empty() && fmtFlags.empty()) {
                    out += s;
                } else {
                    // Apply width and alignment manually for strings
                    int width = fmtWidth.empty() ? 0 : std::stoi(fmtWidth);
                    bool leftAlign = fmtFlags.find('-') != std::string::npos;
                    int pad = width - static_cast<int>(s.size());
                    if (!leftAlign && pad > 0) out.append(pad, ' ');
                    out += s;
                    if (leftAlign && pad > 0) out.append(pad, ' ');
                }
                break;
            }
            case 'r': {
                std::string s;
                if (arg && arg->isString(context)) {
                    std::string raw;
                    arg->asString(context)->toUTF8String(context, raw);
                    s += '\'';
                    for (unsigned char c : raw) {
                        if (c == '\'') { s += '\\'; s += '\''; }
                        else if (c == '\\') { s += "\\\\"; }
                        else if (c == '\n') { s += "\\n"; }
                        else if (c == '\r') { s += "\\r"; }
                        else if (c == '\t') { s += "\\t"; }
                        else if (c < 32 || c >= 127) { char buf[8]; snprintf(buf, sizeof(buf), "\\x%02x", c); s += buf; }
                        else s += c;
                    }
                    s += '\'';
                } else {
                    s = PythonEnvironment::reprObject(context, arg);
                }
                out += s;
                break;
            }
            case 'd':
            case 'i': {
                if (!requireNumeric(spec, arg)) return nullptr;
                long long v = extractLong(arg);
                char buf[64]; snprintf(buf, sizeof(buf), makeIntFmt('d').c_str(), v);
                out += buf;
                break;
            }
            case 'u': {
                if (!requireNumeric(spec, arg)) return nullptr;
                unsigned long long v = static_cast<unsigned long long>(extractLong(arg));
                char buf[64]; snprintf(buf, sizeof(buf), makeIntFmt('u').c_str(), v);
                out += buf;
                break;
            }
            case 'o': {
                if (!requireNumeric(spec, arg)) return nullptr;
                long long v = extractLong(arg);
                char buf[64]; snprintf(buf, sizeof(buf), makeIntFmt('o').c_str(), v);
                out += buf;
                break;
            }
            case 'x': {
                if (!requireNumeric(spec, arg)) return nullptr;
                long long v = extractLong(arg);
                char buf[64]; snprintf(buf, sizeof(buf), makeIntFmt('x').c_str(), v);
                out += buf;
                break;
            }
            case 'X': {
                if (!requireNumeric(spec, arg)) return nullptr;
                long long v = extractLong(arg);
                char buf[64]; snprintf(buf, sizeof(buf), makeIntFmt('X').c_str(), v);
                out += buf;
                break;
            }
            case 'f':
            case 'F': {
                if (!requireNumeric(spec, arg)) return nullptr;
                double v = extractDouble(arg);
                std::string ff = makeFltFmt(fmtPrec.empty() ? 'f' : spec);
                if (fmtPrec.empty()) ff = std::string("%") + fmtFlags + fmtWidth + ".6f";
                char buf[128]; snprintf(buf, sizeof(buf), ff.c_str(), v);
                out += buf;
                break;
            }
            case 'e':
            case 'E': {
                if (!requireNumeric(spec, arg)) return nullptr;
                double v = extractDouble(arg);
                char buf[128]; snprintf(buf, sizeof(buf), makeFltFmt(spec).c_str(), v);
                out += buf;
                break;
            }
            case 'g':
            case 'G': {
                if (!requireNumeric(spec, arg)) return nullptr;
                double v = extractDouble(arg);
                char buf[128]; snprintf(buf, sizeof(buf), makeFltFmt(spec).c_str(), v);
                out += buf;
                break;
            }
            case 'c': {
                // CPython: %c accepts an int 0..0x10FFFF or a single
                // character string.  Anything else (None, list, etc.)
                // raises TypeError: %c requires int or char.  Previously
                // the non-string branch fell through to asLong on
                // PROTO_NONE / list / etc. and crashed with the
                // internal "Object is not an integer type" RuntimeError.
                if (arg && arg->isString(context)) {
                    std::string s;
                    arg->asString(context)->toUTF8String(context, s);
                    if (!s.empty()) out += s[0];
                } else if (arg && arg != PROTO_NONE
                           && (arg->isInteger(context) || arg->isBoolean(context))) {
                    long long v = arg->isInteger(context)
                        ? arg->asLong(context)
                        : (arg == PROTO_TRUE ? 1LL : 0LL);
                    out += static_cast<char>(v & 0xFF);
                } else {
                    if (env) env->raiseTypeError(context,
                        "%c requires int or char");
                    return nullptr;
                }
                break;
            }
            default:
                out += '%';
                out += spec;
                break;
        }
    }
    // CPython: `'%s' % (1, 2)` — too many args raised
    // TypeError("not all arguments converted during string
    // formatting").  Tuple args are exhausted via argIdx; an
    // unused remainder is the trigger.  Single non-tuple arg is
    // considered consumed iff argIdx > 0 (i.e. at least one %
    // spec ran), which covers the `%s' % 'x'` shape too.
    if (env && argTuple && argIdx < argTuple->getSize(context)) {
        env->raiseTypeError(context,
            "not all arguments converted during string formatting");
        return nullptr;
    }
    return PythonEnvironment::getInternedString(context, out.c_str())->asObject(context);
}

static const proto::ProtoObject* py_str_lower(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink* parentLink,
    const proto::ProtoList* positionalParameters,
    const proto::ProtoSparseList* keywordParameters) {
    const proto::ProtoString* str = str_from_self(context, self);
    if (!str && positionalParameters && positionalParameters->getSize(context) >= 1) {
        str = str_from_self(context, positionalParameters->getAt(context, 0));
    }
    if (!str) return PROTO_NONE;
    std::string s;
    str->toUTF8String(context, s);
    for (char& c : s) {
        if (c >= 'A' && c <= 'Z') c += 32;
    }
    return PythonEnvironment::getInternedString(context, s.c_str())->asObject(context);
}

static const proto::ProtoObject* py_str_split(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    const proto::ProtoString* str = str_from_self(context, self);
    int posOff = 0;
    if (!str && posArgs && posArgs->getSize(context) >= 1) {
        // Unbound form: str.split(receiver, [sep], [maxsplit])
        str = str_from_self(context, posArgs->getAt(context, 0));
        if (str) posOff = 1;
    }
    if (!str) {
        PythonEnvironment* env = PythonEnvironment::fromContext(context);
        if (env) env->raiseTypeError(context,
            "descriptor 'split' for 'str' objects doesn't apply to a non-str object");
        return nullptr;
    }
    // Adjust posArgs to skip the unbound receiver, if present.
    if (posOff > 0) {
        proto::ProtoList* shifted = const_cast<proto::ProtoList*>(context->newList());
        for (unsigned long i = posOff; i < posArgs->getSize(context); ++i) {
            shifted = const_cast<proto::ProtoList*>(shifted->appendLast(context, posArgs->getAt(context, static_cast<int>(i))));
        }
        posArgs = shifted;
    }
    std::string s;
    str->toUTF8String(context, s);

    const proto::ProtoObject* sepObj = (posArgs && posArgs->getSize(context) >= 1) ? posArgs->getAt(context, 0) : nullptr;
    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    bool sepIsNone = !sepObj || (env && sepObj == env->getNonePrototype());

    std::string sep;
    if (!sepIsNone) {
        if (!sepObj->isString(context)) {
            if (env) env->raiseTypeError(context, "split arg 1 must be str or None");
            return PROTO_NONE;
        }
        sepObj->asString(context)->toUTF8String(context, sep);
        if (sep.empty()) {
            if (env) env->raiseValueError(context, PythonEnvironment::getInternedString(context, "empty separator")->asObject(context));
            return PROTO_NONE;
        }
    }

    long long maxsplit = -1;
    if (posArgs && posArgs->getSize(context) >= 2) {
        const proto::ProtoObject* msObj = posArgs->getAt(context, 1);
        if (msObj->isInteger(context)) {
            maxsplit = msObj->asLong(context);
        } else if (msObj == PROTO_TRUE) {
            maxsplit = 1;
        } else if (msObj == PROTO_FALSE) {
            maxsplit = 0;
        } else if (msObj != PROTO_NONE) {
            // CPython: split's maxsplit must be int.  Previously a
            // non-int was silently dropped (defaulted to -1), so
            // `'a b c'.split(' ', 'x')` ignored the bad arg.
            if (env) env->raiseTypeError(context,
                "'X' object cannot be interpreted as an integer");
            return nullptr;
        }
    }

    const proto::ProtoList* result = context->newList();
    if (sepIsNone) {
        // Whitespace split
        size_t start = 0;
        int count = 0;
        while (start < s.size() && (maxsplit < 0 || count < maxsplit)) {
            while (start < s.size() && is_ascii_whitespace(s[start])) start++;
            if (start >= s.size()) break;
            size_t end = start;
            while (end < s.size() && !is_ascii_whitespace(s[end])) end++;
            result = result->appendLast(context, PythonEnvironment::getInternedString(context, s.substr(start, end - start).c_str())->asObject(context));
            start = end;
            count++;
        }
        if (maxsplit >= 0 && count >= maxsplit && start < s.size()) {
            while (start < s.size() && is_ascii_whitespace(s[start])) start++;
            if (start < s.size()) {
                result = result->appendLast(context, PythonEnvironment::getInternedString(context, s.substr(start).c_str())->asObject(context));
            }
        }
    } else {
        // Separator split
        size_t start = 0;
        int count = 0;
        while (maxsplit < 0 || count < maxsplit) {
            size_t pos = s.find(sep, start);
            if (pos == std::string::npos) break;
            result = result->appendLast(context, PythonEnvironment::getInternedString(context, s.substr(start, pos - start).c_str())->asObject(context));
            start = pos + sep.size();
            count++;
        }
        result = result->appendLast(context, PythonEnvironment::getInternedString(context, s.substr(start).c_str())->asObject(context));
    }

    if (!env) return result->asObject(context);
    proto::ProtoObject* listObj = const_cast<proto::ProtoObject*>(env->getListPrototype()->newChild(context, true));
    const proto::ProtoString* dataName = PythonEnvironment::getInternalString(context, "__data__");
    listObj->setAttribute(context, dataName, result->asObject(context));
    return listObj;
}

static const proto::ProtoObject* py_str_rsplit(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    int posOff = 0;
    const proto::ProtoString* str = str_from_self_or_arg(context, self, posArgs, &posOff);
    if (!str) return PROTO_NONE;
    std::string s;
    str->toUTF8String(context, s);
    std::string sep = " ";
    bool sepProvided = false;
    if (posArgs->getSize(context) >= static_cast<unsigned long>(1 + posOff)) {
        const proto::ProtoObject* sepObj = posArgs->getAt(context, posOff);
        if (sepObj && sepObj != PROTO_NONE && sepObj->isString(context)) {
            sepObj->asString(context)->toUTF8String(context, sep);
            sepProvided = true;
        }
    }
    long long maxsplit = -1;
    if (posArgs->getSize(context) >= static_cast<unsigned long>(2 + posOff)) {
        const proto::ProtoObject* msObj = posArgs->getAt(context, 1 + posOff);
        if (msObj->isInteger(context)) {
            maxsplit = msObj->asLong(context);
        } else if (msObj == PROTO_TRUE) {
            maxsplit = 1;
        } else if (msObj == PROTO_FALSE) {
            maxsplit = 0;
        } else if (msObj != PROTO_NONE) {
            PythonEnvironment* envE = PythonEnvironment::fromContext(context);
            if (envE) envE->raiseTypeError(context,
                "'X' object cannot be interpreted as an integer");
            return nullptr;
        }
    }
    const proto::ProtoList* result = context->newList();
    if (sep.empty() && sepProvided) return PROTO_NONE;
    std::vector<std::string> parts;
    size_t end = s.size();
    while (maxsplit != 0) {
        size_t pos = std::string::npos;
        if (end >= sep.size()) {
            for (size_t i = end - sep.size(); i != static_cast<size_t>(-1); --i) {
                if (s.compare(i, sep.size(), sep) == 0) { pos = i; break; }
            }
        }
        if (pos == std::string::npos) {
            // Push the entire remaining prefix (possibly empty) and stop.
            // Without this push the final segment is lost — `rsplit`
            // previously fell through the loop with `parts` short of
            // its first element on every input.
            parts.insert(parts.begin(), s.substr(0, end));
            end = 0;
            break;
        }
        parts.insert(parts.begin(), s.substr(pos + sep.size(), end - (pos + sep.size())));
        end = pos;
        if (maxsplit > 0) maxsplit--;
    }
    // If the loop exited via maxsplit reaching zero, push the
    // remaining prefix (the part to the left of the rightmost
    // accepted split).  When the no-match branch already pushed it
    // above, `end` is zeroed to avoid duplicating.
    if (end > 0 || (maxsplit == 0 && parts.size() > 0)) {
        parts.insert(parts.begin(), s.substr(0, end));
    }
    for (const auto& p : parts)
        result = result->appendLast(context, PythonEnvironment::getInternedString(context, p.c_str())->asObject(context));
    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    if (!env) return result->asObject(context);
    proto::ProtoObject* listObj = const_cast<proto::ProtoObject*>(env->getListPrototype()->newChild(context, true));
    const proto::ProtoString* dataName = PythonEnvironment::getInternalString(context, "__data__");
    listObj->setAttribute(context, dataName, result->asObject(context));
    return listObj;
}

static const proto::ProtoObject* py_str_splitlines(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList* kwArgs) {
    const proto::ProtoString* str = str_from_self(context, self);
    if (!str) return PROTO_NONE;
    std::string s;
    str->toUTF8String(context, s);
    bool keepends = false;
    auto coerceKeepends = [&](const proto::ProtoObject* ke) {
        if (!ke) return;
        if (ke->isBoolean(context)) keepends = ke->asBoolean(context);
        else if (ke->isInteger(context)) keepends = ke->asLong(context) != 0;
        else keepends = (ke != PROTO_NONE && ke != PROTO_FALSE);
    };
    if (posArgs && posArgs->getSize(context) >= 1) {
        coerceKeepends(posArgs->getAt(context, 0));
    }
    if (kwArgs) {
        const proto::ProtoString* keS = PythonEnvironment::getInternedString(context, "keepends");
        unsigned long h = keS->getHash(context);
        if (kwArgs->has(context, h)) {
            coerceKeepends(kwArgs->getAt(context, h));
        }
    }
    const proto::ProtoList* result = context->newList();
    size_t start = 0;
    size_t i = 0;
    while (i < s.size()) {
            if (s[i] == '\n') {
            std::string line = s.substr(start, i - start);
            if (keepends) line += '\n';
            result = result->appendLast(context, PythonEnvironment::getInternedString(context, line.c_str())->asObject(context));
            start = i + 1;
            i++;
        } else if (s[i] == '\r') {
            std::string line = s.substr(start, i - start);
            if (keepends) line += (i + 1 < s.size() && s[i + 1] == '\n') ? "\r\n" : "\r";
            result = result->appendLast(context, PythonEnvironment::getInternedString(context, line.c_str())->asObject(context));
            i = (i + 1 < s.size() && s[i + 1] == '\n') ? i + 2 : i + 1;
            start = i;
        } else {
            i++;
        }
    }
    // Python splitlines() doesn't include a trailing empty string for text ending with newline
    {
        std::string tail = s.substr(start);
        if (!tail.empty()) {
            result = result->appendLast(context, PythonEnvironment::getInternedString(context, tail.c_str())->asObject(context));
        }
    }
    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    if (!env) return result->asObject(context);
    proto::ProtoObject* listObj = const_cast<proto::ProtoObject*>(env->getListPrototype()->newChild(context, true));
    const proto::ProtoString* dataName = PythonEnvironment::getInternalString(context, "__data__");
    listObj->setAttribute(context, dataName, result->asObject(context));
    return listObj;
}



static const proto::ProtoObject* py_str_strip(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    const proto::ProtoString* str = str_from_self(context, self);
    int posOff = 0;
    if (!str && posArgs && posArgs->getSize(context) >= 1) {
        str = str_from_self(context, posArgs->getAt(context, 0));
        if (str) posOff = 1;
    }
    if (!str) {
        PythonEnvironment* env_e = PythonEnvironment::fromContext(context);
        if (env_e) env_e->raiseTypeError(context,
            "descriptor 'strip' for 'str' objects doesn't apply to a non-str object");
        return nullptr;
    }
    if (posOff > 0) {
        proto::ProtoList* shifted = const_cast<proto::ProtoList*>(context->newList());
        for (unsigned long i = posOff; i < posArgs->getSize(context); ++i) {
            shifted = const_cast<proto::ProtoList*>(shifted->appendLast(context, posArgs->getAt(context, static_cast<int>(i))));
        }
        posArgs = shifted;
    }
    std::string s;
    str->toUTF8String(context, s);
    std::string chars;
    if (posArgs && posArgs->getSize(context) >= 1) {
        const proto::ProtoObject* charsObj = posArgs->getAt(context, 0);
        PythonEnvironment* env = PythonEnvironment::fromContext(context);
        if (charsObj && !(env && charsObj == env->getNonePrototype())) {
            if (charsObj->isString(context)) charsObj->asString(context)->toUTF8String(context, chars);
            else if (env) {
                env->raiseTypeError(context, "strip arg must be str or None");
                return PROTO_NONE;
            }
        }
    }
    size_t start = 0;
    while (start < s.size() && char_in_chars(static_cast<unsigned char>(s[start]), chars)) start++;
    size_t end = s.size();
    while (end > start && char_in_chars(static_cast<unsigned char>(s[end - 1]), chars)) end--;
    return PythonEnvironment::getInternedString(context, s.substr(start, end - start).c_str())->asObject(context);
}



static const proto::ProtoObject* py_str_lstrip(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    const proto::ProtoString* str = str_from_self(context, self);
    int posOff = 0;
    if (!str && posArgs && posArgs->getSize(context) >= 1) {
        str = str_from_self(context, posArgs->getAt(context, 0));
        if (str) posOff = 1;
    }
    if (!str) return PROTO_NONE;
    std::string s;
    str->toUTF8String(context, s);
    std::string chars;
    if (posArgs && posArgs->getSize(context) >= static_cast<unsigned long>(1 + posOff)
        && posArgs->getAt(context, posOff)->isString(context))
        posArgs->getAt(context, posOff)->asString(context)->toUTF8String(context, chars);
    size_t start = 0;
    while (start < s.size() && char_in_chars(static_cast<unsigned char>(s[start]), chars)) start++;
    return PythonEnvironment::getInternedString(context, s.substr(start).c_str())->asObject(context);
}

