static const proto::ProtoObject* py_str_replace(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    const proto::ProtoString* str = str_from_self(context, self);
    int posOff = 0;
    if (!str && posArgs && posArgs->getSize(context) >= 3) {
        str = str_from_self(context, posArgs->getAt(context, 0));
        if (str) posOff = 1;
    }
    if (!str || !posArgs || posArgs->getSize(context) < static_cast<unsigned long>(2 + posOff)) return PROTO_NONE;
    std::string s;
    str->toUTF8String(context, s);

    const proto::ProtoObject* oldObj = posArgs->getAt(context, 0 + posOff);
    const proto::ProtoObject* newObj = posArgs->getAt(context, 1 + posOff);
    PythonEnvironment* env = PythonEnvironment::fromContext(context);
    if (!oldObj->isString(context) || !newObj->isString(context)) {
        if (env) env->raiseTypeError(context, "replace args 1 and 2 must be str");
        return PROTO_NONE;
    }

    std::string oldStr, newStr;
    oldObj->asString(context)->toUTF8String(context, oldStr);
    newObj->asString(context)->toUTF8String(context, newStr);

    int count = -1;
    if (posArgs->getSize(context) >= static_cast<unsigned long>(3 + posOff)) {
        const proto::ProtoObject* cntObj = posArgs->getAt(context, 2 + posOff);
        if (cntObj->isInteger(context)) {
            count = static_cast<int>(cntObj->asLong(context));
        } else if (cntObj == PROTO_TRUE) {
            count = 1;
        } else if (cntObj == PROTO_FALSE) {
            count = 0;
        } else if (cntObj != PROTO_NONE) {
            // CPython: str.replace count must be int.  Previously a
            // non-int was silently dropped to the default -1, so
            // `'aaa'.replace('a', 'b', 'x')` replaced everything as
            // if the count had been omitted.
            if (env) env->raiseTypeError(context,
                "'X' object cannot be interpreted as an integer");
            return nullptr;
        }
    }

    std::string result;
    if (oldStr.empty()) {
        // Python behavior for empty old string: insert newStr between every character
        int replaced = 0;
        for (size_t i = 0; i < s.size(); ++i) {
            if (count >= 0 && replaced >= count) {
                result += s.substr(i);
                break;
            }
            result += newStr;
            result += s[i];
            replaced++;
        }
        if (count < 0 || replaced < count) result += newStr;
        return PythonEnvironment::getInternedString(context, result.c_str())->asObject(context);
    }

    size_t pos = 0;
    int replaced = 0;
    while (pos < s.size() && (count < 0 || replaced < count)) {
        size_t found = s.find(oldStr, pos);
        if (found == std::string::npos) {
            result += s.substr(pos);
            pos = s.size();
            break;
        }
        result += s.substr(pos, found - pos);
        result += newStr;
        pos = found + oldStr.size();
        replaced++;
    }
    if (pos < s.size())
        result += s.substr(pos);
    return PythonEnvironment::getInternedString(context, result.c_str())->asObject(context);
}

static const proto::ProtoObject* py_str_capitalize(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    const proto::ProtoString* str = str_from_self(context, self);
    if (!str && posArgs && posArgs->getSize(context) >= 1) {
        str = str_from_self(context, posArgs->getAt(context, 0));
    }
    if (!str) return PROTO_NONE;
    std::string s;
    str->toUTF8String(context, s);
    if (s.empty()) return PythonEnvironment::getInternedString(context, "")->asObject(context);
    std::string r;
    r += static_cast<char>(std::toupper(static_cast<unsigned char>(s[0])));
    for (size_t i = 1; i < s.size(); ++i)
        r += static_cast<char>(std::tolower(static_cast<unsigned char>(s[i])));
    return PythonEnvironment::getInternedString(context, r.c_str())->asObject(context);
}

static const proto::ProtoObject* py_str_title(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    const proto::ProtoString* str = str_from_self(context, self);
    if (!str && posArgs && posArgs->getSize(context) >= 1) {
        str = str_from_self(context, posArgs->getAt(context, 0));
    }
    if (!str) return PROTO_NONE;
    std::string s;
    str->toUTF8String(context, s);
    std::string r;
    bool after_boundary = true;
    for (unsigned char c : s) {
        if (std::isalnum(c) || c == '_') {
            r += after_boundary ? static_cast<char>(std::toupper(c)) : static_cast<char>(std::tolower(c));
            after_boundary = false;
        } else {
            r += static_cast<char>(c);
            after_boundary = true;
        }
    }
    return PythonEnvironment::getInternedString(context, r.c_str())->asObject(context);
}

static const proto::ProtoObject* py_str_swapcase(
    proto::ProtoContext* context,
    const proto::ProtoObject* self,
    const proto::ParentLink*, const proto::ProtoList* posArgs, const proto::ProtoSparseList*) {
    const proto::ProtoString* str = str_from_self(context, self);
    if (!str && posArgs && posArgs->getSize(context) >= 1) {
        str = str_from_self(context, posArgs->getAt(context, 0));
    }
    if (!str) return PROTO_NONE;
    std::string s;
    str->toUTF8String(context, s);
    std::string r;
    for (unsigned char c : s) {
        if (std::isupper(c)) r += static_cast<char>(std::tolower(c));
        else if (std::islower(c)) r += static_cast<char>(std::toupper(c));
        else r += static_cast<char>(c);
    }
    return PythonEnvironment::getInternedString(context, r.c_str())->asObject(context);
}

