static int levenshtein_distance(const std::string& s1, const std::string& s2) {
    const size_t len1 = s1.size(), len2 = s2.size();
    if (len1 == 0) return (int)len2;
    if (len2 == 0) return (int)len1;
    std::vector<int> col(len2 + 1), prevCol(len2 + 1);
    for (int i = 0; i <= (int)len2; i++) prevCol[i] = i;
    for (int i = 0; i < (int)len1; i++) {
        col[0] = i + 1;
        for (int j = 0; j < (int)len2; j++) {
            col[j + 1] = std::min({ prevCol[1 + j] + 1, col[j] + 1, prevCol[j] + (s1[i] == s2[j] ? 0 : 1) });
        }
        std::swap(col, prevCol);
    }
    return prevCol[len2];
}

static std::string suggestSimilarName(proto::ProtoContext* ctx, const std::string& name, const proto::ProtoObject* scope) {
    if (!scope) return "";
    const proto::ProtoSparseList* attrs = scope->getAttributes(ctx);
    if (!attrs) return "";
    
    std::string bestMatch;
    int bestDist = 3; // Max distance to suggest
    
    proto::ProtoSparseListIterator* it = const_cast<proto::ProtoSparseListIterator*>(attrs->getIterator(ctx));
    while (it && it->hasNext(ctx)) {
        unsigned long key = it->nextKey(ctx);
        const proto::ProtoString* s = reinterpret_cast<const proto::ProtoString*>(key);
        if (s) {
            std::string candidate;
            s->toUTF8String(ctx, candidate);
            if (candidate.size() >= 2) {
                int d = levenshtein_distance(name, candidate);
                if (d < bestDist) {
                    bestDist = d;
                    bestMatch = candidate;
                }
            }
        }
        it = const_cast<proto::ProtoSparseListIterator*>(it->advance(ctx));
    }
    return bestMatch;
}

void PythonEnvironment::raiseImportError(const std::string& msg) {
    if (!importErrorType) return;
    proto::ProtoContext* ctx = rootContext_;
    const proto::ProtoList* args = ctx->newList()->appendLast(ctx, PythonEnvironment::getInternedString(ctx, msg.c_str())->asObject(ctx));
    // Raise ModuleNotFoundError (subclass of ImportError) for "No module named" messages.
    bool isNotFound = (msg.find("No module named") != std::string::npos);
    const proto::ProtoObject* errType = (isNotFound && moduleNotFoundErrorType && moduleNotFoundErrorType != PROTO_NONE)
        ? moduleNotFoundErrorType : importErrorType;
    const proto::ProtoObject* exc = invokePythonCallable(ctx, errType, args, nullptr);
    if (exc && exc != PROTO_NONE) {
        setPendingException(exc);
    }
}

void PythonEnvironment::raiseNameError(proto::ProtoContext* ctx, const std::string& name) {
    if (!nameErrorType) return;
    std::string msg = "name '" + name + "' is not defined";

    const proto::ProtoList* args = ctx->newList()->appendLast(ctx, PythonEnvironment::getInternedString(ctx, msg.c_str())->asObject(ctx));
    const proto::ProtoObject* exc = invokePythonCallable(ctx, nameErrorType, args, nullptr);
    if (exc) {
        exc = exc->setAttribute(ctx, PythonEnvironment::getInternedString(ctx, "name"), PythonEnvironment::getInternedString(ctx, name.c_str())->asObject(ctx));
        setPendingException(exc);
    }
}

void PythonEnvironment::raiseUnboundLocalError(proto::ProtoContext* ctx, const std::string& msg) {
    if (!unboundLocalErrorType) {
        // Fallback during bootstrap before exceptions are registered.
        raiseNameError(ctx, msg);
        return;
    }
    const proto::ProtoList* args = ctx->newList()->appendLast(ctx, PythonEnvironment::getInternedString(ctx, msg.c_str())->asObject(ctx));
    const proto::ProtoObject* exc = invokePythonCallable(ctx, unboundLocalErrorType, args, nullptr);
    if (exc) setPendingException(exc);
}

void PythonEnvironment::raiseAttributeError(proto::ProtoContext* ctx, const proto::ProtoObject* obj, const std::string& attr) {
    if (!attributeErrorType) {
        // Fallback during bootstrap
        if (get_env_diag()) {
        }
        // Use a generic object as exception marker if types aren't ready
        this->setPendingException(PythonEnvironment::getInternedString(ctx, ("AttributeError: " + attr).c_str())->asObject(ctx));
        return;
    }
    std::string typeName = "object";
    const proto::ProtoString* clsS = PythonEnvironment::getInternedString(ctx, "__class__");
    const proto::ProtoObject* cls = this->getType(ctx, obj);
    if (cls) {
        const proto::ProtoObject* nameAttr = cls->getAttribute(ctx, PythonEnvironment::getInternalString(ctx, "__name__"));
        if (nameAttr && nameAttr->isString(ctx)) nameAttr->asString(ctx)->toUTF8String(ctx, typeName);
    } else {
        if (obj->isInteger(ctx)) typeName = "int";
        else if (obj->isString(ctx)) {
            typeName = "str";
            if (attr == "_data") {
                // str has no '_data' attribute — intentional; nothing to log here
            }
        }
        else if (obj->asList(ctx)) typeName = "list";
    }
    std::string msg = "'" + typeName + "' object has no attribute '" + attr + "'";
    
    const proto::ProtoList* args = ctx->newList()->appendLast(ctx, PythonEnvironment::getInternedString(ctx, msg.c_str())->asObject(ctx));
    const proto::ProtoObject* exc = invokePythonCallable(ctx, attributeErrorType, args, nullptr);
    if (exc) {
        exc = exc->setAttribute(ctx, PythonEnvironment::getInternedString(ctx, "name"), PythonEnvironment::getInternedString(ctx, attr.c_str())->asObject(ctx));
        exc = exc->setAttribute(ctx, PythonEnvironment::getInternedString(ctx, "obj"), obj);
        setPendingException(exc);
    }
}

void PythonEnvironment::raiseAttributeErrorWithMessage(proto::ProtoContext* ctx,
                                                       const proto::ProtoObject* obj,
                                                       const std::string& message,
                                                       const std::string& attr) {
    if (!attributeErrorType) {
        // Fallback during bootstrap: surface the message as a generic marker.
        this->setPendingException(PythonEnvironment::getInternedString(ctx, ("AttributeError: " + message).c_str())->asObject(ctx));
        return;
    }
    const proto::ProtoList* args = ctx->newList()->appendLast(ctx, PythonEnvironment::getInternedString(ctx, message.c_str())->asObject(ctx));
    const proto::ProtoObject* exc = invokePythonCallable(ctx, attributeErrorType, args, nullptr);
    if (exc) {
        exc = exc->setAttribute(ctx, PythonEnvironment::getInternedString(ctx, "name"),
                                PythonEnvironment::getInternedString(ctx, attr.c_str())->asObject(ctx));
        if (obj) {
            exc = exc->setAttribute(ctx, PythonEnvironment::getInternedString(ctx, "obj"), obj);
        }
        setPendingException(exc);
    }
}

