    const proto::ProtoString* py_add = getAddS();

    // 1. Create raw objects
    objectPrototype = rootContext_->newObject(true);
    typePrototype = objectPrototype->newChild(rootContext_, true);
    dictPrototype = objectPrototype->newChild(rootContext_, true);
    listPrototype = objectPrototype->newChild(rootContext_, true);
    tuplePrototype = objectPrototype->newChild(rootContext_, true);
    
    const proto::ProtoString* py_format_dunder = PythonEnvironment::getInternedString(rootContext_, "__format__");
    const proto::ProtoString* py_hash_dunder = PythonEnvironment::getInternedString(rootContext_, "__hash__");

    // 2. Set names and basic identity
    objectPrototype = objectPrototype->setAttribute(rootContext_, py_name, PythonEnvironment::getInternedString(rootContext_, "object")->asObject(rootContext_));
    objectPrototype = objectPrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "__qualname__"), PythonEnvironment::getInternedString(rootContext_, "object")->asObject(rootContext_));
    typePrototype = typePrototype->setAttribute(rootContext_, py_name, PythonEnvironment::getInternedString(rootContext_, "type")->asObject(rootContext_));
    typePrototype = typePrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "__qualname__"), PythonEnvironment::getInternedString(rootContext_, "type")->asObject(rootContext_));
    objectPrototype = objectPrototype->setAttribute(rootContext_, py_module, builtinsVal);
    typePrototype = typePrototype->setAttribute(rootContext_, py_module, builtinsVal);

    // 3. Set all dunders on object
    // Phase-4 own-marker so isActuallyAClass(objectPrototype) collapses
    // to the same single hasOwnAttribute test as user-defined classes.
    objectPrototype = objectPrototype->setAttribute(rootContext_, getInternedString(rootContext_, "__is_python_class__"), PROTO_TRUE);
    objectPrototype = objectPrototype->setAttribute(rootContext_, py_init, rootContext_->fromMethod(nullptr, py_object_init));
    objectPrototype = objectPrototype->setAttribute(rootContext_, newString, rootContext_->fromMethod(nullptr, protoPython::builtins::py_object_new));
    objectPrototype = objectPrototype->setAttribute(rootContext_, py_repr, rootContext_->fromMethod(nullptr, py_object_repr));
    // Default __doc__ to None on objectPrototype so every object that
    // does not provide its own docstring still answers `obj.__doc__`
    // with None (CPython semantics — undocumented objects expose
    // `__doc__ = None` rather than raising AttributeError). Native
    // methods exposed via fromMethod do not carry docstrings, and the
    // stdlib pattern `wrapper.__doc__ = wrapped.__doc__` (used in
    // `signal._wraps`, `functools.wraps` and elsewhere) breaks loudly
    // without this fallback.
    objectPrototype = objectPrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "__doc__"), PROTO_NONE);
    objectPrototype = objectPrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "__dict__"), rootContext_->fromMethod(nullptr, py_object_get_dict));
    objectPrototype = objectPrototype->setAttribute(rootContext_, py_str, rootContext_->fromMethod(nullptr, py_object_str));
    objectPrototype = objectPrototype->setAttribute(rootContext_, getInternedString(rootContext_, "__format__"), rootContext_->fromMethod(nullptr, py_object_format));
    objectPrototype = objectPrototype->setAttribute(rootContext_, getInternedString(rootContext_, "__hash__"), rootContext_->fromMethod(nullptr, py_object_hash));
    objectPrototype = objectPrototype->setAttribute(rootContext_, getInternedString(rootContext_, "__reduce_ex__"), rootContext_->fromMethod(nullptr, py_object_reduce_ex));
    objectPrototype = objectPrototype->setAttribute(rootContext_, getInternedString(rootContext_, "__reduce__"), rootContext_->fromMethod(nullptr, py_object_reduce));
    // PEP 690 / Python 3.11+ — object.__getstate__ exposes the
    // instance __dict__ (and, when __slots__ is defined,
    // (dict, slotstate) tuple).  copyreg._reduce_ex's identity
    // check `type(self).__getstate__ is object.__getstate__` (used
    // to detect a missing override before raising "cannot pickle"
    // for slot-only classes) requires this attribute to exist on
    // object so MRO resolution finds it on plain instances.
    objectPrototype = objectPrototype->setAttribute(rootContext_,
        getInternedString(rootContext_, "__getstate__"),
        rootContext_->fromMethod(nullptr,
        [](proto::ProtoContext* ctx, const proto::ProtoObject* self,
           const proto::ParentLink*, const proto::ProtoList* args,
           const proto::ProtoSparseList*) -> const proto::ProtoObject* {
            PythonEnvironment* envInner = PythonEnvironment::fromContext(ctx);
            if (!envInner) return PROTO_NONE;
            // Bound (self=instance) vs unbound (self=null/objectProto,
            // args=[instance]) dispatch — same shape py_object_reduce
            // resolves.
            const proto::ProtoObject* obj = self;
            if ((!obj || obj == envInner->getObjectPrototype())
                && args && args->getSize(ctx) >= 1) {
                obj = args->getAt(ctx, 0);
            }
            if (!obj) return PROTO_NONE;
            // Mirror the instance dict snapshot py_object_get_dict
            // produces.  Calling that directly returns the live proxy
            // dict, which is what CPython's default __getstate__
            // surfaces (callers iterate / pickle it).  When __dict__
            // raises (bare object() has none), return an empty dict
            // so pickle/copyreg paths can use a consistent state.
            PythonEnvironment* env = PythonEnvironment::fromContext(ctx);
            if (env) env->clearPendingException();
            const proto::ProtoObject* d = py_object_get_dict(ctx, obj, nullptr, nullptr, nullptr);
            if ((!d || env->hasPendingException()) && env) {
                env->clearPendingException();
                const proto::ProtoObject* dp = env->getDictPrototype();
                if (dp) {
                    proto::ProtoObject* empty = const_cast<proto::ProtoObject*>(dp->newChild(ctx, true));
                    empty->setAttribute(ctx, env->getDataString(), ctx->newSparseList()->asObject(ctx));
                    empty->setAttribute(ctx, env->getKeysString(), ctx->newList()->asObject(ctx));
                    return (const proto::ProtoObject*)empty;
                }
                return PROTO_NONE;
            }
            return d;
        }));
    // PH: object.__init_subclass__ is a no-op; classmethod-bound to keep
    // `super().__init_subclass__(**kwargs)` chains terminating cleanly.
    {
        const proto::ProtoObject* iscMethod = rootContext_->fromMethod(nullptr,
            [](proto::ProtoContext* ctx, const proto::ProtoObject*,
               const proto::ParentLink*,
               const proto::ProtoList*,
               const proto::ProtoSparseList*) -> const proto::ProtoObject* {
                PythonEnvironment* env = PythonEnvironment::fromContext(ctx);
                return env ? env->getNonePrototype() : PROTO_NONE;
            });
        objectPrototype = objectPrototype->setAttribute(rootContext_,
            getInternedString(rootContext_, "__init_subclass__"), iscMethod);
    }
    // PH: object.__class_getitem__ is a no-op for object; subclasses may override.
    objectPrototype = objectPrototype->setAttribute(rootContext_,
        getInternedString(rootContext_, "__set_name__"),
        rootContext_->fromMethod(nullptr,
            [](proto::ProtoContext* ctx, const proto::ProtoObject*,
               const proto::ParentLink*,
               const proto::ProtoList*,
               const proto::ProtoSparseList*) -> const proto::ProtoObject* {
                PythonEnvironment* env = PythonEnvironment::fromContext(ctx);
                return env ? env->getNonePrototype() : PROTO_NONE;
            }));

    // 4. Set all dunders on type
    typePrototype = typePrototype->setAttribute(rootContext_, py_repr, rootContext_->fromMethod(nullptr, py_type_repr));
    typePrototype = typePrototype->setAttribute(rootContext_, getInternedString(rootContext_, "__call__"), rootContext_->fromMethod(nullptr, py_type_call));
    typePrototype = typePrototype->setAttribute(rootContext_, getInternedString(rootContext_, "__is_python_class__"), PROTO_TRUE);
    typePrototype = typePrototype->setAttribute(rootContext_, newString, rootContext_->fromMethod(nullptr, protoPython::builtins::py_type));
    typePrototype = typePrototype->setAttribute(rootContext_, py_init, rootContext_->fromMethod(nullptr, protoPython::builtins::py_type_init));
    typePrototype = typePrototype->setAttribute(rootContext_, prepareString, rootContext_->fromMethod(nullptr, protoPython::builtins::py_type_prepare));
    typePrototype = typePrototype->setAttribute(rootContext_, getInternedString(rootContext_, "__class_getitem__"), rootContext_->fromMethod(nullptr, py_type_class_getitem));
    // type.__subclasses__(): returns a fresh list of the type's direct
    // subclasses (read from the __subclasses_list__ slot maintained by
    // py_type at class creation).  CPython parity: the returned list is
    // a copy so callers can mutate it without affecting the type.
    typePrototype = typePrototype->setAttribute(rootContext_,
        getInternedString(rootContext_, "__subclasses__"),
        rootContext_->fromMethod(nullptr,
        [](proto::ProtoContext* ctx, const proto::ProtoObject* self,
           const proto::ParentLink*, const proto::ProtoList* args,
           const proto::ProtoSparseList*) -> const proto::ProtoObject* {
            const proto::ProtoObject* cls = self;
            // Unbound dispatch: type.__subclasses__(C) — args[0] is the cls.
            PythonEnvironment* env = PythonEnvironment::fromContext(ctx);
            if (env && (!cls || cls == env->getTypePrototype())
                && args && args->getSize(ctx) >= 1) {
                cls = args->getAt(ctx, 0);
            }
            if (!cls) return ctx->newList()->asObject(ctx);
            const proto::ProtoString* subListS =
                PythonEnvironment::getInternedString(ctx, "__subclasses_list__");
            const proto::ProtoObject* listObj = cls->hasOwnAttribute(ctx, subListS) == PROTO_TRUE
                ? cls->getAttribute(ctx, subListS) : nullptr;
            const proto::ProtoList* src = (listObj && listObj->asList(ctx))
                ? listObj->asList(ctx) : ctx->newList();
            // Wrap as a Python list with __data__ + class so the
            // result behaves as a real list at the Python level.
            const proto::ProtoList* copy = ctx->newList();
            for (unsigned long i = 0; i < src->getSize(ctx); ++i) {
                copy = copy->appendLast(ctx, src->getAt(ctx, static_cast<int>(i)));
            }
            if (env && env->getListPrototype()) {
                proto::ProtoObject* w = const_cast<proto::ProtoObject*>(ctx->newObject(true));
                w = const_cast<proto::ProtoObject*>(w->setAttribute(ctx, env->getDataString(), copy->asObject(ctx)));
                w = const_cast<proto::ProtoObject*>(w->addParent(ctx, env->getListPrototype()));
                w = const_cast<proto::ProtoObject*>(w->setAttribute(ctx, env->getClassString(), env->getListPrototype()));
                return w;
            }
            return copy->asObject(ctx);
        }));
    typePrototype = typePrototype->setAttribute(rootContext_, getInternedString(rootContext_, "__or__"), rootContext_->fromMethod(nullptr, py_type_or));
    typePrototype = typePrototype->setAttribute(rootContext_, getInternedString(rootContext_, "__instancecheck__"), rootContext_->fromMethod(nullptr, py_type_instancecheck));
    typePrototype = typePrototype->setAttribute(rootContext_, getInternedString(rootContext_, "__subclasscheck__"), rootContext_->fromMethod(nullptr, py_type_subclasscheck));

    // 5. Set MROs and Bases
    objectPrototype = objectPrototype->setAttribute(rootContext_, mroString, rootContext_->newTupleFromList(rootContext_->newList()->appendLast(rootContext_, objectPrototype))->asObject(rootContext_));
    this->objectPrototype = const_cast<proto::ProtoObject*>(objectPrototype);
    this->space_->objectPrototype = const_cast<proto::ProtoObject*>(objectPrototype);

    objectPrototype = objectPrototype->setAttribute(rootContext_, basesString, rootContext_->newTupleFromList(rootContext_->newList())->asObject(rootContext_));
    this->objectPrototype = const_cast<proto::ProtoObject*>(objectPrototype);
    this->space_->objectPrototype = const_cast<proto::ProtoObject*>(objectPrototype);

    const proto::ProtoList* typeMroList = rootContext_->newList()->appendLast(rootContext_, typePrototype)->appendLast(rootContext_, objectPrototype);
    typePrototype = typePrototype->setAttribute(rootContext_, mroString, rootContext_->newTupleFromList(typeMroList)->asObject(rootContext_));
    this->typePrototype = const_cast<proto::ProtoObject*>(typePrototype);

    typePrototype = typePrototype->setAttribute(rootContext_, basesString, rootContext_->newTupleFromList(rootContext_->newList()->appendLast(rootContext_, objectPrototype))->asObject(rootContext_));
    this->typePrototype = const_cast<proto::ProtoObject*>(typePrototype);

    // 6. NOW set __class__ pointers to the FINAL versions
    objectPrototype = objectPrototype->setAttribute(rootContext_, py_class, typePrototype);
    this->objectPrototype = const_cast<proto::ProtoObject*>(objectPrototype);
    this->space_->objectPrototype = const_cast<proto::ProtoObject*>(objectPrototype);

    typePrototype = typePrototype->setAttribute(rootContext_, py_class, typePrototype);
    this->typePrototype = const_cast<proto::ProtoObject*>(typePrototype);

    if (std::getenv("PROTO_ENV_DEBUG")) fprintf(stderr, "DEBUG_ROOT: typePrototype=%p objectPrototype=%p\n", (void*)typePrototype, (void*)objectPrototype);

    // V75: Initialize specific prototypes for better type identity
    // IMPORTANT: methodPrototype MUST be initialized extremely early so that ALL subsequent methods get it natively!
    methodPrototype = objectPrototype->newChild(rootContext_, true);
    methodPrototype = methodPrototype->setAttribute(rootContext_, py_class, typePrototype);
    methodPrototype = methodPrototype->setAttribute(rootContext_, py_name, PythonEnvironment::getInternedString(rootContext_, "method")->asObject(rootContext_));
    methodPrototype = methodPrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "__qualname__"), PythonEnvironment::getInternedString(rootContext_, "method")->asObject(rootContext_));
    methodPrototype = methodPrototype->setAttribute(rootContext_, py_module, builtinsVal);
    // Bind descriptor __get__ so getattr(str, "replace") resolves to a bound method dynamically!
    methodPrototype = methodPrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "__get__"), rootContext_->fromMethod(nullptr, 
        [](proto::ProtoContext* ctx, const proto::ProtoObject* self, const proto::ParentLink*, const proto::ProtoList* args, const proto::ProtoSparseList*) -> const proto::ProtoObject* {
            if (get_env_diag()) fprintf(stderr, "DEBUG_GET: methodPrototype.__get__ called on self=%p. isMethod=%d\n", (void*)self, self->isMethod(ctx));
            if (!args || args->getSize(ctx) < 1) return self;
            const proto::ProtoObject* instance = args->getAt(ctx, 0);
            if (get_env_diag()) fprintf(stderr, "DEBUG_GET: instance=%p\n", (void*)instance);
            if (instance == PROTO_NONE || !instance) return self; // Unbound method accessed natively via class
            // Create natively bound method:
            if (!self->isMethod(ctx)) return self;
            const proto::ProtoObject* bound = ctx->fromMethod(const_cast<proto::ProtoObject*>(instance), self->asMethod(ctx));
            if (get_env_diag()) fprintf(stderr, "DEBUG_GET: created bound method %p\n", (void*)bound);
            
            // Native built-in bound methods need standard introspection primitives identically to user functions.
            PythonEnvironment* env = PythonEnvironment::fromContext(ctx);
            const proto::ProtoString* py_name_s = env ? env->getNameString() : PythonEnvironment::getInternedString(ctx, "__name__");
            const proto::ProtoObject* dunderName = self->getAttribute(ctx, py_name_s);
            if (dunderName && dunderName != PROTO_NONE) {
                bound = bound->setAttribute(ctx, py_name_s, dunderName);
                bound = bound->setAttribute(ctx, PythonEnvironment::getInternedString(ctx, "__qualname__"), dunderName);
            }
            return bound;
        }
    ));
    
    // Bind __call__ so method objects invoke directly instead of falling back to type.__call__ (which creates classes)
    methodPrototype = methodPrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "__call__"), rootContext_->fromMethod(nullptr, 
        [](proto::ProtoContext* ctx, const proto::ProtoObject* self, const proto::ParentLink* parentLink, const proto::ProtoList* args, const proto::ProtoSparseList* kwargs) -> const proto::ProtoObject* {
            PythonEnvironment* env = PythonEnvironment::fromContext(ctx);
            if (!env) return PROTO_NONE;
            
            const proto::ProtoObject* methodObj = nullptr;
            const proto::ProtoList* actualArgs = args;
            
            bool selfHasFunc = false;
            if (self && self != PROTO_NONE) {
                const proto::ProtoObject* f = self->getAttribute(ctx, env->getFuncDunderString());
                if (f && f != PROTO_NONE) selfHasFunc = true;
            }
            
            if (selfHasFunc) {
                methodObj = self;
            } else if (args && args->getSize(ctx) > 0) {
                methodObj = args->getAt(ctx, 0);
                actualArgs = ctx->newList();
                for (size_t i = 1; i < args->getSize(ctx); ++i) {
                    actualArgs = actualArgs->appendLast(ctx, args->getAt(ctx, i));
                }
            }
            
            if (!methodObj || methodObj == PROTO_NONE) return PROTO_NONE;
            
            const proto::ProtoObject* im_self = methodObj->getAttribute(ctx, env->getSelfDunderString());
            const proto::ProtoObject* im_func = methodObj->getAttribute(ctx, env->getFuncDunderString());

            if (get_env_diag()) {
                fprintf(stderr, "DEBUG METHOD CALL: methodObj=%p im_self=%p im_func=%p actualArgsSize=%lu\n",
                        (void*)methodObj, (void*)im_self, (void*)im_func, actualArgs ? actualArgs->getSize(ctx) : 0);
                fflush(stderr);
            }
            
            if (im_self && im_func && im_self != PROTO_NONE && im_func != PROTO_NONE) {
                const proto::ProtoList* subArgs = ctx->newList()->appendLast(ctx, im_self);
                if (actualArgs) {
                    for (size_t i = 0; i < actualArgs->getSize(ctx); ++i) {
                        subArgs = subArgs->appendLast(ctx, actualArgs->getAt(ctx, (int)i));
                    }
                }
                if (get_env_diag()) {
                    fprintf(stderr, "DEBUG METHOD CALL: forwarding to im_func=%p subArgsSize=%lu\n", (void*)im_func, subArgs->getSize(ctx));
                    fflush(stderr);
                }
                return invokePythonCallable(ctx, im_func, subArgs, kwargs);
            }
            
            return invokePythonCallable(ctx, methodObj, actualArgs, kwargs);
        }
    ));
    methodPrototype = methodPrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "__doc__"), PROTO_NONE);
    // Bound-method equality: two bound methods are equal iff they share
    // the same `__self__` (by identity) and the same underlying
    // function/native pointer.  Without this, every fresh `obj.method`
    // lookup yielded a distinct wrapper and `obj.method == obj.method`
    // was always False.  Native bound methods don't always carry
    // __self__/__func__ as Python attributes, so the helper falls back
    // to the C-level asMethodSelf / asMethod pointers.
    methodPrototype = methodPrototype->setAttribute(rootContext_,
        PythonEnvironment::getInternedString(rootContext_, "__eq__"),
        rootContext_->fromMethod(nullptr,
        [](proto::ProtoContext* ctx, const proto::ProtoObject* self,
           const proto::ParentLink*, const proto::ProtoList* args,
           const proto::ProtoSparseList*) -> const proto::ProtoObject* {
            if (!args || args->getSize(ctx) < 1) return PROTO_FALSE;
            const proto::ProtoObject* a = self;
            const proto::ProtoObject* b = args->getAt(ctx, 0);
            if (!a || !b) return PROTO_FALSE;
            if (a == b) return PROTO_TRUE;
            PythonEnvironment* env = PythonEnvironment::fromContext(ctx);
            if (!env) return PROTO_FALSE;
            const proto::ProtoString* selfS = env->getSelfDunderString();
            const proto::ProtoString* funcS = env->getFuncDunderString();
            // Use getAttribute (not hasOwnAttribute) so wrapped Python
            // bound methods (where __self__/__func__ are own attrs of
            // the bound object) and native bound methods (where the
            // C-level pointers are the source of truth) both resolve.
            const proto::ProtoObject* aSelf = a->isMethod(ctx) ? a->asMethodSelf(ctx) : nullptr;
            const proto::ProtoObject* bSelf = b->isMethod(ctx) ? b->asMethodSelf(ctx) : nullptr;
            if (!aSelf) aSelf = a->getAttribute(ctx, selfS);
            if (!bSelf) bSelf = b->getAttribute(ctx, selfS);
            if (!aSelf || aSelf == PROTO_NONE || !bSelf || bSelf == PROTO_NONE) return env->getNotImplementedPrototype();
            if (aSelf != bSelf) return PROTO_FALSE;
            if (a->isMethod(ctx) && b->isMethod(ctx)) {
                return a->asMethod(ctx) == b->asMethod(ctx) ? PROTO_TRUE : PROTO_FALSE;
            }
            const proto::ProtoObject* aFunc = a->getAttribute(ctx, funcS);
            const proto::ProtoObject* bFunc = b->getAttribute(ctx, funcS);
            if (!aFunc || aFunc == PROTO_NONE || !bFunc || bFunc == PROTO_NONE) return env->getNotImplementedPrototype();
            return aFunc == bFunc ? PROTO_TRUE : PROTO_FALSE;
        }));
    methodPrototype = methodPrototype->setAttribute(rootContext_,
        PythonEnvironment::getInternedString(rootContext_, "__ne__"),
        rootContext_->fromMethod(nullptr,
        [](proto::ProtoContext* ctx, const proto::ProtoObject* self,
           const proto::ParentLink*, const proto::ProtoList* args,
           const proto::ProtoSparseList*) -> const proto::ProtoObject* {
            if (!args || args->getSize(ctx) < 1) return PROTO_TRUE;
            const proto::ProtoObject* a = self;
            const proto::ProtoObject* b = args->getAt(ctx, 0);
            if (!a || !b) return PROTO_TRUE;
            if (a == b) return PROTO_FALSE;
            PythonEnvironment* env = PythonEnvironment::fromContext(ctx);
            if (!env) return PROTO_TRUE;
            const proto::ProtoString* selfS = env->getSelfDunderString();
            const proto::ProtoString* funcS = env->getFuncDunderString();
            const proto::ProtoObject* aSelf = a->isMethod(ctx) ? a->asMethodSelf(ctx) : nullptr;
            const proto::ProtoObject* bSelf = b->isMethod(ctx) ? b->asMethodSelf(ctx) : nullptr;
            if (!aSelf) aSelf = a->getAttribute(ctx, selfS);
            if (!bSelf) bSelf = b->getAttribute(ctx, selfS);
            if (!aSelf || aSelf == PROTO_NONE || !bSelf || bSelf == PROTO_NONE) return env->getNotImplementedPrototype();
            if (aSelf != bSelf) return PROTO_TRUE;
            if (a->isMethod(ctx) && b->isMethod(ctx)) {
                return a->asMethod(ctx) == b->asMethod(ctx) ? PROTO_FALSE : PROTO_TRUE;
            }
            const proto::ProtoObject* aFunc = a->getAttribute(ctx, funcS);
            const proto::ProtoObject* bFunc = b->getAttribute(ctx, funcS);
            if (!aFunc || aFunc == PROTO_NONE || !bFunc || bFunc == PROTO_NONE) return env->getNotImplementedPrototype();
            return aFunc == bFunc ? PROTO_FALSE : PROTO_TRUE;
        }));
    // Bound-method __hash__: combine __self__ identity and __func__
    // identity so `hash(a.m) == hash(a.m)` (CPython invariant).  Without
    // this, hash falls through to ProtoObject's address-based hash and
    // each fresh `a.m` lookup hashes to a different value.
    methodPrototype = methodPrototype->setAttribute(rootContext_,
        PythonEnvironment::getInternedString(rootContext_, "__hash__"),
        rootContext_->fromMethod(nullptr,
        [](proto::ProtoContext* ctx, const proto::ProtoObject* self,
           const proto::ParentLink*, const proto::ProtoList*,
           const proto::ProtoSparseList*) -> const proto::ProtoObject* {
            PythonEnvironment* env = PythonEnvironment::fromContext(ctx);
            if (!env || !self) return PROTO_NONE;
            const proto::ProtoObject* sf = self->isMethod(ctx) ? self->asMethodSelf(ctx) : nullptr;
            if (!sf) sf = self->getAttribute(ctx, env->getSelfDunderString());
            const proto::ProtoObject* fn = nullptr;
            if (self->isMethod(ctx)) {
                // Hash native method by its function pointer identity:
                // shift to 56-bit small-int range.
                uintptr_t fp = reinterpret_cast<uintptr_t>(self->asMethod(ctx));
                long long combined = static_cast<long long>(fp) ^
                    static_cast<long long>(reinterpret_cast<uintptr_t>(sf));
                return proto::makeSmallInt(combined & 0x00FFFFFFFFFFFFFFLL);
            }
            fn = self->getAttribute(ctx, env->getFuncDunderString());
            uintptr_t sp = reinterpret_cast<uintptr_t>(sf);
            uintptr_t fp = reinterpret_cast<uintptr_t>(fn);
            long long combined = static_cast<long long>(sp ^ fp);
            return proto::makeSmallInt(combined & 0x00FFFFFFFFFFFFFFLL);
        }));
    // Register this as the prototype for all native POINTER_TAG_METHOD objects so they
    // inherit __doc__, __get__, __call__ and other standard function attributes.
    rootContext_->space->methodPrototype = const_cast<proto::ProtoObject*>(methodPrototype);

    // Initialize mappingproxy
    mappingProxyPrototype = objectPrototype->newChild(rootContext_, true);
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, py_class, typePrototype);
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, py_name, PythonEnvironment::getInternedString(rootContext_, "mappingproxy")->asObject(rootContext_));
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "__qualname__"), PythonEnvironment::getInternedString(rootContext_, "mappingproxy")->asObject(rootContext_));
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, newString, rootContext_->fromMethod(nullptr, py_mappingproxy_new));
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, py_repr, rootContext_->fromMethod(nullptr, py_mappingproxy_repr));
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "__eq__"), rootContext_->fromMethod(nullptr, py_mappingproxy_eq));
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "__ne__"), rootContext_->fromMethod(nullptr, py_mappingproxy_ne));
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "copy"), rootContext_->fromMethod(nullptr, py_mappingproxy_copy));
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "__or__"), rootContext_->fromMethod(nullptr, py_mappingproxy_or));
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "__ror__"), rootContext_->fromMethod(nullptr, py_mappingproxy_ror));
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "__ior__"), rootContext_->fromMethod(nullptr, py_mappingproxy_ior));
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "__reversed__"), rootContext_->fromMethod(nullptr, py_mappingproxy_reversed));
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "__class_getitem__"), rootContext_->fromMethod(nullptr, py_mappingproxy_class_getitem));
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "__hash__"), rootContext_->fromMethod(nullptr, py_mappingproxy_hash));
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, keysS, rootContext_->fromMethod(nullptr, py_mappingproxy_keys));
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, valuesS, rootContext_->fromMethod(nullptr, py_mappingproxy_values));
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, itemsS, rootContext_->fromMethod(nullptr, py_mappingproxy_items));
    
    // Initialize UnionType
    unionTypePrototype = objectPrototype->newChild(rootContext_, true);
    unionTypePrototype = unionTypePrototype->setAttribute(rootContext_, py_class, typePrototype);
    unionTypePrototype = unionTypePrototype->setAttribute(rootContext_, py_name, PythonEnvironment::getInternedString(rootContext_, "UnionType")->asObject(rootContext_));
    unionTypePrototype = unionTypePrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "__qualname__"), PythonEnvironment::getInternedString(rootContext_, "UnionType")->asObject(rootContext_));
    unionTypePrototype = unionTypePrototype->setAttribute(rootContext_, py_module, builtinsVal);
    unionTypePrototype = unionTypePrototype->setAttribute(rootContext_, py_repr, rootContext_->fromMethod(nullptr, py_union_type_repr));
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, getItemString, rootContext_->fromMethod(nullptr, py_mappingproxy_getitem));
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "__contains__"), rootContext_->fromMethod(nullptr, py_mappingproxy_contains));
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "get"), rootContext_->fromMethod(nullptr, py_mappingproxy_get));
    // SP-C/C3: own-only __iter__ and __len__ so iter(cls.__dict__) and
    // len(cls.__dict__) return the class's own attribute count, matching
    // CPython's mappingproxy semantics.
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, py_iter, rootContext_->fromMethod(nullptr, py_mappingproxy_iter));
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, py_len, rootContext_->fromMethod(nullptr, py_mappingproxy_len));
    mappingProxyPrototype = mappingProxyPrototype->setAttribute(rootContext_, py_module, builtinsVal);

    // Initialize getset_descriptor
    getSetDescriptorPrototype = objectPrototype->newChild(rootContext_, true);
    getSetDescriptorPrototype = getSetDescriptorPrototype->setAttribute(rootContext_, py_class, typePrototype);
    getSetDescriptorPrototype = getSetDescriptorPrototype->setAttribute(rootContext_, py_name, PythonEnvironment::getInternedString(rootContext_, "getset_descriptor")->asObject(rootContext_));
    getSetDescriptorPrototype = getSetDescriptorPrototype->setAttribute(rootContext_, PythonEnvironment::getInternedString(rootContext_, "__qualname__"), PythonEnvironment::getInternedString(rootContext_, "getset_descriptor")->asObject(rootContext_));
    getSetDescriptorPrototype = getSetDescriptorPrototype->setAttribute(rootContext_, py_repr, PythonEnvironment::getInternedString(rootContext_, "<getset_descriptor>")->asObject(rootContext_)); // Placeholder
    getSetDescriptorPrototype = getSetDescriptorPrototype->setAttribute(rootContext_, getDunderString, rootContext_->fromMethod(nullptr, py_getset_get));


    // Register __dict__ on type as a property/descriptor (STEP 15502 FIX)
    // We create an instance of getset_descriptor and set its fget to py_type_get_dict
